-- ════════════════════════════════════════════════════════
-- 245 — Huitième recensement : vingt-cinq maisons, dont les trois
--       marques d'United Cigars (lots d'écriture 15, 16 et 20 à 23)
-- ────────────────────────────────────────────────────────
-- D'OÙ ELLES VIENNENT. Comme la 239 à la 244 : des noms que le marché
-- vend et que l'atlas n'avait pas, passés par le tri, le contradicteur,
-- le rédacteur, la relecture et la traduction.
--   Rép. dominicaine  Artista Cigars (El Artista, Tamboril), Domenico
--                     (Punta Cana) et Eladio Diaz (TDC, Santiago),
--                     usines propres ; Don Emmanuel (TDC), Domaine de
--                     Lavalette (Don Esteban), God of Fire et La Unica
--                     (Tabacalera A. Fuente), Laura Chavin (Altagracia),
--                     Emperors Cut (La Aurora), Firecracker (Magia
--                     Cubana), Gellis Family Cigars (La iSLA), Red
--                     Anchor (Kelner Boutique Factory) et Licenciados
--                     (MATASA), à Santiago ; Onyx (Tabacalera de
--                     García, La Romana) ; Secret Blend of Cuba (ABAM,
--                     Villa Mella) ; Mustique
--   Allemagne         Christo (Bad Lobenstein) et Herr Lehmann (Lahr),
--                     manufactures propres ; Flavoroute
--   Honduras          La Fontana et La Gianna (Diadema, Danlí) ; Las
--                     Cabrillas
--   Nicaragua         El Mago (MGE Cigars Factory, Estelí) ; Fortis
--                     Cigars
--   États-Unis        Drunk Chicken
--
-- ── LE SILENCE ÉCRIT ────────────────────────────────────
-- Cinq fiches : Flavoroute, Mustique, Las Cabrillas, Fortis Cigars et
-- Drunk Chicken. Le propriétaire est identifié et le pays de roulage
-- attesté ; la maison ne nomme pas sa fabrique (décision du
-- 23 septembre). Fortis Cigars dit seulement une collaboration avec
-- A.J. Fernandez, à Estelí.
--
-- ── LES MARQUES D'UN MÊME PROPRIÉTAIRE ──────────────────
-- Firecracker, La Gianna et Red Anchor sont à David Garofalo (United
-- Cigars), roulées dans trois fabriques qu'il ne possède pas : trois
-- fiches, qui se renvoient l'une à l'autre. La ligne United, sans
-- fabrique ni pays lus, n'a pas de fiche ; United Cigars est une
-- mention de Firecracker, La Gianna Havana une mention de La Gianna.
--
-- ── CE QUE LA RELECTURE A TRANCHÉ ───────────────────────
-- Sortent, parce qu'elles ne se vendent plus : Escarabin (six formats
-- épuisés), Joya de la Romana, Ilegal (rien depuis février 2020 ; La
-- Familia, son doublon, avec elle) et Hernandez & Ruiz (épuisée
-- partout, chez son importateur compris). Edition One n'est pas une
-- fiche : son seul cigare, Cloud Hopper, est une ligne de Warped.
-- Domaine de Lavalette sort du silence : Cigarworld.de la dit roulée
-- chez Don Esteban, la fabrique d'Oskar Nausch, à Santiago. Flavoroute se range en Allemagne, où la maison dit son
-- Wildkirsch #1 entièrement fabriqué ; l'Anoroc Puro, shortfiller
-- qu'elle ne dit pas roulé à la main, reste dehors. Emperors Cut se
-- range en République dominicaine : son site ne présente plus que les
-- trois lignes de La Aurora. Firecracker perd une adresse de Gurabo
-- qui ne venait que d'un annuaire de données d'expédition. Secret
-- Blend of Cuba est relue sur les pages de Neptune Cigars : ABAM,
-- roulage à la main, tripe mêlée ; ses quatre vitolas sont en rupture
-- en octobre 2026, sans date de retour depuis octobre 2024, et des
-- avis de clients datent de 2025 : l'état s'écrit. Les lignes perdent
-- le nom de la marque quand il le répète (Christo, Firecracker, La
-- Gianna, Mustique, Onyx, Las Cabrillas, La Fontana, Drunk Chicken).
--
-- ── À LA DÉCISION DE L'UTILISATEUR ──────────────────────
-- Herr Lehmann : la poupée est formée avec une bande de cuir
-- actionnée au pied (Netzwerk Südbaden, mars 2022), la cape posée à la
-- main ; Cigarworld.de classe les cigares totalmente a mano. Le cas
-- rejoint la 51 d'Helvada (244) : la fiche entre, le point est écrit.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Fondations : Laura Chavin, 1992 ou 1998 ; Firecracker, 2006 ou
-- 2007 ; Gellis Family Cigars, 2019 ou 2024 ; Eladio Diaz, 2021 ou
-- 2022 ; La Fontana, Sal Fontana en 1992 ou Tino Argudin, 1993 chez
-- trois détaillants ; Licenciados, 1987, 1988 ou 1989 ; Onyx Reserve,
-- 2000 ou 1990 ; Red Anchor, 1772 pour la maison, 1770 pour le dépôt
-- de la marque selon Cigar Coop. Emperors Cut : Houston ou Atlanta.
-- La Gianna : cape du Maduro mexicaine, équatorienne ou hondurienne
-- selon la date.
--
-- Rejouable : INSERT … ON DUPLICATE KEY UPDATE ; le `brands` des pays
-- touchés est relu en base et réécrit en littéral ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Artista Cigars ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Artista Cigars',
        'dominican',
        '1956 — Ramón « Pulita » Rodríguez, Tamboril',
        'Usine propre — Tabacalera El Artista, Tamboril',
        'artistacigars.com « Factory » (consultée en septembre 2026 : la maison nomme sa fabrique Tabacalera El Artista, dit rouler des cigares dans le Cibao depuis soixante-dix ans et parle d''une troisième génération de propriétaires familiaux, sans donner d''année) ; artistacigars.com « Brands » (consultée en septembre 2026 : catalogue en séries Artista, Factory Classics, Rugged Country, Studio Works et David Ortiz, dont Harvest, Midnight, Buffalo TEN, Big Papi et The Slugger) ; artistacigars.com « Media Portal — ARTISTA CIGARS » (consultée en septembre 2026 : annonces de produits datées de 2022 à 2025) ; cigarworld.de « Artista Cigars » (consultée en septembre 2026 : maison établie en 1956 et basée à Tamboril, dirigée par Radhames « Ram » Rodriguez, présenté comme petit-fils du fondateur) ; premiumcigars.org « The Artisans of Tabacalera El Artista » (consultée en septembre 2026 : fabrique ouverte en 1956 à Tamboril, passée d''El Artista à Artista en 2022 pour sa division premium, Ram Rodriguez entré dans l''entreprise familiale en 2010, entrepôts et autres sites à Moca, La Vega et San Juan, Harvest de corps moyen et Midnight de corps complet, Big Papi pour David Ortiz, ancien joueur de baseball, et The Slugger) ; absolutecigars.com « Dominican Cigar Factories » (consultée en septembre 2026 : Tabacalera El Artista en activité depuis 1956 à Tamboril, fondée par Ramón « Pulita » Rodríguez, dirigée par son fils Radhames Rodríguez) ; stogiepress.com « Cigar News: Artista Cigars Announces Rebrand and New Products » (5 juillet 2022 : El Artista Cigars devient Artista, Ram Rodriguez président, Harvest de force moyenne à cape Sumatra et Midnight corsé à cape Habano équatorien foncé, en robusto et en toro, en boîtes de vingt) ; smokeinn.com « Buy Buffalo Ten Connecticut By El Artista Cigars Online » (consultée en septembre 2026 : Buffalo TEN en trois variétés, dont un Connecticut à cape équatorienne, sous-cape camerounaise, tripe du Nicaragua et des champs dominicains d''El Artista, de force douce à moyenne)',
        '["Big Papi","The Slugger"]',
        'Artista est la maison d''une famille de Tamboril, dans la vallée du Cibao. Cigarworld.de, Premiumcigars.org et Absolutecigars.com datent de 1956 l''ouverture de la fabrique, et Absolutecigars.com nomme son fondateur, Ramón « Pulita » Rodríguez. Sur la page de sa fabrique, la maison la nomme Tabacalera El Artista, dit rouler des cigares dans le Cibao depuis soixante-dix ans et parle d''une troisième génération de propriétaires familiaux ; elle ne donne pas d''année. En septembre 2026, Cigarworld.de présente Radhames « Ram » Rodriguez à sa tête comme petit-fils du fondateur ; Absolutecigars.com le dit fils du fondateur. Selon Premiumcigars.org, il est entré dans l''entreprise familiale en 2010.

Le 5 juillet 2022, Stogie Press annonce que la maison, jusque-là El Artista Cigars, adopte la marque Artista, avec Ram Rodriguez comme président et deux lignes nouvelles, Harvest et Midnight, en robusto et en toro. Premiumcigars.org situe la production principale à Tamboril, avec des entrepôts et d''autres sites à Moca, La Vega et San Juan.

En septembre 2026, le site de la maison range ses cigares en séries — Artista, Factory Classics, Rugged Country, Studio Works et une série David Ortiz — et sa page presse liste des annonces datées de 2022 à 2025. Premiumcigars.org cite Big Papi, fait pour l''ancien joueur de baseball David Ortiz, et The Slugger, sa suite, parmi les cigares que la fabrique produit.',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"Annoncée le 5 juillet 2022 avec Midnight, dit Stogie Press, en robusto et en toro, en boîtes de vingt."},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"Habano équatorien foncé","vitolas":[],"story":"Annoncée le 5 juillet 2022 avec Harvest, dit Stogie Press, en robusto et en toro, en boîtes de vingt ; Premiumcigars.org la range en corps complet."},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne de la série Rugged Country ; en septembre 2026, Smokeinn.com la dit en trois variétés, dont un Connecticut à cape équatorienne, sous-cape camerounaise et tripe du Nicaragua et des champs dominicains de la maison, de force douce à moyenne."}]',
        'Artista is the house of a family from Tamboril, in the Cibao Valley. Cigarworld.de, Premiumcigars.org and Absolutecigars.com date the opening of the factory to 1956, and Absolutecigars.com names its founder, Ramón « Pulita » Rodríguez. On the page for its factory, the house names it Tabacalera El Artista, says it has been rolling cigars in the Cibao for seventy years and speaks of a third generation of family owners; it gives no year. In September 2026, Cigarworld.de presents Radhames « Ram » Rodriguez, at its head, as the founder''s grandson; Absolutecigars.com says he is the founder''s son. According to Premiumcigars.org, he joined the family business in 2010.

On 5 July 2022, Stogie Press announces that the house, until then El Artista Cigars, adopts the Artista brand, with Ram Rodriguez as president and two new lines, Harvest and Midnight, in robusto and toro. Premiumcigars.org places the main production in Tamboril, with warehouses and other sites in Moca, La Vega and San Juan.

In September 2026, the house''s website arranges its cigars in series — Artista, Factory Classics, Rugged Country, Studio Works and a David Ortiz series — and its press page lists announcements dated from 2022 to 2025. Premiumcigars.org cites Big Papi, made for the former baseball player David Ortiz, and The Slugger, its follow-up, among the cigars the factory produces.',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"Announced on 5 July 2022 together with Midnight, says Stogie Press, in robusto and toro, in boxes of twenty."},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"Dark Ecuadorian Habano","vitolas":[],"story":"Announced on 5 July 2022 together with Harvest, says Stogie Press, in robusto and toro, in boxes of twenty; Premiumcigars.org classes it as full-bodied."},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line of the Rugged Country series; in September 2026, Smokeinn.com says it comes in three varieties, including a Connecticut with an Ecuadorian wrapper, a Cameroonian binder and a filler from Nicaragua and from the house''s Dominican fields, of mild to medium strength."}]',
        'Artista es la casa de una familia de Tamboril, en el valle del Cibao. Cigarworld.de, Premiumcigars.org y Absolutecigars.com fechan en 1956 la apertura de la fábrica, y Absolutecigars.com nombra a su fundador, Ramón « Pulita » Rodríguez. En la página de su fábrica, la casa la llama Tabacalera El Artista, dice liar puros en el Cibao desde hace setenta años y habla de una tercera generación de propietarios familiares; no da ningún año. En septiembre de 2026, Cigarworld.de presenta a Radhames « Ram » Rodriguez, al frente de la casa, como nieto del fundador; Absolutecigars.com dice que es hijo del fundador. Según Premiumcigars.org, entró en la empresa familiar en 2010.

El 5 de julio de 2022, Stogie Press anuncia que la casa, hasta entonces El Artista Cigars, adopta la marca Artista, con Ram Rodriguez como presidente y dos líneas nuevas, Harvest y Midnight, en robusto y en toro. Premiumcigars.org sitúa la producción principal en Tamboril, con almacenes y otros sitios en Moca, La Vega y San Juan.

En septiembre de 2026, el sitio web de la casa agrupa sus puros en series —Artista, Factory Classics, Rugged Country, Studio Works y una serie David Ortiz— y su página de prensa enumera anuncios fechados de 2022 a 2025. Premiumcigars.org cita Big Papi, hecho para el exjugador de béisbol David Ortiz, y The Slugger, su continuación, entre los puros que produce la fábrica.',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"Anunciada el 5 de julio de 2022 junto con Midnight, dice Stogie Press, en robusto y en toro, en cajas de veinte."},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"Habano ecuatoriano oscuro","vitolas":[],"story":"Anunciada el 5 de julio de 2022 junto con Harvest, dice Stogie Press, en robusto y en toro, en cajas de veinte; Premiumcigars.org la clasifica como de cuerpo completo."},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea de la serie Rugged Country; en septiembre de 2026, Smokeinn.com dice que se ofrece en tres variedades, entre ellas un Connecticut con capa ecuatoriana, capote camerunés y tripa de Nicaragua y de los campos dominicanos de la casa, de fuerza suave a media."}]',
        'Artista ist das Haus einer Familie aus Tamboril im Cibao-Tal. Cigarworld.de, Premiumcigars.org und Absolutecigars.com datieren die Eröffnung der Fabrik auf 1956, und Absolutecigars.com nennt ihren Gründer, Ramón « Pulita » Rodríguez. Auf der Seite zu ihrer Fabrik nennt das Haus sie Tabacalera El Artista, sagt, seit siebzig Jahren im Cibao Zigarren zu rollen, und spricht von einer dritten Generation von Familieneigentümern; ein Jahr nennt es nicht. Im September 2026 stellt Cigarworld.de Radhames « Ram » Rodriguez, an der Spitze des Hauses, als Enkel des Gründers vor; Absolutecigars.com nennt ihn den Sohn des Gründers. Laut Premiumcigars.org ist er 2010 in das Familienunternehmen eingetreten.

Am 5. Juli 2022 kündigt Stogie Press an, dass das Haus, bis dahin El Artista Cigars, die Marke Artista annimmt, mit Ram Rodriguez als Präsident und zwei neuen Linien, Harvest und Midnight, als Robusto und als Toro. Premiumcigars.org verortet die Hauptproduktion in Tamboril, mit Lagerhäusern und weiteren Standorten in Moca, La Vega und San Juan.

Im September 2026 gliedert die Website des Hauses seine Zigarren in Serien — Artista, Factory Classics, Rugged Country, Studio Works und eine Serie David Ortiz — und seine Presseseite listet Ankündigungen auf, die von 2022 bis 2025 datiert sind. Premiumcigars.org nennt Big Papi, gemacht für den ehemaligen Baseballspieler David Ortiz, und The Slugger, dessen Fortsetzung, unter den Zigarren, die die Fabrik herstellt.',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"Am 5. Juli 2022 zusammen mit Midnight angekündigt, so Stogie Press, als Robusto und als Toro, in Kisten zu zwanzig."},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"Habano aus Ecuador, dunkel","vitolas":[],"story":"Am 5. Juli 2022 zusammen mit Harvest angekündigt, so Stogie Press, als Robusto und als Toro, in Kisten zu zwanzig; Premiumcigars.org ordnet sie als vollmundig ein."},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie der Serie Rugged Country; im September 2026 sagt Smokeinn.com, sie gebe es in drei Sorten, darunter ein Connecticut mit Deckblatt aus Ecuador, Umblatt aus Kamerun und Einlage aus Nicaragua und von den dominikanischen Feldern des Hauses, von milder bis mittlerer Stärke."}]',
        'Artista是锡瓦奥谷地坦博里尔一个家族的企业。Cigarworld.de、Premiumcigars.org与Absolutecigars.com均将工厂的开办时间定为1956年，Absolutecigars.com还点明了其创始人，即Ramón « Pulita » Rodríguez。在介绍其工厂的页面上，品牌方称该工厂为Tabacalera El Artista，称自己在锡瓦奥地区卷制雪茄已有七十年，并提到第三代家族所有者；但未给出年份。2026年9月，Cigarworld.de将掌管该企业的Radhames « Ram » Rodriguez介绍为创始人的孙子；Absolutecigars.com则称他是创始人的儿子。据Premiumcigars.org介绍，他于2010年加入家族企业。

2022年7月5日，Stogie Press宣布，该企业此前名为El Artista Cigars，现采用Artista品牌，由Ram Rodriguez出任总裁，并推出Harvest与Midnight两个新系列，规格为robusto与toro。Premiumcigars.org将主要生产地定位于坦博里尔，另在莫卡、拉维加和圣胡安设有仓库及其他场所。

2026年9月，品牌方网站按系列归类其雪茄：Artista、Factory Classics、Rugged Country、Studio Works以及David Ortiz系列；其新闻页面列出了日期为2022年至2025年的公告。Premiumcigars.org在该工厂生产的雪茄中列举了Big Papi（为前棒球运动员David Ortiz制作）及其续作The Slugger。',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"2022年7月5日与Midnight一同宣布，据Stogie Press称，规格为robusto与toro，每盒二十支。"},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"厄瓜多尔深色Habano","vitolas":[],"story":"2022年7月5日与Harvest一同宣布，据Stogie Press称，规格为robusto与toro，每盒二十支；Premiumcigars.org将其归为浓郁型。"},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"未公开","vitolas":[],"story":"Rugged Country系列中的产品线；2026年9月，Smokeinn.com称其共有三款，其中一款为Connecticut，茄衣产自厄瓜多尔，茄套产自喀麦隆，茄芯来自尼加拉瓜及品牌方位于多米尼加的烟田，力度温和至中等。"}]',
        'Artista هي دار عائلة من تامبوريل، في وادي سيباو. يؤرّخ كلٌّ من Cigarworld.de وPremiumcigars.org وAbsolutecigars.com افتتاح المصنع بعام 1956، ويسمّي Absolutecigars.com مؤسسه، وهو Ramón « Pulita » Rodríguez. وفي صفحة مصنعها، تسمّيه الدار Tabacalera El Artista، وتقول إنها تلفّ السيجار في سيباو منذ سبعين عامًا، وتتحدث عن جيل ثالث من الملّاك العائليين؛ ولا تذكر أي سنة. وفي سبتمبر 2026، يقدّم Cigarworld.de الشخص الذي يقود الدار، Radhames « Ram » Rodriguez، بوصفه حفيد المؤسس؛ ويقول Absolutecigars.com إنه ابن المؤسس. وبحسب Premiumcigars.org، انضمّ إلى الشركة العائلية عام 2010.

وفي 5 يوليو 2022، يعلن Stogie Press أن الدار، التي كانت حتى ذلك الحين El Artista Cigars، تعتمد علامة Artista، برئاسة Ram Rodriguez وبخطّين جديدين هما Harvest وMidnight، بمقاسَي robusto وtoro. ويحدّد Premiumcigars.org الإنتاج الرئيسي في تامبوريل، مع مستودعات ومواقع أخرى في موكا ولا فيغا وسان خوان.

وفي سبتمبر 2026، يصنّف موقع الدار سيجارها في سلاسل — Artista وFactory Classics وRugged Country وStudio Works وسلسلة David Ortiz — وتسرد صفحتها الصحفية إعلانات مؤرّخة من 2022 إلى 2025. ويذكر Premiumcigars.org Big Papi، المصنوع للاعب البيسبول السابق David Ortiz، وThe Slugger، تتمّته، ضمن السيجار الذي ينتجه المصنع.',
        '[{"name":"Harvest","color":"#A0522D","force":"Medium","wrapper":"Sumatra","vitolas":[],"story":"أُعلن عنه في 5 يوليو 2022 مع Midnight، بحسب Stogie Press، بمقاسَي robusto وtoro، في علب من عشرين قطعة."},{"name":"Midnight","color":"#6B4226","force":"Full","wrapper":"Habano إكوادوري داكن","vitolas":[],"story":"أُعلن عنه في 5 يوليو 2022 مع Harvest، بحسب Stogie Press، بمقاسَي robusto وtoro، في علب من عشرين قطعة؛ ويصنّفه Premiumcigars.org ضمن فئة الجسم الكامل."},{"name":"Buffalo TEN","color":"#C9A96E","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط من سلسلة Rugged Country؛ وفي سبتمبر 2026، يقول Smokeinn.com إنه يأتي في ثلاثة أنواع، منها Connecticut بغلاف إكوادوري ورباط كاميروني وحشوة من نيكاراغوا ومن حقول الدار الدومينيكية، بقوة خفيفة إلى متوسطة."}]')
