-- ── Domaine de Lavalette ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Domaine de Lavalette',
        'dominican',
        'Non précisée — Tabac Benden, Düsseldorf',
        'Chez Tabacalera Don Esteban (Oskar Nausch), Santiago de los Caballeros (République dominicaine)',
        'cigarworld.de « Kontakt » (consultée en septembre 2026 : site exploité par Tabac Benden GmbH, Burghofstr. 28, 40223 Düsseldorf) ; cigarworld.de « Domaine de Lavalette: Buy Cigars and Cigarillos » (consultée en septembre 2026 : marque maison de Cigarworld.de, achats en grandes quantités directement au fabricant, vente sans boîte, séries Classic, Premium Connecticut et Premium Maduro roulées à la main en République dominicaine, série Honduras d''une tabacalera non nommée) ; cigarworld.de « Domaine de Lavalette Classic Robusto » (consultée en septembre 2026 : fiche technique nommant la Tabacalera Don Esteban, Tabac Benden GmbH désignée comme fabricant et importateur, cape, sous-cape et tripe de République dominicaine, tripe mixte, au catalogue depuis le 21 décembre 2002) ; cigarworld.de « Domaine de Lavalette Premium Robusto (blaue Bauchbinde) » (consultée en septembre 2026 : fiche technique nommant la Tabacalera Don Esteban, tripe de feuilles entières, au catalogue depuis le 2 septembre 2002) ; cigarworld.de « Domaine de Lavalette Premium Maduro Robusto » (consultée en septembre 2026 : fiche technique nommant la Tabacalera Don Esteban, tripe de feuilles entières, au catalogue depuis le 20 novembre 2009) ; cigarworld.de « Domaine de Lavalette Classic (Grey) » (consultée en septembre 2026 : série au catalogue depuis le 17 décembre 2002, onze formats, cape Connecticut Shade claire, sous-cape et tripe dominicaines, douce, tripe mixte de morceaux de feuilles, roulée à la main en République dominicaine) ; cigarworld.de « Buy Domaine de Lavalette Premium (Blue) cigars » (consultée en septembre 2026 : série Premium Connecticut au catalogue depuis le 30 août 2002, sept formats, cape Connecticut claire, sous-cape et tripe dominicaines, très douce, roulée par le même producteur que les séries Premium Maduro et Classic) ; cigarworld.de « Buy Domaine de Lavalette Premium Maduro cigars » (consultée en septembre 2026 : série au catalogue depuis le 20 novembre 2009, cinq formats, cape Maduro foncée, sous-cape et tripe dominicaines, douce, même fabricant que les séries Premium Connecticut et Classic) ; cigarworld.de « Buy Domaine de Lavalette Honduras (Yellow) cigars » (consultée en septembre 2026 : série au catalogue depuis le 17 août 2003, six formats, tripes de feuilles entières seulement depuis 2017) ; cigarworld.de « Buy Domaine de Lavalette Nicaragua cigars » (consultée en septembre 2026 : série au catalogue depuis le 30 juin 2010, variantes Rico, Suave, Maduro et Oscuro, roulées à la main) ; cigarworld.de « Buy Domaine de Lavalette Panama (Green) cigars » (consultée en septembre 2026 : série au catalogue depuis le 24 avril 2012, six formats, roulée à la main, rangée parmi les cigares du Panama) ; hacico.de « Domaine de Lavalette » (consultée en septembre 2026 : site exploité par Tabac Benden GmbH ; série Honduras d''une fabrique respectée, série Nicaragua d''une fabrique renommée qui la vend d''ordinaire sous un autre nom, série Panama roulée avec du tabac du Panama) ; presidencia.gob.do « República Dominicana presenta lo mejor de la oferta exportable en cigarros en InterTabac, en Alemania » (18 septembre 2023 : la Tabacalera Don Esteban figure parmi les entreprises dominicaines présentes à InterTabac 2023, sans ville) ; cigarworld.de « Capadura » (lu le 1er octobre 2026, en anglais : Oskar Nausch exploite la Tabacalera Don Esteban à Santiago de los Caballeros, où se roulent Capadura et Samana)',
        NULL,
        'Domaine de Lavalette est la marque maison de Tabac Benden GmbH, société de Düsseldorf qui exploite Cigarworld.de et Hacico.de. La maison ne date pas la création de la marque ; Cigarworld.de en a ajouté les séries à son catalogue entre août 2002 et avril 2012, et les tient toutes en septembre 2026.

Selon la maison, elle achète en grandes quantités directement au fabricant et vend la marque sans boîte. Elle dit rouler à la main, en République dominicaine, ses séries Classic, Premium Connecticut et Premium Maduro, chez le même producteur : les fiches techniques des trois séries nomment la Tabacalera Don Esteban, qu''Oskar Nausch exploite à Santiago de los Caballeros, dit Cigarworld.de. Le 18 septembre 2023, la présidence de la République dominicaine cite la Tabacalera Don Esteban parmi les entreprises dominicaines présentes à InterTabac 2023, en Allemagne.

D''après la maison, la Classic a une cape Connecticut Shade claire et une tripe mixte de morceaux de feuilles ; les deux Premium, une tripe de feuilles entières, sous une cape Connecticut claire pour l''une et Maduro pour l''autre. La série Honduras vient d''une tabacalera que la maison ne nomme pas ; la série n''offre que des tripes de feuilles entières depuis 2017. La maison dit tenir la série Nicaragua d''une fabrique qu''elle ne nomme pas et qui vend d''ordinaire la série sous un autre nom, et rouler la série Panama avec du tabac venu du Panama.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Onze formats, au catalogue depuis le 17 décembre 2002 ; la maison la dit douce, à cape Connecticut Shade claire, sous-cape et tripe dominicaines, la tripe mêlant des morceaux de feuilles."},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"Sept formats, au catalogue depuis le 30 août 2002 ; la maison la dit très douce, à cape Connecticut claire, sous-cape et tripe de feuilles entières dominicaines."},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"Cinq formats, au catalogue depuis le 20 novembre 2009 ; la maison la dit douce, à cape Maduro foncée, sous-cape et tripe de feuilles entières dominicaines."},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Six formats, au catalogue depuis le 17 août 2003 ; la maison dit la tenir d''une tabacalera qu''elle ne nomme pas, et la série n''offre que des tripes de feuilles entières depuis 2017."},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Roulée à la main, en versions Rico, Suave, Maduro et Oscuro, au catalogue depuis le 30 juin 2010 ; la maison dit la tenir d''une fabrique qu''elle ne nomme pas."},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Six formats roulés à la main, au catalogue depuis le 24 avril 2012 ; la maison dit la rouler avec du tabac venu directement du Panama."}]',
        'Domaine de Lavalette is the house brand of Tabac Benden GmbH, a Düsseldorf company that operates Cigarworld.de and Hacico.de. The house does not date the creation of the brand; Cigarworld.de added its series to its catalogue between August 2002 and April 2012, and carries them all in September 2026.

According to the house, it buys in large quantities directly from the manufacturer and sells the brand without a box. It says it rolls its Classic, Premium Connecticut and Premium Maduro series by hand, in the Dominican Republic, at the same producer: the technical data sheets of the three series name Tabacalera Don Esteban, which Oskar Nausch operates in Santiago de los Caballeros, says Cigarworld.de. On 18 September 2023, the presidency of the Dominican Republic cites Tabacalera Don Esteban among the Dominican companies present at InterTabac 2023, in Germany.

According to the house, the Classic has a light Connecticut Shade wrapper and a mixed filler of pieces of leaves; the two Premium series have a whole-leaf filler, under a light Connecticut wrapper for one and a Maduro wrapper for the other. The Honduras series comes from a tabacalera that the house does not name; the series has offered only whole-leaf fillers since 2017. The house says it gets the Nicaragua series from a factory that it does not name and that usually sells the series under another name, and rolls the Panama series with tobacco from Panama.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Eleven formats, in the catalogue since 17 December 2002; the house says it is mild, with a light Connecticut Shade wrapper, and Dominican binder and filler, the filler mixing pieces of leaves."},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"Seven formats, in the catalogue since 30 August 2002; the house says it is very mild, with a light Connecticut wrapper and a Dominican binder and whole-leaf filler."},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"Five formats, in the catalogue since 20 November 2009; the house says it is mild, with a dark Maduro wrapper and a Dominican binder and whole-leaf filler."},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Six formats, in the catalogue since 17 August 2003; the house says it gets it from a tabacalera that it does not name, and the series has offered only whole-leaf fillers since 2017."},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Hand-rolled, in Rico, Suave, Maduro and Oscuro versions, in the catalogue since 30 June 2010; the house says it gets it from a factory that it does not name."},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Six formats rolled by hand, in the catalogue since 24 April 2012; the house says it rolls it with tobacco coming directly from Panama."}]',
        'Domaine de Lavalette es la marca propia de Tabac Benden GmbH, empresa de Düsseldorf que gestiona Cigarworld.de y Hacico.de. La casa no fecha la creación de la marca; Cigarworld.de añadió sus series a su catálogo entre agosto de 2002 y abril de 2012, y las tiene todas en septiembre de 2026.

Según la casa, compra en grandes cantidades directamente al fabricante y vende la marca sin caja. Dice liar a mano, en la República Dominicana, sus series Classic, Premium Connecticut y Premium Maduro, con el mismo productor: las fichas técnicas de las tres series nombran la Tabacalera Don Esteban, que Oskar Nausch regenta en Santiago de los Caballeros, dice Cigarworld.de. El 18 de septiembre de 2023, la presidencia de la República Dominicana cita la Tabacalera Don Esteban entre las empresas dominicanas presentes en InterTabac 2023, en Alemania.

Según la casa, la Classic tiene una capa Connecticut Shade clara y una tripa mixta de trozos de hoja; las dos Premium, una tripa de hoja entera, bajo una capa Connecticut clara una y Maduro la otra. La serie Honduras procede de una tabacalera que la casa no nombra; la serie solo ofrece tripas de hoja entera desde 2017. La casa dice obtener la serie Nicaragua de una fábrica que no nombra y que suele vender la serie bajo otro nombre, y liar la serie Panama con tabaco procedente de Panamá.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Once formatos, en catálogo desde el 17 de diciembre de 2002; la casa dice que es suave, con capa Connecticut Shade clara, capote y tripa dominicanos, la tripa con trozos de hoja mezclados."},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"Siete formatos, en catálogo desde el 30 de agosto de 2002; la casa dice que es muy suave, con capa Connecticut clara, capote y tripa de hoja entera dominicanos."},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"Cinco formatos, en catálogo desde el 20 de noviembre de 2009; la casa dice que es suave, con capa Maduro oscura, capote y tripa de hoja entera dominicanos."},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Seis formatos, en catálogo desde el 17 de agosto de 2003; la casa dice obtenerla de una tabacalera que no nombra, y la serie solo ofrece tripas de hoja entera desde 2017."},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Liada a mano, en versiones Rico, Suave, Maduro y Oscuro, en catálogo desde el 30 de junio de 2010; la casa dice obtenerla de una fábrica que no nombra."},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Seis formatos liados a mano, en catálogo desde el 24 de abril de 2012; la casa dice liarla con tabaco procedente directamente de Panamá."}]',
        'Domaine de Lavalette ist die Hausmarke von Tabac Benden GmbH, einem Düsseldorfer Unternehmen, das Cigarworld.de und Hacico.de betreibt. Das Haus datiert die Entstehung der Marke nicht; Cigarworld.de hat ihre Serien zwischen August 2002 und April 2012 in seinen Katalog aufgenommen und führt sie im September 2026 alle.

Laut dem Haus kauft es in großen Mengen direkt beim Hersteller und verkauft die Marke ohne Kiste. Es sagt, seine Serien Classic, Premium Connecticut und Premium Maduro in der Dominikanischen Republik von Hand zu rollen, beim selben Produzenten: Die technischen Datenblätter der drei Serien nennen die Tabacalera Don Esteban, die Oskar Nausch in Santiago de los Caballeros betreibt, so Cigarworld.de. Am 18. September 2023 nennt das Präsidialamt der Dominikanischen Republik die Tabacalera Don Esteban unter den dominikanischen Unternehmen, die auf der InterTabac 2023 in Deutschland vertreten sind.

Nach Angaben des Hauses hat die Classic ein helles Deckblatt Connecticut Shade und eine gemischte Einlage aus Blattstücken; die beiden Premium haben eine Einlage aus ganzen Blättern, unter einem hellen Deckblatt Connecticut die eine und unter einem Deckblatt Maduro die andere. Die Serie Honduras stammt von einer Tabacalera, die das Haus nicht nennt; die Serie bietet seit 2017 nur Einlagen aus ganzen Blättern. Das Haus sagt, die Serie Nicaragua von einer Fabrik zu beziehen, die es nicht nennt und die die Serie üblicherweise unter einem anderen Namen verkauft, und die Serie Panama mit Tabak aus Panama zu rollen.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Elf Formate, seit dem 17. Dezember 2002 im Katalog; das Haus sagt, sie sei mild, mit hellem Deckblatt Connecticut Shade, dominikanischem Umblatt und dominikanischer Einlage, die Einlage aus gemischten Blattstücken."},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"Sieben Formate, seit dem 30. August 2002 im Katalog; das Haus sagt, sie sei sehr mild, mit hellem Deckblatt Connecticut, dominikanischem Umblatt und dominikanischer Einlage aus ganzen Blättern."},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"Fünf Formate, seit dem 20. November 2009 im Katalog; das Haus sagt, sie sei mild, mit dunklem Deckblatt Maduro, dominikanischem Umblatt und dominikanischer Einlage aus ganzen Blättern."},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Sechs Formate, seit dem 17. August 2003 im Katalog; das Haus sagt, sie von einer Tabacalera zu beziehen, die es nicht nennt, und die Serie bietet seit 2017 nur Einlagen aus ganzen Blättern."},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Von Hand gerollt, in den Versionen Rico, Suave, Maduro und Oscuro, seit dem 30. Juni 2010 im Katalog; das Haus sagt, sie von einer Fabrik zu beziehen, die es nicht nennt."},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Sechs von Hand gerollte Formate, seit dem 24. April 2012 im Katalog; das Haus sagt, sie mit Tabak zu rollen, der direkt aus Panama kommt."}]',
        'Domaine de Lavalette是Tabac Benden GmbH的自有品牌，该公司位于杜塞尔多夫，运营着Cigarworld.de与Hacico.de。品牌方未标明该品牌的创立时间；Cigarworld.de于2002年8月至2012年4月间陆续将其各系列加入目录，并于2026年9月全部有售。

据品牌方介绍，其直接向制造商大批量采购，销售该品牌时不带盒。品牌方称其Classic、Premium Connecticut与Premium Maduro系列在多米尼加共和国手工卷制，均出自同一生产商：这三个系列的技术资料页都注明了Tabacalera Don Esteban，据Cigarworld.de称，该厂由Oskar Nausch在圣地亚哥-德洛斯卡瓦列罗斯经营。2023年9月18日，多米尼加共和国总统府在参加德国InterTabac 2023的多米尼加企业中提到了Tabacalera Don Esteban。

据品牌方介绍，Classic采用浅色Connecticut Shade茄衣，配由烟叶碎块组成的混合茄芯；两个Premium系列均采用整叶茄芯，一个配浅色Connecticut茄衣，另一个配Maduro茄衣。Honduras系列来自一家品牌方未透露名称的tabacalera；自2017年起，该系列只提供整叶茄芯。品牌方称，Nicaragua系列来自一家其未透露名称的工厂，该厂通常以另一名称销售该系列；并称Panama系列使用来自巴拿马的烟叶卷制。',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"共十一种规格，自2002年12月17日起列入目录；品牌方称其温和，采用浅色Connecticut Shade茄衣，茄套与茄芯均为多米尼加产，茄芯由烟叶碎块混合而成。"},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"共七种规格，自2002年8月30日起列入目录；品牌方称其非常温和，采用浅色Connecticut茄衣，茄套与整叶茄芯均为多米尼加产。"},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"共五种规格，自2009年11月20日起列入目录；品牌方称其温和，采用深色Maduro茄衣，茄套与整叶茄芯均为多米尼加产。"},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"共六种规格，自2003年8月17日起列入目录；品牌方称该系列来自一家其未透露名称的tabacalera，且自2017年起该系列只提供整叶茄芯。"},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"手工卷制，分Rico、Suave、Maduro与Oscuro版本，自2010年6月30日起列入目录；品牌方称该系列来自一家其未透露名称的工厂。"},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"六种规格，手工卷制，自2012年4月24日起列入目录；品牌方称该系列使用直接来自巴拿马的烟叶卷制。"}]',
        'Domaine de Lavalette هي العلامة الخاصة بشركة Tabac Benden GmbH، وهي شركة في دوسلدورف تدير Cigarworld.de وHacico.de. ولا تؤرّخ الدار إنشاء العلامة؛ وقد أضاف Cigarworld.de سلاسلها إلى كتالوجه بين أغسطس 2002 وأبريل 2012، ويضمّها كلها في سبتمبر 2026.

وبحسب الدار، تشتري بكميات كبيرة مباشرة من الصانع، وتبيع العلامة من دون علبة. وتقول إنها تلفّ يدويًا، في جمهورية الدومينيكان، سلاسلها Classic وPremium Connecticut وPremium Maduro، لدى المنتج نفسه: فالبطاقات الفنية للسلاسل الثلاث تذكر Tabacalera Don Esteban، التي يديرها Oskar Nausch في سانتياغو دي لوس كاباييروس، بحسب Cigarworld.de. وفي 18 سبتمبر 2023، تذكر رئاسة جمهورية الدومينيكان Tabacalera Don Esteban ضمن الشركات الدومينيكية الحاضرة في InterTabac 2023، في ألمانيا.

وبحسب الدار، لدى Classic غلاف Connecticut Shade فاتح وحشوة مختلطة من قطع الأوراق؛ ولدى سلسلتي Premium حشوة من أوراق كاملة، تحت غلاف Connecticut فاتح لإحداهما وMaduro للأخرى. وتأتي سلسلة Honduras من tabacalera لا تسمّيها الدار؛ ولا تقدّم السلسلة منذ عام 2017 سوى حشوات من أوراق كاملة. وتقول الدار إنها تحصل على سلسلة Nicaragua من مصنع لا تسمّيه، وهو يبيع السلسلة عادةً تحت اسم آخر، وإنها تلفّ سلسلة Panama بتبغ قادم من بنما.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"أحد عشر مقاسًا، في الكتالوج منذ 17 ديسمبر 2002؛ وتقول الدار إنها خفيفة، بغلاف Connecticut Shade فاتح ورباط وحشوة دومينيكيين، والحشوة تمزج قطعًا من الأوراق."},{"name":"Premium Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut","vitolas":[],"story":"سبعة مقاسات، في الكتالوج منذ 30 أغسطس 2002؛ وتقول الدار إنها خفيفة جدًا، بغلاف Connecticut فاتح ورباط وحشوة من أوراق كاملة دومينيكيين."},{"name":"Premium Maduro","color":"#4A3728","force":"Mild","wrapper":"Maduro","vitolas":[],"story":"خمسة مقاسات، في الكتالوج منذ 20 نوفمبر 2009؛ وتقول الدار إنها خفيفة، بغلاف Maduro داكن ورباط وحشوة من أوراق كاملة دومينيكيين."},{"name":"Honduras","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"ستة مقاسات، في الكتالوج منذ 17 أغسطس 2003؛ وتقول الدار إنها تحصل عليها من tabacalera لا تسمّيها، ولا تقدّم السلسلة منذ عام 2017 سوى حشوات من أوراق كاملة."},{"name":"Nicaragua","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"مُلفوفة يدويًا، بإصدارات Rico وSuave وMaduro وOscuro، في الكتالوج منذ 30 يونيو 2010؛ وتقول الدار إنها تحصل عليها من مصنع لا تسمّيه."},{"name":"Panama","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"ستة مقاسات مُلفوفة يدويًا، في الكتالوج منذ 24 أبريل 2012؛ وتقول الدار إنها تلفّها بتبغ قادم مباشرة من بنما."}]')
