-- ── God of Fire ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('God of Fire',
        'dominican',
        '2004 — Keith K. Park (Prometheus)',
        'Chez Tabacalera A. Fuente, Santiago de los Caballeros',
        'godoffire.com « Our Story » (lu les 30 septembre et 1er octobre 2026 : Keith K. Park, fondateur et président de Prometheus ; Prometheus fabrique briquets, cendriers et humidors ; documentaire sur la famille Fuente, dont Park est le producteur, tourné au printemps 2002 en République dominicaine, où on l''appelle God of Fire ; Carlito Fuente suggère ce nom de marque ; dîner du printemps 2003 en République dominicaine ; premiers cigares en 2004 avec des humidors de Prometheus en édition limitée ; cigares faits à la main à la Tabacalera A. Fuente y Cia., liant et tripe dominicains, cape variable selon l''assemblage ; année de fabrication sur la seconde bague ; six assemblages ; vingtième anniversaire en 2024) ; godoffire.com « God of Fire KKP Never Back Down » (lu le 30 septembre 2026 : cape VSW de l''étage supérieur, cultivée au Château de la Fuente, liant et tripe dominicains ; Gran Toro 56 et Piramide 58 présentés en 2024 pour le vingtième anniversaire de la marque ; Toro Extra 54 expédiée aux détaillants à l''été 2025 ; Diademas Selection 54, 56 et 60 annoncée pour 2026 ; trente-cinquième anniversaire de Prometheus en 2027) ; godoffire.com « God of Fire KKP Special Reserve » (lu le 30 septembre 2026 : introduite en 2022 pour le trentième anniversaire de Prometheus ; cape VSW de l''étage inférieur, cultivée au Château de la Fuente, liant et tripe dominicains ; Toro Extra 54, Gran Toro 56, Piramide 58 ; Diademas Selection 54, 56 et 60 annoncée pour 2026) ; godoffire.com « God of Fire Serie B » (lu le 30 septembre 2026 : liant et tripe dominicains ; cape Ecuador Sun Grown sur Robusto, Robusto Tubo et Robusto Gordo 54, cape Connecticut Broadleaf Maduro sur Double Robusto, Double Robusto Tubo, Diademas 56 et Gran Toro ; capes sombres) ; godoffire.com « God of Fire Serie Aniversario » (lu le 30 septembre 2026 : cape équatorienne, liant et tripe dominicains ; Aniversario 54, 56 et 60 ; corps moyen pour les 54 et 56) ; godoffire.com « God of Fire By Don Carlos » (lu le 30 septembre 2026 : cape équatorienne, liant et tripe dominicains ; Robusto, Robusto Tubo, Robusto Gordo 54 et Toro ; corps moyen) ; godoffire.com « God of Fire By Carlito » (lu le 30 septembre 2026 : cape du Cameroun, liant et tripe dominicains ; force moyenne à forte ; Double Robusto, Double Robusto Tubo, Piramide, Diademas 56, Churchill et Double Corona) ; en.wikipedia.org « Arturo Fuente » (lu le 1er octobre 2026 : en septembre 1980, Tabacalera A. Fuente ouvre une fabrique de 12 000 pieds carrés à Santiago, en République dominicaine, où la famille Fuente s''installe ; Carlos Fuente Sr. et Carlos Fuente Jr. dirigent l''exploitation) ; halfwheel.com « Prometheus Celebrating God of Fire''s 20th Anniversary With Never Back Down » (page fermée aux robots, lue par son titre : Prometheus fête le vingtième anniversaire de God of Fire avec Never Back Down)',
        NULL,
        'God of Fire est la marque de cigares de Keith K. Park, fondateur et président de Prometheus, maison de briquets, de cendriers et d''humidors qui rêvait de sa propre ligne de cigares, dit la maison. Le nom naît au printemps 2002, sur le tournage en République dominicaine du documentaire The Fuente Family: An American Dream, que Park produisait : on l''y appelait God of Fire, en allusion à Prometheus, et Carlito Fuente lui suggère d''en faire un nom de marque. L''occasion se présente au printemps 2003, lors d''un dîner de Park et de Carlito Fuente en République dominicaine ; les premiers cigares paraissent en 2004, avec des humidors de Prometheus en édition limitée.

Les cigares sont faits à la main à la Tabacalera A. Fuente y Cia., sur liant et tripe dominicains, la cape variant selon l''assemblage, dit la maison ; la fabrique appartient à la famille Fuente, qui l''a ouverte à Santiago de los Caballeros en septembre 1980, dit Wikipédia ; la marque, elle, est à Park. La seconde bague porte l''année de fabrication.

En septembre 2026, la maison compte six assemblages : KKP Never Back Down, KKP Special Reserve, Serie B, Serie Aniversario, By Don Carlos et By Carlito. La Special Reserve naît en 2022 pour le trentième anniversaire de Prometheus, la Never Back Down en 2024 pour le vingtième de la marque ; pour 2026, la maison annonce une Diademas Selection de chacune des deux, avant le trente-cinquième anniversaire de Prometheus, en 2027.',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Gran Toro 56 et Piramide 58 présentés en 2024 pour les vingt ans de la marque, Toro Extra 54 expédiée à l''été 2025, Diademas Selection (54, 56, 60) annoncée pour 2026 ; cape VSW de l''étage supérieur sur liant et tripe dominicains, dit la maison."},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Introduite en 2022 pour les trente ans de Prometheus, en Toro Extra 54, Gran Toro 56 et Piramide 58, avec une Diademas Selection (54, 56, 60) annoncée pour 2026 ; cape VSW de l''étage inférieur sur liant et tripe dominicains, dit la maison."},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Cape Ecuador Sun Grown sur les Robusto, Robusto Tubo et Robusto Gordo 54, Connecticut Broadleaf Maduro sur les Double Robusto, Double Robusto Tubo, Diademas 56 et Gran Toro, sur liant et tripe dominicains ; ligne à cape sombre, dit la maison."},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"Équateur","vitolas":[],"story":"Aniversario 54, 56 et 60, sur liant et tripe dominicains ; corps moyen pour les 54 et 56, goût plus sucré et épicé pour la 60, dit la maison."},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"Équateur","vitolas":[],"story":"Robusto, Robusto Tubo, Robusto Gordo 54 et Toro, sur liant et tripe dominicains ; corps moyen, légèrement sucré et poivré, dit la maison."},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"Cameroun","vitolas":[],"story":"Double Robusto (aussi en tube), Piramide, Diademas 56, Churchill et Double Corona, sur liant et tripe dominicains ; force moyenne à forte, dit la maison."}]',
        'God of Fire is the cigar brand of Keith K. Park, founder and president of Prometheus, a house of lighters, ashtrays and humidors that dreamed of its own line of cigars, says the house. The name was born in spring 2002, during the shooting in the Dominican Republic of the documentary The Fuente Family: An American Dream, which Park was producing: he was called God of Fire there, in allusion to Prometheus, and Carlito Fuente suggested that he make it a brand name. The opportunity came in spring 2003, at a dinner between Park and Carlito Fuente in the Dominican Republic; the first cigars appeared in 2004, with Prometheus humidors in a limited edition.

The cigars are made by hand at Tabacalera A. Fuente y Cia., on a Dominican binder and filler, the wrapper varying with the blend, says the house; the factory belongs to the Fuente family, who opened it in Santiago de los Caballeros in September 1980, says Wikipedia; the brand, for its part, belongs to Park. The second band carries the year of manufacture.

In September 2026, the house has six blends: KKP Never Back Down, KKP Special Reserve, Serie B, Serie Aniversario, By Don Carlos and By Carlito. The Special Reserve was born in 2022 for the thirtieth anniversary of Prometheus, the Never Back Down in 2024 for the twentieth of the brand; for 2026, the house announces a Diademas Selection of each of the two, ahead of the thirty-fifth anniversary of Prometheus, in 2027.',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Gran Toro 56 and Piramide 58 presented in 2024 for the brand''s twenty years, Toro Extra 54 shipped in summer 2025, Diademas Selection (54, 56, 60) announced for 2026; VSW wrapper from the plant''s upper tier on a Dominican binder and filler, says the house."},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Introduced in 2022 for Prometheus''s thirty years, in Toro Extra 54, Gran Toro 56 and Piramide 58, with a Diademas Selection (54, 56, 60) announced for 2026; VSW wrapper from the plant''s lower tier on a Dominican binder and filler, says the house."},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Ecuador Sun Grown wrapper on the Robusto, Robusto Tubo and Robusto Gordo 54, Connecticut Broadleaf Maduro on the Double Robusto, Double Robusto Tubo, Diademas 56 and Gran Toro, on a Dominican binder and filler; a dark-wrapper line, says the house."},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Aniversario 54, 56 and 60, on a Dominican binder and filler; medium body for the 54 and 56, a sweeter and spicier taste for the 60, says the house."},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Robusto, Robusto Tubo, Robusto Gordo 54 and Toro, on a Dominican binder and filler; medium body, slightly sweet and peppery, says the house."},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"Cameroon","vitolas":[],"story":"Double Robusto (also in tube), Piramide, Diademas 56, Churchill and Double Corona, on a Dominican binder and filler; medium to strong strength, says the house."}]',
        'God of Fire es la marca de puros de Keith K. Park, fundador y presidente de Prometheus, casa de encendedores, ceniceros y humidores que soñaba con su propia línea de puros, dice la casa. El nombre nace en la primavera de 2002, durante el rodaje en República Dominicana del documental The Fuente Family: An American Dream, que Park producía: allí lo llamaban God of Fire, en alusión a Prometheus, y Carlito Fuente le sugiere convertirlo en nombre de marca. La ocasión se presenta en la primavera de 2003, en una cena de Park y Carlito Fuente en República Dominicana; los primeros puros aparecen en 2004, con humidores de Prometheus en edición limitada.

Los puros se hacen a mano en la Tabacalera A. Fuente y Cia., sobre capote y tripa dominicanos, con la capa variable según la liga, dice la casa; la fábrica pertenece a la familia Fuente, que la abrió en Santiago de los Caballeros en septiembre de 1980, dice Wikipedia; la marca, en cambio, es de Park. La segunda anilla lleva el año de fabricación.

En septiembre de 2026, la casa cuenta con seis ligas: KKP Never Back Down, KKP Special Reserve, Serie B, Serie Aniversario, By Don Carlos y By Carlito. La Special Reserve nace en 2022 para el trigésimo aniversario de Prometheus, la Never Back Down en 2024 para el vigésimo de la marca; para 2026, la casa anuncia una Diademas Selection de cada una de las dos, antes del trigésimo quinto aniversario de Prometheus, en 2027.',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Gran Toro 56 y Piramide 58 presentados en 2024 para los veinte años de la marca, Toro Extra 54 enviada en el verano de 2025, Diademas Selection (54, 56, 60) anunciada para 2026; capa VSW del piso superior de la planta sobre capote y tripa dominicanos, dice la casa."},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Introducida en 2022 para los treinta años de Prometheus, en Toro Extra 54, Gran Toro 56 y Piramide 58, con una Diademas Selection (54, 56, 60) anunciada para 2026; capa VSW del piso inferior de la planta sobre capote y tripa dominicanos, dice la casa."},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Capa Ecuador Sun Grown en los Robusto, Robusto Tubo y Robusto Gordo 54, Connecticut Broadleaf Maduro en los Double Robusto, Double Robusto Tubo, Diademas 56 y Gran Toro, sobre capote y tripa dominicanos; línea de capa oscura, dice la casa."},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Aniversario 54, 56 y 60, sobre capote y tripa dominicanos; cuerpo medio para las 54 y 56, sabor más dulce y especiado para la 60, dice la casa."},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Robusto, Robusto Tubo, Robusto Gordo 54 y Toro, sobre capote y tripa dominicanos; cuerpo medio, ligeramente dulce y pimentado, dice la casa."},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"Camerún","vitolas":[],"story":"Double Robusto (también en tubo), Piramide, Diademas 56, Churchill y Double Corona, sobre capote y tripa dominicanos; fuerza media a fuerte, dice la casa."}]',
        'God of Fire ist die Zigarrenmarke von Keith K. Park, Gründer und Präsident von Prometheus, einem Haus für Feuerzeuge, Aschenbecher und Humidore, das von einer eigenen Zigarrenlinie träumte, so das Haus. Der Name entsteht im Frühjahr 2002 bei den Dreharbeiten zum Dokumentarfilm The Fuente Family: An American Dream in der Dominikanischen Republik, den Park produzierte: Dort nannte man ihn God of Fire, in Anspielung auf Prometheus, und Carlito Fuente regt an, daraus einen Markennamen zu machen. Die Gelegenheit ergibt sich im Frühjahr 2003 bei einem Abendessen von Park und Carlito Fuente in der Dominikanischen Republik; die ersten Zigarren erscheinen 2004, mit Humidoren von Prometheus in limitierter Auflage.

Die Zigarren werden von Hand in der Tabacalera A. Fuente y Cia. gefertigt, auf dominikanischem Umblatt und dominikanischer Einlage, wobei das Deckblatt je nach Mischung variiert, so das Haus; die Fabrik gehört der Familie Fuente, die sie im September 1980 in Santiago de los Caballeros eröffnete, so Wikipedia; die Marke dagegen gehört Park. Die zweite Bauchbinde trägt das Herstellungsjahr.

Im September 2026 zählt das Haus sechs Mischungen: KKP Never Back Down, KKP Special Reserve, Serie B, Serie Aniversario, By Don Carlos und By Carlito. Die Special Reserve entsteht 2022 zum dreißigsten Jubiläum von Prometheus, die Never Back Down 2024 zum zwanzigsten der Marke; für 2026 kündigt das Haus von beiden je eine Diademas Selection an, vor Prometheus'' fünfunddreißigstem Jubiläum im Jahr 2027.',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"Gran Toro 56 und Piramide 58, 2024 zu den zwanzig Jahren der Marke vorgestellt, Toro Extra 54, im Sommer 2025 ausgeliefert, Diademas Selection (54, 56, 60), für 2026 angekündigt; Deckblatt VSW aus der oberen Blattetage der Pflanze auf dominikanischem Umblatt und dominikanischer Einlage, so das Haus."},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW, Château de la Fuente","vitolas":[],"story":"2022 zu den dreißig Jahren von Prometheus eingeführt, als Toro Extra 54, Gran Toro 56 und Piramide 58, mit einer für 2026 angekündigten Diademas Selection (54, 56, 60); Deckblatt VSW aus der unteren Blattetage der Pflanze auf dominikanischem Umblatt und dominikanischer Einlage, so das Haus."},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Deckblatt Ecuador Sun Grown bei den Robusto, Robusto Tubo und Robusto Gordo 54, Connecticut Broadleaf Maduro bei den Double Robusto, Double Robusto Tubo, Diademas 56 und Gran Toro, auf dominikanischem Umblatt und dominikanischer Einlage; Linie mit dunklem Deckblatt, so das Haus."},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Aniversario 54, 56 und 60, auf dominikanischem Umblatt und dominikanischer Einlage; mittlerer Körper bei der 54 und der 56, süßerer und würzigerer Geschmack bei der 60, so das Haus."},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Robusto, Robusto Tubo, Robusto Gordo 54 und Toro, auf dominikanischem Umblatt und dominikanischer Einlage; mittlerer Körper, leicht süß und pfeffrig, so das Haus."},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"Kamerun","vitolas":[],"story":"Double Robusto (auch in der Tube), Piramide, Diademas 56, Churchill und Double Corona, auf dominikanischem Umblatt und dominikanischer Einlage; mittlere bis kräftige Stärke, so das Haus."}]',
        'God of Fire是Keith K. Park的雪茄品牌。Park是Prometheus的创始人兼总裁，这家公司经营打火机、烟灰缸与雪茄保湿盒，据品牌方称，它一直梦想拥有自己的雪茄产品线。该名称诞生于2002年春，当时在多米尼加共和国拍摄由Park担任制片人的纪录片《The Fuente Family：An American Dream》：人们在那里称他为God of Fire，意指Prometheus，Carlito Fuente则建议他把它用作品牌名。机会出现在2003年春，Park与Carlito Fuente在多米尼加共和国共进晚餐时；首批雪茄于2004年问世，并配有限量版Prometheus保湿盒。

据品牌方称，雪茄在Tabacalera A. Fuente y Cia.手工制作，采用多米尼加茄套与茄芯，茄衣因拼配而异；据Wikipedia介绍，该工厂属于Fuente家族，该家族于1980年9月在圣地亚哥-德洛斯卡瓦列罗斯开设了它；而品牌则属于Park。第二枚雪茄环上印有生产年份。

2026年9月，品牌方共有六款拼配：KKP Never Back Down、KKP Special Reserve、Serie B、Serie Aniversario、By Don Carlos与By Carlito。Special Reserve诞生于2022年，为纪念Prometheus三十周年；Never Back Down诞生于2024年，为纪念品牌二十周年；品牌方宣布将于2026年为这两款各推出一款Diademas Selection，先于2027年Prometheus的三十五周年。',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW，Château de la Fuente","vitolas":[],"story":"2024年为品牌二十周年发布Gran Toro 56与Piramide 58，Toro Extra 54于2025年夏发货，Diademas Selection（54、56、60）宣布将于2026年推出；据品牌方称，茄衣为VSW，取自植株上部叶，配多米尼加茄套与茄芯。"},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW，Château de la Fuente","vitolas":[],"story":"2022年推出，为纪念Prometheus三十周年，规格为Toro Extra 54、Gran Toro 56与Piramide 58，另有一款Diademas Selection（54、56、60）宣布将于2026年推出；据品牌方称，茄衣为VSW，取自植株下部叶，配多米尼加茄套与茄芯。"},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"Robusto、Robusto Tubo与Robusto Gordo 54采用厄瓜多尔Sun Grown茄衣，Double Robusto、Double Robusto Tubo、Diademas 56与Gran Toro采用Connecticut Broadleaf Maduro茄衣，均配多米尼加茄套与茄芯；据品牌方称，该系列为深色茄衣产品线。"},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔","vitolas":[],"story":"据品牌方称，Aniversario 54、56与60配多米尼加茄套与茄芯；54与56醇度中等，60口味更甜、更带香料味。"},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔","vitolas":[],"story":"据品牌方称，Robusto、Robusto Tubo、Robusto Gordo 54与Toro配多米尼加茄套与茄芯；醇度中等，略带甜味与胡椒味。"},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"喀麦隆","vitolas":[],"story":"据品牌方称，Double Robusto（另有管装）、Piramide、Diademas 56、Churchill与Double Corona配多米尼加茄套与茄芯；力度中等至强。"}]',
        'God of Fire هي علامة السيجار التابعة لـKeith K. Park، مؤسس Prometheus ورئيسها، وهي دار للولّاعات ومنافض السجائر وصناديق الترطيب (هيوميدور) كانت تحلم بخط سيجار خاص بها، بحسب الدار. وُلد الاسم في ربيع 2002، أثناء تصوير الفيلم الوثائقي The Fuente Family: An American Dream في جمهورية الدومينيكان، وقد كان Park منتجه: كانوا يلقّبونه هناك God of Fire، في إشارة إلى Prometheus، واقترح عليه Carlito Fuente أن يجعله اسم علامة. وسنحت الفرصة في ربيع 2003، خلال عشاء جمع Park وCarlito Fuente في جمهورية الدومينيكان؛ وظهرت أولى السيجار في 2004، مع صناديق ترطيب من Prometheus بإصدار محدود.

تُصنع السيجار يدويًا في Tabacalera A. Fuente y Cia.، على غلاف داخلي وحشوة دومينيكيَّين، ويتغيّر الغلاف تبعًا للخلطة، كما تقول الدار؛ والمصنع ملك لعائلة Fuente التي افتتحته في سانتياغو دي لوس كاباييروس في سبتمبر 1980، بحسب Wikipedia؛ أما العلامة فهي لـPark. وتحمل الحلقة الثانية سنة الصنع.

وفي سبتمبر 2026، تضم الدار ست خلطات: KKP Never Back Down وKKP Special Reserve وSerie B وSerie Aniversario وBy Don Carlos وBy Carlito. وقد وُلدت Special Reserve عام 2022 بمناسبة الذكرى الثلاثين لـPrometheus، وNever Back Down عام 2024 بمناسبة الذكرى العشرين للعلامة؛ وتعلن الدار لعام 2026 عن Diademas Selection لكل منهما، قبل الذكرى الخامسة والثلاثين لـPrometheus في 2027.',
        '[{"name":"KKP Never Back Down","color":"#8B5A2B","force":null,"wrapper":"VSW، Château de la Fuente","vitolas":[],"story":"قُدِّم Gran Toro 56 وPiramide 58 في 2024 بمناسبة مرور عشرين عامًا على العلامة، وشُحن Toro Extra 54 في صيف 2025، وأُعلن عن Diademas Selection (54، 56، 60) لعام 2026؛ بغلاف VSW من الطبقة العليا من النبتة على غلاف داخلي وحشوة دومينيكيَّين، بحسب الدار."},{"name":"KKP Special Reserve","color":"#8B5A2B","force":null,"wrapper":"VSW، Château de la Fuente","vitolas":[],"story":"أُطلقت في 2022 بمناسبة مرور ثلاثين عامًا على Prometheus، بمقاسات Toro Extra 54 وGran Toro 56 وPiramide 58، مع Diademas Selection (54، 56، 60) أُعلن عنها لعام 2026؛ بغلاف VSW من الطبقة السفلى من النبتة على غلاف داخلي وحشوة دومينيكيَّين، بحسب الدار."},{"name":"Serie B","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"غلاف Sun Grown من الإكوادور على Robusto وRobusto Tubo وRobusto Gordo 54، وغلاف Connecticut Broadleaf Maduro على Double Robusto وDouble Robusto Tubo وDiademas 56 وGran Toro، على غلاف داخلي وحشوة دومينيكيَّين؛ خط بغلاف داكن، بحسب الدار."},{"name":"Serie Aniversario","color":"#A0522D","force":"Medium","wrapper":"الإكوادور","vitolas":[],"story":"Aniversario 54 و56 و60، على غلاف داخلي وحشوة دومينيكيَّين؛ بجسم متوسط لمقاسَي 54 و56، ومذاق أميل إلى الحلاوة والتوابل لمقاس 60، بحسب الدار."},{"name":"By Don Carlos","color":"#A0522D","force":"Medium","wrapper":"الإكوادور","vitolas":[],"story":"Robusto وRobusto Tubo وRobusto Gordo 54 وToro، على غلاف داخلي وحشوة دومينيكيَّين؛ بجسم متوسط وطعم حلو وفلفلي بدرجة خفيفة، بحسب الدار."},{"name":"By Carlito","color":"#8B5A2B","force":"Medium-Full","wrapper":"الكاميرون","vitolas":[],"story":"Double Robusto (وفي أنبوب أيضًا) وPiramide وDiademas 56 وChurchill وDouble Corona، على غلاف داخلي وحشوة دومينيكيَّين؛ بقوة متوسطة إلى قوية، بحسب الدار."}]')
