-- ── Laura Chavin ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Laura Chavin',
        'dominican',
        '1992 ou 1998 — Helmut Bührle, Hochdorf',
        'Chez Tabacalera Altagracia (Günther Schichl), Santiago de los Caballeros — dite aussi Dreamland La Altagracia',
        'laurachavin.de « Über uns - Laura Chavin » (2026-10-01, en allemand : marque fondée en 1992 par Helmut Bührle à Hochdorf, en Souabe ; en 2017, Willi Knopf reprend le patrimoine d''exploitation puis les droits de la marque de la Laura Chavin Cigars GmbH et installe sa Cigar Company à Dielheim, sa ville natale ; édition 2019 ; cigares faits en République dominicaine chez le partenaire exclusif Günther Schichl) ; laurachavin.de « Sansibar - Laura Chavin » (2026-10-01 : puro dominicain créé par les maîtres-mélangeurs de Laura Chavin exclusivement pour la marque Sansibar ; tabacs de 1996/1998 et de 2004/2005, cape de 2008 ; cape, liant et tripe de République dominicaine ; Toro de 19 mm sur 136 mm ; la page ne dit pas Gran Reserva) ; laurachavin.de « Classic - Laura Chavin » (2026-10-01, en allemand : cape de variété Connecticut d''Équateur, liant et tripe dominicains, six tabacs dans la tripe gardés au moins quatre à cinq ans ; huit formats, du No. 33 Corona au No. 99 Fino Largo) ; laurachavin.de « Concours - Laura Chavin » (2026-10-01, en allemand : puro dominicain à l''assemblage tenu secret, conçu pour les dix ans de la marque ; Robusto, Perfecto, Corona, Diadema) ; laurachavin.de « Terre de Mythe - Laura Chavin » (2026-10-01, en allemand : puro dominicain ; Petit Corona, Grand Robusto, Corona Gorda, Perfecto) ; laurachavin.de « Virginy - Laura Chavin » (2026-10-01 : cape d''Équateur, liant et tripe dominicains, tabac Olor Dominican Virgen de Carbonell ; Toro, Belicoso, Lonsdale) ; laurachavin.de « La Ligue des Divins - Laura Chavin » (2026-10-01, en allemand : tabacs du Cibao cultivés vers 800 m d''altitude ; édition 2020 en Toro, Short Churchill et Gran Corona) ; laurachavin.de « La Tentation - Laura Chavin » (2026-10-01 : mini-cigare longfiller roulé à la main, 10 mm sur 60 mm, cape d''Équateur, liant et tripe dominicains) ; laurachavin.de « Invincible - Laura Chavin » (2026-10-01, en allemand : éditions Black et Copper, puros dominicains faits main ; Short Corona, Short Robusto et Gordito de 105 mm) ; cigarjournal.com « Laura Chavin » (communiqué du 25 mars 2019, en allemand : insolvabilité de la Laura Chavin Cigar GmbH en 2017 ; fondation de la Cigar Company de Willi Knopf en janvier 2019 ; Willi Knopf dit avoir conclu un contrat d''exclusivité avec Günther Schichl et sa Tabacalera Altagracia à Santiago de los Caballeros ; lignes Classic, Concours et Terre de Mythe annoncées pour la saison 2019) ; cigarworld.de « Laura Chavin » (2026-10-01, en anglais : marque créée en 1992 par Helmut Bührle, poursuivie depuis 2017 par la Cigar Company Willi Knopf ; cigares faits à la Tabacalera Altagracia, en République dominicaine, sous contrat d''exclusivité ; séries en vente) ; cigarworld.de « Laura Chavin Classic Sansibar Gran Reserva Toro Tubo » (2026-10-01, en anglais : fabricant Tabacalera Altagracia ; cape criollo, liant olor, tripe criollo dominicains ; Toro de 5,5 pouces, calibre 52 ; en stock ; importateur Cigar Company Willi Knopf GmbH, Dielheim ; au catalogue depuis le 7 juillet 2008) ; dalayzigarren.de « Laura Chavin Zigarren » (2026-10-01, en allemand : marque établie en 1998 par Helmut Bührle ; direction de Willi Knopf en 2017 ; fabrication par Günther Schichl et son équipe à la Tabacalera Dreamland La Altagracia, de la culture du tabac au roulage à la main et à l''emballage ; sept séries dont Sansibar, trente références disponibles) ; blog.dalayzigarren.de « DAG Event » (7 septembre 2013, en allemand : Günther Schichl, Oberösterreicher de naissance, à la tête de la Tabacalera Altagracia, à Villa González/Santiago de los Caballeros ; marques DAG et DAG por DAG) ; zigarrenclub.at « Verkostung Tabacalera Altagracia - Der 1. Linzer Zigarren-Club » (28 mars 2010, en allemand : Günther Schichl, 39 ans, copropriétaire haut-autrichien de la Tabacalera) ; smokersplanet.de « Für Connaisseurs und Schatzsucher : Laura Chavin und der Schatz aus der Tube » (2 juin 2020, en allemand : Willi Knopf, nouveau propriétaire de la marque ; Günther Schichel et sa Tabacalera Altagracia responsables du développement et de la construction du cigare Sansibar ; tabacs des millésimes 1996 à 1998, cape de 2008 ; tube en aluminium) ; de.wikipedia.org « Sansibar (Sylt) » (2026-10-01, en allemand : restaurant de Sylt, entre Rantum et Hörnum ; boutiques vendant une collection de mode, chaussures, sacs, accessoires et vins ; fondé par Herbert Seckler, transmis à son fils Niklas en 2022)',
        '["Sansibar"]',
        'Laura Chavin est une marque allemande fondée en 1992 par Helmut Bührle, à Hochdorf, en Souabe, dit la maison ; Cigarworld.de donne la même année, Dalay Zigarren la dit établie en 1998. En 2017, Willi Knopf reprend le patrimoine d''exploitation, puis les droits de la marque, de la Laura Chavin Cigars GmbH, dont l''insolvabilité date de la même année, et installe sa Cigar Company à Dielheim, sa ville natale, dit la maison. Un communiqué de mars 2019 date de janvier 2019 la fondation de cette société ; une édition 2019 ouvre, dit la maison, une nouvelle époque de la marque.

Les cigares sont faits en République dominicaine chez le partenaire exclusif de la maison, Günther Schichl, Autrichien natif de Haute-Autriche, à la Tabacalera Altagracia, à Santiago de los Caballeros, que Dalay Zigarren appelle Tabacalera Dreamland La Altagracia ; Willi Knopf dit avoir conclu avec lui un contrat d''exclusivité. Sansibar, restaurant de l''île de Sylt dont les boutiques vendent aussi une collection de mode, fait rouler chez Laura Chavin un puro dominicain, que Cigarworld.de nomme Gran Reserva ; les maîtres-mélangeurs de la maison l''ont créé pour elle seule, avec des tabacs de 1996-1998 et de 2004-2005, dit la maison.

En octobre 2026, le site de la maison présente sept séries : Classic, Concours, Terre de Mythe, Virginy, La Ligue des Divins, La Tentation et Invincible, la Sansibar ayant sa page à part.',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Cape de variété Connecticut d''Équateur sur liant et tripe dominicains, six tabacs dans la tripe gardés au moins quatre à cinq ans ; huit formats, du No. 33 Corona au No. 99 Fino Largo, dit la maison."},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"Dominicaine","vitolas":[],"story":"Puro dominicain à l''assemblage tenu secret, conçu pour les dix ans de la marque d''après le mélange de l''ancien Concours ; Robusto, Perfecto, Corona et Diadema, dit la maison."},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"Dominicaine","vitolas":[],"story":"Puro dominicain en Petit Corona, Grand Robusto, Corona Gorda et Perfecto, aux facettes sensorielles changeantes, dit la maison."},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"Équateur","vitolas":[],"story":"Cape d''Équateur sur liant et tripe dominicains, avec le tabac Olor Dominican Virgen de Carbonell ; Toro (No. 1), Belicoso (No. 2) et Lonsdale (No. 3), dit la maison."},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Tabacs cultivés vers 800 m d''altitude dans le Cibao ; édition 2020 en Toro, Short Churchill et Gran Corona, dit la maison."},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"Équateur","vitolas":[],"story":"Mini-cigare longfiller roulé à la main, de 10 mm sur 60 mm, cape d''Équateur sur liant et tripe dominicains, dit la maison."}]',
        'Laura Chavin is a German brand founded in 1992 by Helmut Bührle, in Hochdorf, in Swabia, says the house; Cigarworld.de gives the same year, and Dalay Zigarren says it was established in 1998. In 2017, Willi Knopf took over the operating assets, then the rights to the brand, of Laura Chavin Cigars GmbH, whose insolvency dates from the same year, and set up his Cigar Company in Dielheim, his home town, says the house. A press release of March 2019 dates the founding of this company to January 2019; a 2019 edition opens, says the house, a new era for the brand.

The cigars are made in the Dominican Republic with the house''s exclusive partner, Günther Schichl, an Austrian native of Upper Austria, at the Tabacalera Altagracia, in Santiago de los Caballeros, which Dalay Zigarren calls Tabacalera Dreamland La Altagracia; Willi Knopf says he has concluded an exclusivity contract with him. Sansibar, a restaurant on the island of Sylt whose shops also sell a fashion collection, has a Dominican puro rolled at Laura Chavin, which Cigarworld.de names Gran Reserva; the house''s master blenders created it for Sansibar alone, with tobaccos from 1996-1998 and from 2004-2005, says the house.

In October 2026, the house''s website presents seven series: Classic, Concours, Terre de Mythe, Virginy, La Ligue des Divins, La Tentation and Invincible, with the Sansibar on a page of its own.',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Wrapper of the Connecticut variety from Ecuador on a Dominican binder and filler, six tobaccos in the filler kept for at least four to five years; eight formats, from No. 33 Corona to No. 99 Fino Largo, says the house."},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"Dominican","vitolas":[],"story":"Dominican puro with a secret blend, created to mark the brand''s ten years, modelled on the blend of the former Concours; Robusto, Perfecto, Corona and Diadema, says the house."},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"Dominican","vitolas":[],"story":"Dominican puro in Petit Corona, Grand Robusto, Corona Gorda and Perfecto, with changing sensory facets, says the house."},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Wrapper from Ecuador on a Dominican binder and filler, with the Olor Dominican Virgen de Carbonell tobacco; Toro (No. 1), Belicoso (No. 2) and Lonsdale (No. 3), says the house."},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Tobaccos grown at about 800 m altitude in the Cibao; 2020 edition in Toro, Short Churchill and Gran Corona, says the house."},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Hand-rolled longfiller mini-cigar, 10 mm by 60 mm, wrapper from Ecuador on a Dominican binder and filler, says the house."}]',
        'Laura Chavin es una marca alemana fundada en 1992 por Helmut Bührle, en Hochdorf, en Suabia, dice la casa; Cigarworld.de da el mismo año, y Dalay Zigarren la da por establecida en 1998. En 2017, Willi Knopf se hace cargo de los activos de explotación y luego de los derechos de la marca de Laura Chavin Cigars GmbH, cuya insolvencia data del mismo año, e instala su Cigar Company en Dielheim, su ciudad natal, dice la casa. Un comunicado de marzo de 2019 sitúa en enero de 2019 la fundación de esta empresa; una edición 2019 abre, dice la casa, una nueva época de la marca.

Los puros se hacen en República Dominicana con el socio exclusivo de la casa, Günther Schichl, austriaco natural de la Alta Austria, en la Tabacalera Altagracia, en Santiago de los Caballeros, que Dalay Zigarren llama Tabacalera Dreamland La Altagracia; Willi Knopf dice haber concluido con él un contrato de exclusividad. Sansibar, restaurante de la isla de Sylt cuyas tiendas venden también una colección de moda, hace liar en Laura Chavin un puro dominicano, que Cigarworld.de llama Gran Reserva; los maestros mezcladores de la casa lo crearon solo para Sansibar, con tabacos de 1996-1998 y de 2004-2005, dice la casa.

En octubre de 2026, el sitio web de la casa presenta siete series: Classic, Concours, Terre de Mythe, Virginy, La Ligue des Divins, La Tentation e Invincible, con la Sansibar en una página aparte.',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Capa de variedad Connecticut de Ecuador sobre capote y tripa dominicanos, seis tabacos en la tripa guardados durante un mínimo de cuatro a cinco años; ocho formatos, del No. 33 Corona al No. 99 Fino Largo, dice la casa."},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"Dominicana","vitolas":[],"story":"Puro dominicano de liga mantenida en secreto, concebido para los diez años de la marca a partir de la mezcla del antiguo Concours; Robusto, Perfecto, Corona y Diadema, dice la casa."},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"Dominicana","vitolas":[],"story":"Puro dominicano en Petit Corona, Grand Robusto, Corona Gorda y Perfecto, de facetas sensoriales cambiantes, dice la casa."},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Capa de Ecuador sobre capote y tripa dominicanos, con el tabaco Olor Dominican Virgen de Carbonell; Toro (No. 1), Belicoso (No. 2) y Lonsdale (No. 3), dice la casa."},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Tabacos cultivados a unos 800 m de altitud en el Cibao; edición 2020 en Toro, Short Churchill y Gran Corona, dice la casa."},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Mini puro longfiller liado a mano, de 10 mm por 60 mm, capa de Ecuador sobre capote y tripa dominicanos, dice la casa."}]',
        'Laura Chavin ist eine deutsche Marke, 1992 von Helmut Bührle in Hochdorf in Schwaben gegründet, so das Haus; Cigarworld.de nennt dasselbe Jahr, Dalay Zigarren sagt, sie sei 1998 gegründet worden. 2017 übernimmt Willi Knopf das Betriebsvermögen und dann die Markenrechte der Laura Chavin Cigars GmbH, deren Insolvenz aus demselben Jahr stammt, und richtet seine Cigar Company in Dielheim ein, seiner Heimatstadt, so das Haus. Eine Pressemitteilung vom März 2019 datiert die Gründung dieser Gesellschaft auf Januar 2019; eine Edition 2019 eröffnet, so das Haus, eine neue Epoche der Marke.

Die Zigarren werden in der Dominikanischen Republik beim exklusiven Partner des Hauses hergestellt, Günther Schichl, einem aus Oberösterreich gebürtigen Österreicher, in der Tabacalera Altagracia in Santiago de los Caballeros, die Dalay Zigarren Tabacalera Dreamland La Altagracia nennt; Willi Knopf sagt, mit ihm einen Exklusivvertrag geschlossen zu haben. Sansibar, ein Restaurant auf der Insel Sylt, dessen Boutiquen auch eine Modekollektion verkaufen, lässt bei Laura Chavin einen dominikanischen Puro rollen, den Cigarworld.de Gran Reserva nennt; die Master-Blender des Hauses haben ihn allein für Sansibar geschaffen, mit Tabaken aus den Jahren 1996-1998 und 2004-2005, so das Haus.

Im Oktober 2026 zeigt die Website des Hauses sieben Serien: Classic, Concours, Terre de Mythe, Virginy, La Ligue des Divins, La Tentation und Invincible; die Sansibar hat eine eigene Seite.',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Deckblatt der Sorte Connecticut aus Ecuador auf dominikanischem Umblatt und dominikanischer Einlage, sechs Tabake in der Einlage, mindestens vier bis fünf Jahre gelagert; acht Formate, vom No. 33 Corona bis zum No. 99 Fino Largo, so das Haus."},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"Dominikanisch","vitolas":[],"story":"Dominikanischer Puro mit geheim gehaltener Mischung, anlässlich der zehn Jahre der Marke nach der Mischung des früheren Concours entworfen; Robusto, Perfecto, Corona und Diadema, so das Haus."},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"Dominikanisch","vitolas":[],"story":"Dominikanischer Puro in Petit Corona, Grand Robusto, Corona Gorda und Perfecto, mit wechselnden sensorischen Facetten, so das Haus."},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Deckblatt aus Ecuador auf dominikanischem Umblatt und dominikanischer Einlage, mit dem Tabak Olor Dominican Virgen de Carbonell; Toro (No. 1), Belicoso (No. 2) und Lonsdale (No. 3), so das Haus."},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Tabake, auf etwa 800 m Höhe im Cibao angebaut; Edition 2020 als Toro, Short Churchill und Gran Corona, so das Haus."},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Mini-Zigarre als Longfiller, von Hand gerollt, 10 mm mal 60 mm, Deckblatt aus Ecuador auf dominikanischem Umblatt und dominikanischer Einlage, so das Haus."}]',
        'Laura Chavin是一个德国品牌，据品牌方称，由Helmut Bührle于1992年在施瓦本的霍赫多夫（Hochdorf）创立；Cigarworld.de给出的是同一年份，Dalay Zigarren则称其成立于1998年。2017年，Willi Knopf从Laura Chavin Cigars GmbH接手了经营性资产，继而接手了品牌权利，该公司无力偿债的时间也在同一年；他在家乡迪尔海姆设立了自己的Cigar Company，品牌方如是说。2019年3月的一份新闻稿将这家公司的成立时间定在2019年1月；品牌方称，一款2019年版开启了品牌的新时期。

雪茄在多米尼加共和国制作，合作方为品牌方的独家合作伙伴Günther Schichl——出生于上奥地利的奥地利人——地点在圣地亚哥-德洛斯卡瓦列罗斯的Tabacalera Altagracia，Dalay Zigarren称其为Tabacalera Dreamland La Altagracia；Willi Knopf称，他已与其订立独家合同。Sansibar是叙尔特岛上的一家餐厅，其旗下商店还出售一个时装系列；它委托Laura Chavin卷制一款多米尼加puro，Cigarworld.de称之为Gran Reserva；品牌方的调配大师专为Sansibar创制了这款雪茄，采用1996-1998年和2004-2005年的烟叶，品牌方如是说。

2026年10月，品牌方网站展示七个系列：Classic、Concours、Terre de Mythe、Virginy、La Ligue des Divins、La Tentation与Invincible，Sansibar另有专页。',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"据品牌方称，茄衣为厄瓜多尔Connecticut品种，配多米尼加茄套与茄芯，茄芯含六种烟叶，至少存放四至五年；共八种规格，从No. 33 Corona到No. 99 Fino Largo。"},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"多米尼加","vitolas":[],"story":"据品牌方称，这是一款多米尼加puro，拼配保密，为品牌十周年依照旧版Concours的拼配创制；规格有Robusto、Perfecto、Corona与Diadema。"},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"多米尼加","vitolas":[],"story":"据品牌方称，多米尼加puro，规格有Petit Corona、Grand Robusto、Corona Gorda与Perfecto，感官层面特征多变。"},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"厄瓜多尔","vitolas":[],"story":"据品牌方称，茄衣来自厄瓜多尔，配多米尼加茄套与茄芯，并使用Olor Dominican Virgen de Carbonell烟叶；规格有Toro（No. 1）、Belicoso（No. 2）与Lonsdale（No. 3）。"},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"据品牌方称，烟叶种植于锡瓦奥海拔约800 m处；2020年版推出Toro、Short Churchill与Gran Corona规格。"},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"厄瓜多尔","vitolas":[],"story":"据品牌方称，这是一款手工卷制的longfiller迷你雪茄，10 mm × 60 mm，茄衣来自厄瓜多尔，配多米尼加茄套与茄芯。"}]',
        'Laura Chavin علامة ألمانية تأسست عام 1992 على يد Helmut Bührle في هوخدورف (Hochdorf) في شوابيا، بحسب الدار؛ ويذكر Cigarworld.de السنة نفسها، بينما يقول Dalay Zigarren إنها أُسّست عام 1998. وفي 2017، تولّى Willi Knopf الأصول التشغيلية ثم حقوق العلامة من Laura Chavin Cigars GmbH، التي يعود إعسارها إلى السنة نفسها، وأقام شركته Cigar Company في ديلهايم (Dielheim)، مسقط رأسه، بحسب الدار. ويؤرّخ بيان صحفي صدر في مارس 2019 تأسيس هذه الشركة بيناير 2019؛ وتقول الدار إن إصدار 2019 يفتتح حقبة جديدة للعلامة.

تُصنع السيجار في جمهورية الدومينيكان لدى الشريك الحصري للدار، Günther Schichl، النمساوي المولود في النمسا العليا، في Tabacalera Altagracia في سانتياغو دي لوس كاباييروس، وهي ما يسمّيه Dalay Zigarren Tabacalera Dreamland La Altagracia؛ ويقول Willi Knopf إنه أبرم معه عقدًا حصريًا. أما Sansibar، وهو مطعم في جزيرة زولت تبيع متاجره أيضًا مجموعة أزياء، فيُلفّ له لدى Laura Chavin puro دومينيكي، يسمّيه Cigarworld.de Gran Reserva؛ وقد ابتكره أساتذة المزج لدى الدار حصريًا لـSansibar، بتبغ من 1996-1998 ومن 2004-2005، بحسب الدار.

وفي أكتوبر 2026، يعرض موقع الدار سبع سلاسل: Classic وConcours وTerre de Mythe وVirginy وLa Ligue des Divins وLa Tentation وInvincible، مع صفحة مستقلة لـSansibar.',
        '[{"name":"Classic","color":"#C9A96E","force":null,"wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"غلاف من صنف Connecticut من الإكوادور على غلاف داخلي وحشوة دومينيكيَّين، وستة أنواع من التبغ في الحشوة تُحفظ أربع إلى خمس سنوات على الأقل؛ وثمانية مقاسات، من No. 33 Corona إلى No. 99 Fino Largo، بحسب الدار."},{"name":"Concours","color":"#8B5A2B","force":null,"wrapper":"دومينيكي","vitolas":[],"story":"puro دومينيكي بخلطة تُحفظ سرًّا، صُمّم بمناسبة مرور عشر سنوات على العلامة استنادًا إلى خلطة Concours السابق؛ بمقاسات Robusto وPerfecto وCorona وDiadema، بحسب الدار."},{"name":"Terre de Mythe","color":"#8B5A2B","force":null,"wrapper":"دومينيكي","vitolas":[],"story":"puro دومينيكي بمقاسات Petit Corona وGrand Robusto وCorona Gorda وPerfecto، بأوجه حسّية متغيّرة، بحسب الدار."},{"name":"Virginy","color":"#A0522D","force":null,"wrapper":"الإكوادور","vitolas":[],"story":"غلاف من الإكوادور على غلاف داخلي وحشوة دومينيكيَّين، مع تبغ Olor Dominican Virgen de Carbonell؛ بمقاسات Toro (No. 1) وBelicoso (No. 2) وLonsdale (No. 3)، بحسب الدار."},{"name":"La Ligue des Divins","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تبغ يُزرع على ارتفاع نحو 800 m في سيباو؛ وإصدار 2020 بمقاسات Toro وShort Churchill وGran Corona، بحسب الدار."},{"name":"La Tentation","color":"#A0522D","force":null,"wrapper":"الإكوادور","vitolas":[],"story":"سيجار longfiller مصغّر يُلفّ يدويًا، بقياس 10 mm × 60 mm، بغلاف من الإكوادور على غلاف داخلي وحشوة دومينيكيَّين، بحسب الدار."}]')
