-- ── Mustique ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Mustique',
        'dominican',
        'Non précisée — Kopp Tobaccos, Rellingen',
        'République dominicaine — la maison ne nomme pas sa fabrique',
        'kopp-tobaccos.com « Serienauswahl - Kopp Tobaccos » (page Mustique, 2026-10-01, en allemand : la maison dit avoir composé elle-même les blends ; cigares roulés à la main par les employés d''un producteur de cigares qu''elle ne nomme pas ; la page ne dit ni le pays ni la fabrique ; trois lignes, Amber, Blue et Red ; marque dite sûre dès le départ de s''imposer sur le marché des bundles) ; kopp-tobaccos.com « Über uns - Kopp Tobaccos » (2026-10-01, en allemand : Kopp Tobaccos GmbH & Co. KG, Adlerstrasse 50-56, 25462 Rellingen ; Oliver et Thilo Kopp propriétaires depuis début 2023, la société portant dès lors le nom Kopp Tobaccos) ; kopp-companies.com « Über uns - kopp-companies.com » (2026-10-01, en allemand : la société s''appelait Kohlhase & Kopp ; les frères Kohlhase la quittent au 31 décembre 2022 ; Oliver et Thilo Kopp seuls propriétaires depuis début 2023, la société portant dès lors le nom Kopp Tobaccos) ; noblego.de « Mustique Zigarren online bei Noblego kaufen » (2026-10-01, en allemand : mediumfillers faits en République dominicaine pour le compte du distributeur Kohlhase et Kopp, qui a composé les blends et les a optimisés pour le marché allemand ; tous roulés à la main ; Blue à cape Connecticut Shade, liant et tripe dominicains, force douce ; Red à cape d''Équateur, liant du Nicaragua, tripe dominicaine et brésilienne, force douce ; Amber du Honduras à cape du Honduras, liant et tripe du Nicaragua, force moyenne ; vente en bundles, plusieurs Amber épuisées) ; cigarworld.de « Buy Mustique Blue cigars » (2026-10-01, en anglais : cape Connecticut Shade dorée, liant et tripe dominicains choisis pour le marché allemand par l''importateur Kohlhase & Kopp, Rellingen ; cigare fait à la main de type mediumfiller, ligne légère, sœur de la Red ; bundles de dix sous cellophane ; au catalogue depuis le 1er octobre 2008 ; légende de fabrication : TAF, entièrement à la main mais à tripe déchirée ; Amber, variante du Honduras, ajoutée en septembre 2015) ; cigarworld.de « Buy Mustique Red cigars » (2026-10-01, en anglais : ancienne série Bundles B ; cape Sun Grown d''Équateur, liant du Nicaragua, tripe de tabacs dominicains et de feuilles brésiliennes ; force moyenne ; au catalogue depuis le 13 janvier 2004 ; Amber, variante du Honduras, ajoutée en septembre 2015 à l''Intertabac de Dortmund) ; cigarworld.de « Mustique Red Toro - Dominikanische Republik » (2026-10-01 : Totalmente a mano (mediumfiller), République dominicaine ; cape Ecuador Connecticut Sungrown, liant du Nicaragua, tripe du Brésil et de République dominicaine ; Toro de 6,125 pouces, calibre 50 ; importateur Kopp Tobaccos GmbH & Co. KG ; en stock ; au catalogue depuis le 11 février 2012) ; cigarworld.de « Mustique Amber Robusto » (2026-10-01 : pays de production Honduras ; cape Connecticut du Honduras, liant de Jamastrán et tripe d''Estelí et de Jalapa, au Nicaragua ; force douce ; Totalmente a mano (mediumfiller) ; au catalogue depuis le 8 septembre 2015 ; Churchill, Corona, Corona Blanco, Petit Corona, Robusto) ; tabak-traeber.de « Mustique Zigarren » (2026-10-01, en anglais : République dominicaine ; fabricant indiqué Kopp Tobaccos ; roulé à la main par les employés d''un producteur de cigares ; Blue Churchill, Corona, Lonsdale, Petit Corona, Robusto et Slim Panetela ; Red Churchill, Corona, Robusto et Toro ; livraison sous trois à quatre jours)',
        NULL,
        'Mustique est une marque de Kopp Tobaccos GmbH & Co. KG, à Rellingen, société qui s''appelait Kohlhase & Kopp jusqu''au départ des frères Kohlhase, au 31 décembre 2022, et que les frères Oliver et Thilo Kopp possèdent seuls depuis début 2023, dit-elle. Elle dit avoir composé elle-même les blends et fait rouler les cigares à la main par les employés d''un producteur de cigares ; elle ne nomme pas sa fabrique, et la page de la marque ne dit pas le pays. Noblego écrit que ces mediumfillers sont faits en République dominicaine pour le compte de Kohlhase & Kopp et optimisés pour le marché allemand.

Cigarworld.de classe ces cigares en Totalmente a mano (mediumfiller), c''est-à-dire, dit-il, entièrement faits à la main mais à tripe déchirée. La marque compte trois lignes, vendues en bundles de dix sous cellophane : la Blue, ligne légère à cape Connecticut Shade dorée sur liant et tripe dominicains, au catalogue de Cigarworld.de depuis le 1er octobre 2008 ; la Red, plus corsée que la Blue, à cape Sun Grown d''Équateur, liant du Nicaragua et tripe de tabacs dominicains et brésiliens, au catalogue depuis le 13 janvier 2004 sous son ancien nom de Bundles B ; et l''Amber, variante du Honduras ajoutée en septembre 2015, à l''Intertabac de Dortmund, dit Cigarworld.de, qui la range, comme Noblego, au Honduras.

En octobre 2026, Cigarworld.de, Noblego et Tabak Träber vendent la marque.',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Cape dorée sur liant et tripe dominicains ; Churchill, Corona, Lonsdale, Petit Corona, Robusto et Slim Panetella, en bundles de dix ; ligne légère, dit Cigarworld.de."},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown (Équateur)","vitolas":[],"story":"Liant du Nicaragua, tripe de tabacs dominicains et de feuilles brésiliennes ; Churchill, Corona, Robusto et Toro, en bundles de dix ; force moyenne selon Cigarworld.de, douce selon Noblego."},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Variante du Honduras : liant de Jamastrán et tripe d''Estelí et de Jalapa, au Nicaragua ; Churchill, Corona, Corona Blanco, Petit Corona et Robusto ; force douce selon Cigarworld.de, moyenne selon Noblego."}]',
        'Mustique is a brand of Kopp Tobaccos GmbH & Co. KG, in Rellingen, a company that was called Kohlhase & Kopp until the Kohlhase brothers left, on 31 December 2022, and that the brothers Oliver and Thilo Kopp have owned on their own since early 2023, it says. It says it composed the blends itself and had the cigars rolled by hand by the employees of a cigar producer; it does not name its factory, and the brand''s page does not state the country. Noblego writes that these mediumfillers are made in the Dominican Republic on behalf of Kohlhase & Kopp and optimised for the German market.

Cigarworld.de classes these cigars as Totalmente a mano (mediumfiller), that is, it says, entirely hand-made but with a torn filler. The brand has three lines, sold in bundles of ten in cellophane: the Blue, a light line with a golden Connecticut Shade wrapper on a Dominican binder and filler, in the Cigarworld.de catalogue since 1 October 2008; the Red, fuller-bodied than the Blue, with a Sun Grown wrapper from Ecuador, a binder from Nicaragua and a filler of Dominican and Brazilian tobaccos, in the catalogue since 13 January 2004 under its former name of Bundles B; and the Amber, a variant from Honduras added in September 2015, at Intertabac in Dortmund, says Cigarworld.de, which files it, like Noblego, under Honduras.

In October 2026, Cigarworld.de, Noblego and Tabak Träber sell the brand.',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Golden wrapper on a Dominican binder and filler; Churchill, Corona, Lonsdale, Petit Corona, Robusto and Slim Panetella, in bundles of ten; a light line, says Cigarworld.de."},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown (Ecuador)","vitolas":[],"story":"Binder from Nicaragua, filler of Dominican tobaccos and Brazilian leaves; Churchill, Corona, Robusto and Toro, in bundles of ten; medium strength according to Cigarworld.de, mild according to Noblego."},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Variant from Honduras: binder from Jamastrán and filler from Estelí and Jalapa, in Nicaragua; Churchill, Corona, Corona Blanco, Petit Corona and Robusto; mild strength according to Cigarworld.de, medium according to Noblego."}]',
        'Mustique es una marca de Kopp Tobaccos GmbH & Co. KG, en Rellingen, sociedad que se llamaba Kohlhase & Kopp hasta la salida de los hermanos Kohlhase, el 31 de diciembre de 2022, y que los hermanos Oliver y Thilo Kopp poseen en exclusiva desde principios de 2023, dice la propia sociedad. Dice haber compuesto ella misma las ligas y haber hecho liar los puros a mano por los empleados de un productor de puros; no nombra su fábrica, y la página de la marca no dice el país. Noblego escribe que estos mediumfillers se hacen en República Dominicana por cuenta de Kohlhase & Kopp y están optimizados para el mercado alemán.

Cigarworld.de clasifica estos puros como Totalmente a mano (mediumfiller), es decir, según el propio sitio, enteramente hechos a mano pero con tripa desgarrada. La marca cuenta con tres líneas, vendidas en bundles de diez en celofán: la Blue, línea ligera con capa Connecticut Shade dorada sobre capote y tripa dominicanos, en el catálogo de Cigarworld.de desde el 1 de octubre de 2008; la Red, de más cuerpo que la Blue, con capa Sun Grown de Ecuador, capote de Nicaragua y tripa de tabacos dominicanos y brasileños, en el catálogo desde el 13 de enero de 2004 con su antiguo nombre de Bundles B; y la Amber, variante de Honduras añadida en septiembre de 2015, en la Intertabac de Dortmund, dice Cigarworld.de, que la clasifica, como Noblego, en Honduras.

En octubre de 2026, Cigarworld.de, Noblego y Tabak Träber venden la marca.',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Capa dorada sobre capote y tripa dominicanos; Churchill, Corona, Lonsdale, Petit Corona, Robusto y Slim Panetella, en bundles de diez; línea ligera, dice Cigarworld.de."},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown (Ecuador)","vitolas":[],"story":"Capote de Nicaragua, tripa de tabacos dominicanos y hojas brasileñas; Churchill, Corona, Robusto y Toro, en bundles de diez; fuerza media según Cigarworld.de, suave según Noblego."},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Variante de Honduras: capote de Jamastrán y tripa de Estelí y de Jalapa, en Nicaragua; Churchill, Corona, Corona Blanco, Petit Corona y Robusto; fuerza suave según Cigarworld.de, media según Noblego."}]',
        'Mustique ist eine Marke der Kopp Tobaccos GmbH & Co. KG in Rellingen, einer Gesellschaft, die bis zum Ausscheiden der Brüder Kohlhase zum 31. Dezember 2022 Kohlhase & Kopp hieß und die den Brüdern Oliver und Thilo Kopp seit Anfang 2023 allein gehört, so die Gesellschaft selbst. Sie sagt, die Mischungen selbst zusammengestellt und die Zigarren von den Angestellten eines Zigarrenproduzenten von Hand rollen lassen zu haben; ihre Fabrik nennt sie nicht, und die Seite der Marke nennt das Land nicht. Noblego schreibt, diese Mediumfiller würden in der Dominikanischen Republik für Kohlhase & Kopp hergestellt und für den deutschen Markt optimiert.

Cigarworld.de ordnet diese Zigarren als Totalmente a mano (mediumfiller) ein, das heißt, nach eigener Angabe, vollständig von Hand gefertigt, aber mit zerrissener Einlage. Die Marke umfasst drei Linien, verkauft in Bundles zu zehn in Cellophan: die Blue, eine leichte Linie mit goldenem Deckblatt Connecticut Shade auf dominikanischem Umblatt und dominikanischer Einlage, seit dem 1. Oktober 2008 im Katalog von Cigarworld.de; die Red, kräftiger als die Blue, mit Deckblatt Sun Grown aus Ecuador, Umblatt aus Nicaragua und Einlage aus dominikanischen Tabaken und brasilianischen Blättern, seit dem 13. Januar 2004 im Katalog unter ihrem früheren Namen Bundles B; und die Amber, eine Variante aus Honduras, im September 2015 hinzugefügt, auf der Intertabac in Dortmund, so Cigarworld.de, das sie wie Noblego Honduras zuordnet.

Im Oktober 2026 verkaufen Cigarworld.de, Noblego und Tabak Träber die Marke.',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Goldenes Deckblatt auf dominikanischem Umblatt und dominikanischer Einlage; Churchill, Corona, Lonsdale, Petit Corona, Robusto und Slim Panetella, in Bundles zu zehn; leichte Linie, so Cigarworld.de."},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown (Ecuador)","vitolas":[],"story":"Umblatt aus Nicaragua, Einlage aus dominikanischen Tabaken und brasilianischen Blättern; Churchill, Corona, Robusto und Toro, in Bundles zu zehn; mittlere Stärke laut Cigarworld.de, milde laut Noblego."},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Variante aus Honduras: Umblatt aus Jamastrán und Einlage aus Estelí und Jalapa, in Nicaragua; Churchill, Corona, Corona Blanco, Petit Corona und Robusto; milde Stärke laut Cigarworld.de, mittlere laut Noblego."}]',
        'Mustique是Kopp Tobaccos GmbH & Co. KG旗下的品牌，该公司位于雷林根（Rellingen），在Kohlhase兄弟于2022年12月31日离开之前名为Kohlhase & Kopp，自2023年初起由Oliver与Thilo Kopp兄弟单独持有，公司如是说。公司称拼配由自己调制，雪茄由一家雪茄生产商的员工手工卷制；公司未透露其工厂名称，品牌页面也没有说明是在哪个国家。Noblego写道，这些mediumfiller雪茄在多米尼加共和国为Kohlhase & Kopp制造，并针对德国市场做了优化。

Cigarworld.de将这些雪茄归为Totalmente a mano（mediumfiller），即按其说法，完全手工制作，但茄芯为撕碎的烟叶。该品牌共有三个系列，均以十支装bundles、玻璃纸包装出售：Blue是力度轻的系列，采用金色Connecticut Shade茄衣，配多米尼加茄套与茄芯，自2008年10月1日起列入Cigarworld.de目录；Red比Blue更浓郁，采用厄瓜多尔Sun Grown茄衣、尼加拉瓜茄套，茄芯为多米尼加烟草与巴西烟叶，自2004年1月13日起以旧名Bundles B列入目录；Amber是来自洪都拉斯的版本，于2015年9月在多特蒙德的Intertabac展会上加入，据Cigarworld.de称，该网站与Noblego一样将其归入洪都拉斯。

2026年10月，Cigarworld.de、Noblego与Tabak Träber均销售该品牌。',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"据Cigarworld.de称，金色茄衣，配多米尼加茄套与茄芯；规格有Churchill、Corona、Lonsdale、Petit Corona、Robusto与Slim Panetella，十支装bundles；产品线力度轻。"},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown（厄瓜多尔）","vitolas":[],"story":"尼加拉瓜茄套，茄芯为多米尼加烟草与巴西烟叶；规格有Churchill、Corona、Robusto与Toro，十支装bundles；Cigarworld.de称力度中等，Noblego称力度温和。"},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut（洪都拉斯）","vitolas":[],"story":"来自洪都拉斯的版本：茄套来自哈马斯特兰（Jamastrán），茄芯来自埃斯特利与哈拉帕，位于尼加拉瓜；规格有Churchill、Corona、Corona Blanco、Petit Corona与Robusto；Cigarworld.de称力度温和，Noblego称力度中等。"}]',
        'Mustique علامة تابعة لـKopp Tobaccos GmbH & Co. KG في ريلينغن (Rellingen)، وهي شركة كانت تُسمّى Kohlhase & Kopp إلى أن غادر الأخوان Kohlhase في 31 ديسمبر 2022، ويملك الأخوان Oliver وThilo Kopp الشركة وحدهما منذ مطلع 2023، بحسب قولها. وتقول إنها ألّفت الخلطات بنفسها وجعلت موظفي منتج سيجار يلفّون سيجارها يدويًا؛ ولا تذكر اسم مصنعها، ولا تذكر صفحة العلامة البلد. ويكتب Noblego أن هذه السيجار من نوع mediumfiller تُصنع في جمهورية الدومينيكان لحساب Kohlhase & Kopp، وأنها مُحسَّنة للسوق الألماني.

ويصنّف Cigarworld.de هذه السيجار ضمن Totalmente a mano (mediumfiller)، أي، بحسب قوله، مصنوعة بالكامل يدويًا لكن بحشوة ممزّقة. وللعلامة ثلاثة خطوط تُباع في bundles من عشرة مغلّفة بالسيلوفان: Blue، وهو خط خفيف بغلاف Connecticut Shade ذهبي على غلاف داخلي وحشوة دومينيكيَّين، وهو في كتالوج Cigarworld.de منذ 1 أكتوبر 2008؛ وRed، وهي أشدّ قوةً من Blue، بغلاف Sun Grown من الإكوادور وغلاف داخلي من نيكاراغوا وحشوة من تبغ دومينيكي وبرازيلي، وهي في الكتالوج منذ 13 يناير 2004 باسمها السابق Bundles B؛ وAmber، وهي نسخة من هندوراس أُضيفت في سبتمبر 2015، في معرض Intertabac بدورتموند، بحسب Cigarworld.de الذي يصنّفها، مثل Noblego، في هندوراس.

وفي أكتوبر 2026، يبيع Cigarworld.de وNoblego وTabak Träber العلامة.',
        '[{"name":"Blue","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"غلاف ذهبي على غلاف داخلي وحشوة دومينيكيَّين؛ بمقاسات Churchill وCorona وLonsdale وPetit Corona وRobusto وSlim Panetella، في bundles من عشرة؛ خط خفيف، بحسب Cigarworld.de."},{"name":"Red","color":"#A0522D","force":null,"wrapper":"Sun Grown (الإكوادور)","vitolas":[],"story":"غلاف داخلي من نيكاراغوا، وحشوة من تبغ دومينيكي وأوراق برازيلية؛ بمقاسات Churchill وCorona وRobusto وToro، في bundles من عشرة؛ بقوة متوسطة بحسب Cigarworld.de، وخفيفة بحسب Noblego."},{"name":"Amber","color":"#C9A96E","force":null,"wrapper":"Connecticut (هندوراس)","vitolas":[],"story":"نسخة من هندوراس: غلاف داخلي من خاماستران (Jamastrán) وحشوة من إستيلي وخالابا، في نيكاراغوا؛ بمقاسات Churchill وCorona وCorona Blanco وPetit Corona وRobusto؛ بقوة خفيفة بحسب Cigarworld.de، ومتوسطة بحسب Noblego."}]')
