-- ── El Mago ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('El Mago',
        'nicaragua',
        '2022 — Nicholas Fusco, Miami',
        'Chez MGE Cigars Factory (Mighty God Enterprise), Estelí, Nicaragua',
        'elmagocigars.com « El Mago Cigars » (page d''accueil, 1er octobre 2026 : marque de Nicholas Fusco, à Miami ; hommage à ses grands-parents, Maria et Gonzalo Torre, morts le 24 juin 2021 dans l''effondrement des Champlain Towers ; cigares faits à la main) ; cigar-coop.com « Cigar News: El Mago Cigars Launches Cigar Lines » (15 septembre 2022 : El Mago Cigars créée en 2022 par Nick Fusco en hommage à ses grands-parents ; quatre cigares, Pepe, Triunfante, Miami Maduro et Miami Art Deco, en Toro 6 x 52, avec cape, liant et tripe de chacun ; produits au Nicaragua) ; cigar-coop.com « El Mago Pepe Cigar Review » (27 mai 2025 : fiche technique, fabrique MGE Cigars Factory, au Nicaragua ; cape San Andrés mexicaine, liant U.S. Broadleaf, tripe nicaraguayenne, Toro 6 x 52 box-pressé, tubes carrés individuels, boîtes de douze ; Pepe en hommage au grand-père, ainsi surnommé ; la MGE gère toute la production d''El Mago) ; cigar-coop.com « El Mago to Release The James Avenue at PCA 2026 » (3 avril 2026 : nouvelle ligne régulière The James Avenue, quatre mélanges Connecticut, Habano, Maduro et Sumatra, Toro 6 x 54 box-pressé ; production à la MGE (Mighty God Enterprise) Cigars Factory, à Estelí ; hommage au James Hotel, acheté en 1989 par le grand-père du fondateur) ; cigardojo.com « El Mago Begins Shipping New James Avenue Core Line » (23 juin 2026 : capes et liants des quatre mélanges, tripes nicaraguayennes, boîtes de vingt, fabrique MGE Cigars Factory à Estelí, expédition aux détaillants) ; cigardojo.com « El Mago Expands Collectible Tin Series with JUG and Cavalry » (28 mai 2026 : JUG et Cavalry, collections nos 3 et 4, 5 x 50 box-pressé, tins de cinq, fabrique MGE à Estelí ; JUG cape San Andrés maduro, liant équatorien, corps plein ; Cavalry cape Corojo, liant nicaraguayen, tripe nicaraguayenne et dominicaine, corps moyen ; distribution limitée à moins de quarante comptes) ; cigar-coop.com « El Mago to Introduce Miami Beach Sweets at PCA 2025 » (4 avril 2025 : Miami Beach Sweets n''est pas une marque d''El Mago, qui en est le distributeur exclusif ; cigares aromatisés produits à la fabrique MGE, au Nicaragua) ; cigarcentury.com « El Mago - Miami Pepe » (1er octobre 2026 : fiche du détaillant Century Premium Cigars : El Mago fondée en 2022 par Nicholas Fusco en hommage à ses grands-parents ; fabrique de Miguel Pinto, MGE Cigars Factory ; Toro 6 x 52, cape San Andrés maduro mexicaine, liant Broadleaf, tripe du Nicaragua) ; cigarcentury.com « El Mago - Miami Art Deco Edition » (1er octobre 2026 : Toro 6 x 52, cape Habano équatorienne, liant Broadleaf, tripe du Nicaragua ; fabrique de Miguel Pinto, MGE Cigars Factory) ; cigarcentury.com « El Mago - Century Premium Cigars » (page de marque, 1er octobre 2026 : El Mago établie en 2022 par Nicholas Fusco ; catalogue d''une quinzaine de cigares, dont Alakazam, Jaguar, Mistico, Solstice, Miami Maduro, Miami Pepe et Miami Triunfante)',
        NULL,
        'El Mago est la marque de Nicholas Fusco, à Miami, créée en hommage à ses grands-parents, Maria et Gonzalo Torre, morts le 24 juin 2021 dans l''effondrement des Champlain Towers, dit la maison. Century Premium Cigars la dit fondée en 2022 ; Cigar Coop annonce ses premiers cigares le 15 septembre 2022 : Pepe, Triunfante, Miami Maduro et Miami Art Deco, tous en Toro 6 x 52.

Les cigares sont roulés au Nicaragua, à la MGE Cigars Factory (Mighty God Enterprise), à Estelí, qui gère toute la production d''El Mago, dit Cigar Coop en mai 2025 ; Century Premium Cigars en fait la fabrique de Miguel Pinto. En 2026, la marque présente The James Avenue, ligne régulière de quatre mélanges en Toro 6 x 54 box-pressé, livrée aux détaillants à partir de juin, et deux nouveaux cigares de sa Collectible Tin Series, JUG et Cavalry, annoncés le 28 mai, dit Cigar Dojo.

El Mago distribue en exclusivité Miami Beach Sweets, une marque de cigares aromatisés qui n''est pas la sienne, produite à la même fabrique, dit Cigar Coop en avril 2025. En octobre 2026, Century Premium Cigars tient à son catalogue d''autres cigares d''El Mago, dont Alakazam, Jaguar, Mistico et Solstice.',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne régulière de 2026, du nom d''une rue de Miami Beach et en hommage au James Hotel, que le grand-père du fondateur a acheté en 1989, dit Cigar Coop ; quatre mélanges en Toro 6 x 54 box-pressé, en boîtes de vingt : Connecticut et Habano sur liant nicaraguayen, Maduro (cape San Andrés mexicaine) et Sumatra sur liant équatorien, tripes nicaraguayennes, dit Cigar Dojo."},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Série en tins de cinq, 5 x 50 box-pressé, en distribution restreinte ; JUG (no 3 : cape San Andrés maduro, liant équatorien, corps plein) et Cavalry (no 4 : cape Corojo, liant nicaraguayen, tripe nicaraguayenne et dominicaine, corps moyen), dit Cigar Dojo en mai 2026."},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Hommage au grand-père du fondateur, surnommé Pepe, dit Cigar Coop ; liant U.S. Broadleaf, tripe nicaraguayenne, en Toro 6 x 52 box-pressé, vendu en tubes carrés individuels et en boîtes de douze."},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Liant Corojo, tripe nicaraguayenne, en Toro 6 x 52 box-pressé, dit Cigar Coop en septembre 2022."},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape San Andrés bicolore, liant Sumatra, tripe nicaraguayenne d''Estelí, en Toro 6 x 52, dit Cigar Coop en septembre 2022."},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano (Équateur)","vitolas":[],"story":"Liant U.S. Broadleaf, tripe nicaraguayenne, en Toro 6 x 52, dit Cigar Coop en septembre 2022."}]',
        'El Mago is the brand of Nicholas Fusco, in Miami, created in tribute to his grandparents, Maria and Gonzalo Torre, who died on 24 June 2021 in the collapse of the Champlain Towers, says the house. Century Premium Cigars says it was founded in 2022; Cigar Coop announces its first cigars on 15 September 2022: Pepe, Triunfante, Miami Maduro and Miami Art Deco, all in Toro 6 x 52.

The cigars are rolled in Nicaragua, at the MGE Cigars Factory (Mighty God Enterprise), in Estelí, which manages all of El Mago''s production, says Cigar Coop in May 2025; Century Premium Cigars calls it the factory of Miguel Pinto. In 2026, the brand presents The James Avenue, a regular line of four blends in box-pressed Toro 6 x 54, delivered to retailers from June, and two new cigars in its Collectible Tin Series, JUG and Cavalry, announced on 28 May, says Cigar Dojo.

El Mago distributes exclusively Miami Beach Sweets, a brand of flavoured cigars that is not its own, produced at the same factory, says Cigar Coop in April 2025. In October 2026, Century Premium Cigars carries other El Mago cigars in its catalogue, including Alakazam, Jaguar, Mistico and Solstice.',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Regular line of 2026, named after a street in Miami Beach and in tribute to the James Hotel, which the founder''s grandfather bought in 1989, says Cigar Coop; four blends in box-pressed Toro 6 x 54, in boxes of twenty: Connecticut and Habano on a Nicaraguan binder, Maduro (Mexican San Andrés wrapper) and Sumatra on an Ecuadorian binder, Nicaraguan fillers, says Cigar Dojo."},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Series in tins of five, 5 x 50 box-pressed, in restricted distribution; JUG (no. 3: San Andrés maduro wrapper, Ecuadorian binder, full body) and Cavalry (no. 4: Corojo wrapper, Nicaraguan binder, Nicaraguan and Dominican filler, medium body), says Cigar Dojo in May 2026."},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Tribute to the founder''s grandfather, nicknamed Pepe, says Cigar Coop; U.S. Broadleaf binder, Nicaraguan filler, in box-pressed Toro 6 x 52, sold in individual square tubes and in boxes of twelve."},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Corojo binder, Nicaraguan filler, in box-pressed Toro 6 x 52, says Cigar Coop in September 2022."},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Two-tone San Andrés wrapper, Sumatra binder, Nicaraguan filler from Estelí, in Toro 6 x 52, says Cigar Coop in September 2022."},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"U.S. Broadleaf binder, Nicaraguan filler, in Toro 6 x 52, says Cigar Coop in September 2022."}]',
        'El Mago es la marca de Nicholas Fusco, en Miami, creada en homenaje a sus abuelos, Maria y Gonzalo Torre, fallecidos el 24 de junio de 2021 en el derrumbe de las Champlain Towers, dice la casa. Century Premium Cigars dice que fue fundada en 2022; Cigar Coop anuncia sus primeros puros el 15 de septiembre de 2022: Pepe, Triunfante, Miami Maduro y Miami Art Deco, todos en Toro 6 x 52.

Los puros se lían en Nicaragua, en la MGE Cigars Factory (Mighty God Enterprise), en Estelí, que gestiona toda la producción de El Mago, dice Cigar Coop en mayo de 2025; Century Premium Cigars la presenta como la fábrica de Miguel Pinto. En 2026, la marca presenta The James Avenue, línea regular de cuatro mezclas en Toro 6 x 54 box-pressed, entregada a los minoristas a partir de junio, y dos nuevos puros de su Collectible Tin Series, JUG y Cavalry, anunciados el 28 de mayo, dice Cigar Dojo.

El Mago distribuye en exclusiva Miami Beach Sweets, una marca de puros aromatizados que no es suya, producida en la misma fábrica, dice Cigar Coop en abril de 2025. En octubre de 2026, Century Premium Cigars tiene en su catálogo otros puros de El Mago, entre ellos Alakazam, Jaguar, Mistico y Solstice.',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea regular de 2026, que lleva el nombre de una calle de Miami Beach y rinde homenaje al James Hotel, que el abuelo del fundador compró en 1989, dice Cigar Coop; cuatro mezclas en Toro 6 x 54 box-pressed, en cajas de veinte: Connecticut y Habano sobre capote nicaragüense, Maduro (capa San Andrés mexicana) y Sumatra sobre capote ecuatoriano, tripas nicaragüenses, dice Cigar Dojo."},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Serie en latas de cinco, 5 x 50 box-pressed, en distribución restringida; JUG (n.º 3: capa San Andrés maduro, capote ecuatoriano, cuerpo pleno) y Cavalry (n.º 4: capa Corojo, capote nicaragüense, tripa nicaragüense y dominicana, cuerpo medio), dice Cigar Dojo en mayo de 2026."},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Homenaje al abuelo del fundador, apodado Pepe, dice Cigar Coop; capote U.S. Broadleaf, tripa nicaragüense, en Toro 6 x 52 box-pressed, vendido en tubos cuadrados individuales y en cajas de doce."},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Capote Corojo, tripa nicaragüense, en Toro 6 x 52 box-pressed, dice Cigar Coop en septiembre de 2022."},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Capa San Andrés bicolor, capote Sumatra, tripa nicaragüense de Estelí, en Toro 6 x 52, dice Cigar Coop en septiembre de 2022."},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Capote U.S. Broadleaf, tripa nicaragüense, en Toro 6 x 52, dice Cigar Coop en septiembre de 2022."}]',
        'El Mago ist die Marke von Nicholas Fusco in Miami, zu Ehren seiner Großeltern Maria und Gonzalo Torre geschaffen, die am 24. Juni 2021 beim Einsturz der Champlain Towers starben, so das Haus. Century Premium Cigars zufolge wurde sie 2022 gegründet; Cigar Coop kündigt ihre ersten Zigarren am 15. September 2022 an: Pepe, Triunfante, Miami Maduro und Miami Art Deco, alle als Toro 6 x 52.

Die Zigarren werden in Nicaragua gerollt, in der MGE Cigars Factory (Mighty God Enterprise) in Estelí, die die gesamte Produktion von El Mago betreut, so Cigar Coop im Mai 2025; Century Premium Cigars nennt sie die Fabrik von Miguel Pinto. 2026 stellt die Marke The James Avenue vor, eine reguläre Linie aus vier Mischungen als Toro 6 x 54, box-pressed, die ab Juni an die Einzelhändler ausgeliefert wird, sowie zwei neue Zigarren ihrer Collectible Tin Series, JUG und Cavalry, am 28. Mai angekündigt, so Cigar Dojo.

El Mago vertreibt exklusiv Miami Beach Sweets, eine Marke aromatisierter Zigarren, die ihr nicht gehört und in derselben Fabrik hergestellt wird, so Cigar Coop im April 2025. Im Oktober 2026 führt Century Premium Cigars weitere Zigarren von El Mago im Katalog, darunter Alakazam, Jaguar, Mistico und Solstice.',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Reguläre Linie von 2026, benannt nach einer Straße in Miami Beach und zu Ehren des James Hotel, das der Großvater des Gründers 1989 kaufte, so Cigar Coop; vier Mischungen als Toro 6 x 54, box-pressed, in Kisten zu zwanzig Stück: Connecticut und Habano auf nicaraguanischem Umblatt, Maduro (mexikanisches Deckblatt San Andrés) und Sumatra auf ecuadorianischem Umblatt, nicaraguanische Einlagen, so Cigar Dojo."},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Serie in Dosen zu fünf Stück, 5 x 50 box-pressed, in eingeschränktem Vertrieb; JUG (Nr. 3: Deckblatt San Andrés maduro, ecuadorianisches Umblatt, voller Körper) und Cavalry (Nr. 4: Deckblatt Corojo, nicaraguanisches Umblatt, nicaraguanische und dominikanische Einlage, mittlerer Körper), so Cigar Dojo im Mai 2026."},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Hommage an den Großvater des Gründers, der den Spitznamen Pepe trug, so Cigar Coop; Umblatt U.S. Broadleaf, nicaraguanische Einlage, als Toro 6 x 52, box-pressed, verkauft in einzelnen quadratischen Tuben und in Kisten zu zwölf Stück."},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Umblatt Corojo, nicaraguanische Einlage, als Toro 6 x 52, box-pressed, so Cigar Coop im September 2022."},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Zweifarbiges Deckblatt San Andrés, Umblatt Sumatra, nicaraguanische Einlage aus Estelí, als Toro 6 x 52, so Cigar Coop im September 2022."},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Umblatt U.S. Broadleaf, nicaraguanische Einlage, als Toro 6 x 52, so Cigar Coop im September 2022."}]',
        'El Mago是Nicholas Fusco在迈阿密的品牌，为向其祖父母Maria与Gonzalo Torre致敬而创建，二人于2021年6月24日在Champlain Towers倒塌事故中遇难，据品牌方称。据Century Premium Cigars称，该品牌创立于2022年；Cigar Coop于2022年9月15日宣布其首批雪茄，即Pepe、Triunfante、Miami Maduro与Miami Art Deco，均为Toro 6 x 52。

雪茄在尼加拉瓜埃斯特利的MGE Cigars Factory（Mighty God Enterprise）卷制，据Cigar Coop于2025年5月称，该厂负责El Mago的全部生产；Century Premium Cigars则称其为Miguel Pinto的工厂。2026年，该品牌推出The James Avenue，这是一条由四种拼配组成的常规产品线，规格为box-pressed Toro 6 x 54，自6月起交付零售商；另有其Collectible Tin Series的两款新雪茄JUG与Cavalry，据Cigar Dojo称，于5月28日宣布。

El Mago独家经销Miami Beach Sweets，这是一个调味雪茄品牌，并非其自有品牌，在同一家工厂生产，据Cigar Coop于2025年4月称。2026年10月，Century Premium Cigars在目录中还列有El Mago的其他雪茄，包括Alakazam、Jaguar、Mistico与Solstice。',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"2026年的常规产品线，名称取自迈阿密海滩的一条街道，并向James Hotel致敬，该酒店由创始人的祖父于1989年购得，据Cigar Coop称；四种拼配，规格为box-pressed Toro 6 x 54，每盒二十支：Connecticut与Habano配尼加拉瓜茄套，Maduro（墨西哥San Andrés茄衣）与Sumatra配厄瓜多尔茄套，茄芯均产自尼加拉瓜，据Cigar Dojo称。"},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"系列以五支装铁盒发售，规格为box-pressed 5 x 50，分销范围受限；JUG（3号：San Andrés maduro茄衣，厄瓜多尔茄套，烟体饱满）与Cavalry（4号：Corojo茄衣，尼加拉瓜茄套，尼加拉瓜与多米尼加茄芯，烟体中等），据Cigar Dojo于2026年5月称。"},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"向创始人的祖父致敬，其绰号为Pepe，据Cigar Coop称；茄套为U.S. Broadleaf，茄芯产自尼加拉瓜，规格为box-pressed Toro 6 x 52，以单支方形管装和十二支装盒装出售。"},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"茄套为Corojo，茄芯产自尼加拉瓜，规格为box-pressed Toro 6 x 52，据Cigar Coop于2022年9月称。"},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"双色San Andrés茄衣，茄套为Sumatra，茄芯为来自埃斯特利的尼加拉瓜烟叶，规格为Toro 6 x 52，据Cigar Coop于2022年9月称。"},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"茄套为U.S. Broadleaf，茄芯产自尼加拉瓜，规格为Toro 6 x 52，据Cigar Coop于2022年9月称。"}]',
        'El Mago هي علامة Nicholas Fusco، في ميامي، أُنشئت تكريمًا لجدّته وجدّه، Maria وGonzalo Torre، اللذين توفيا في 24 يونيو 2021 في انهيار Champlain Towers، بحسب الدار. وتقول Century Premium Cigars إنها تأسست عام 2022؛ وتعلن Cigar Coop عن أولى سيجاراتها في 15 سبتمبر 2022: Pepe وTriunfante وMiami Maduro وMiami Art Deco، وكلها بمقاس Toro 6 x 52.

يُلَفّ السيجار في نيكاراغوا، في مصنع MGE Cigars Factory (Mighty God Enterprise) في إستيلي، الذي يتولى إدارة الإنتاج كله لدى El Mago، بحسب Cigar Coop في مايو 2025؛ وتقدّمه Century Premium Cigars على أنه مصنع Miguel Pinto. وفي 2026، تعرض العلامة The James Avenue، وهو خط إنتاج منتظم من أربع خلطات بمقاس Toro 6 x 54 box-pressed، يُسلَّم إلى تجار التجزئة اعتبارًا من يونيو، وسيجارين جديدين من سلسلتها Collectible Tin Series، هما JUG وCavalry، أُعلن عنهما في 28 مايو، بحسب Cigar Dojo.

وتوزّع El Mago حصريًا Miami Beach Sweets، وهي علامة سيجار منكّه ليست علامتها، تُنتَج في المصنع نفسه، بحسب Cigar Coop في أبريل 2025. وفي أكتوبر 2026، تُدرج Century Premium Cigars في فهرسها سيجارات أخرى من El Mago، منها Alakazam وJaguar وMistico وSolstice.',
        '[{"name":"The James Avenue","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط إنتاج منتظم لعام 2026، سُمّي على اسم شارع في ميامي بيتش وتكريمًا لفندق James Hotel الذي اشتراه جدّ المؤسس عام 1989، بحسب Cigar Coop؛ أربع خلطات بمقاس Toro 6 x 54 box-pressed، في علب من عشرين: Connecticut وHabano على رباط نيكاراغوي، وMaduro (غلاف San Andrés مكسيكي) وSumatra على رباط إكوادوري، وحشوات نيكاراغوية، بحسب Cigar Dojo."},{"name":"Collectible Tin Series","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سلسلة في علب معدنية من خمسة، 5 x 50 box-pressed، بتوزيع مقيَّد؛ JUG (رقم 3: غلاف San Andrés maduro، ورباط إكوادوري، وقوام ممتلئ) وCavalry (رقم 4: غلاف Corojo، ورباط نيكاراغوي، وحشوة نيكاراغوية ودومينيكية، وقوام متوسط)، بحسب Cigar Dojo في مايو 2026."},{"name":"Pepe","color":"#4A3728","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"تكريم لجدّ المؤسس، الملقّب Pepe، بحسب Cigar Coop؛ رباط U.S. Broadleaf وحشوة نيكاراغوية، بمقاس Toro 6 x 52 box-pressed، ويُباع في أنابيب مربعة فردية وفي علب من اثني عشر."},{"name":"Triunfante","color":"#C9A96E","force":null,"wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"رباط Corojo وحشوة نيكاراغوية، بمقاس Toro 6 x 52 box-pressed، بحسب Cigar Coop في سبتمبر 2022."},{"name":"Miami Maduro","color":"#4A3728","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف San Andrés ثنائي اللون، ورباط Sumatra، وحشوة نيكاراغوية من إستيلي، بمقاس Toro 6 x 52، بحسب Cigar Coop في سبتمبر 2022."},{"name":"Miami Art Deco","color":"#A0522D","force":null,"wrapper":"Habano (الإكوادور)","vitolas":[],"story":"رباط U.S. Broadleaf وحشوة نيكاراغوية، بمقاس Toro 6 x 52، بحسب Cigar Coop في سبتمبر 2022."}]')
