INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Emperors Cut',
        'dominican',
        '2017 — Darnell Streat et associés, Houston',
        'Chez La Aurora (Manuel Inoa), Santiago de los Caballeros ; Natural Pleasure et Indulgence chez Agrotabacos (Omar Ortez), Condega (Nicaragua)',
        'stogiepress.com « Cigar News: Emperors Cut Cigars Announces the Red Tail Series » (7 novembre 2022 : maison de Houston, au Texas, fondée en 2017 ; Red Tail Series faite à La Aurora, à Santiago de los Caballeros, en République dominicaine, avec le maître mélangeur Manuel Inoa ; Toro et Torpedo, capes Natural et Maduro, boîtes de dix ; en ligne le 1er décembre 2022, sortie générale en février 2023) ; stogiepress.com « Cigar Review: Emperors Cut Natural Pleasure Toro » (29 mai 2022 : fiche technique, cape nicaraguayenne, liant équatorien, tripe nicaraguayenne, Toro 6½ x 52, force moyenne, sortie en 2018 ; faite à Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos), avec Omar Ortez ; Greg Willis, cofondateur) ; tobaccobusiness.com « Partners in Smoke: Emperors Cut Cigars » (26 avril 2021 : l''occasion de lancer la société se présente en 2017 après des années de discussion ; Natural Pleasure, mélange nicaraguayen, fait par une famille du Nicaragua ; Jazz Series, mélange dominicain, avec Manuel Inoa de La Aurora) ; cigar-coop.com « Cigar News: Emperors Cut Adds Three New Sizes to Natural Pleasure Line » (21 février 2020 : Natural Pleasure, première ligne, cape colorado maduro, liant équatorien, tripes d''Estelí ; Toro 6½ x 52, Grand Robusto 5½ x 56, Robusto 5 x 50, Shawty 4 x 56 ; marque dite basée à Atlanta, en Géorgie ; lancements à Houston et dans d''autres villes) ; cigar-coop.com « Cigar News: Emperors Cut Launches Jazz Series » (2 octobre 2020 : Jazz Series, deuxième ligne, lancée le 1er octobre 2020 avec Manuel Inoa, à La Aurora ; cape Sumatra équatorienne sun grown de teinte colorado maduro, liant équatorien, tripes du Nicaragua, du Pérou et de deux feuilles dominicaines du Cibao ; Toro 6½ x 56, Gran Robusto 5½ x 52, Gordito ; pays d''origine République dominicaine, fabrique dite à Estelí dans l''article) ; cigar-coop.com « Cigar News: Emperors Cut Indulgence Announced » (30 novembre 2021 : Indulgence, troisième ligne, pour fumeurs de force douce à moyenne ; cape Connecticut Shade équatorienne, liant nicaraguayen, tripes nicaraguayenne et dominicaine ; Belicoso 6½ x 54 et Lancero 7 x 38, boîtes de dix ; faite à Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos), à Condega ; en ligne le 1er décembre 2021, chez les détaillants en avril 2022) ; cigar-coop.com « Cigar News: Emperors Cut Announces Red Tail Series » (7 novembre 2022 : Emperors Group LLC, société mère d''Emperors Cut Cigars, annonce sa quatrième ligne, hommage aux Tuskegee Airmen ; capes Natural et Maduro ; Toro et Torpedo 6½ x 52 ; La Aurora, avec le maître mélangeur Manuel Inoa) ; cigar-coop.com « Emperors Cut Cigars Announces Prophecy » (20 juillet 2026 : Prophecy, production limitée ; cape du Cameroun, liant nicaraguayen, tripes du Nicaragua, de Pennsylvanie et de République dominicaine ; 7 x 52 ; La Aurora, avec Manuel Inoa ; disponible dès le 1er août 2026 ; Darnell Streat, associé gérant) ; emperors-cut.com « About Us » (1er octobre 2026 : la maison se dit fondée par cinq entrepreneurs et nomme sept associés : Darnell Streat, associé gérant, Maurice Holland, Darryl Redmon, Temi Bush, Robert Howard, Greg Hurt et Greg Willis ; Houston cité à propos de Darnell Streat, aucun siège désigné) ; emperors-cut.com « Emperors Cut Premium Cigars » (page d''accueil, 1er octobre 2026 : collections Emperors Reserve, Royal Harvest, Prophecy, Red Tail Series (HellFighter, Warhawk Natural, 332nd Maduro) et Jazz Series ; ni Natural Pleasure ni Indulgence nommées) ; emperors-cut.com « Shop_OLD » (1er octobre 2026 : ancienne page boutique, Natural Pleasure et Jazz Series) ; cigarcentury.com « Emperors Cut - Century Premium Cigars » (1er octobre 2026 : catalogue du détaillant : Indulgence, Jazz, Natural Pleasure et Red Tail Series)',
        NULL,
        'Emperors Group LLC est la société mère d''Emperors Cut Cigars, dit Cigar Coop. Stogiepress dit la maison fondée en 2017 à Houston, au Texas ; Cigar Coop la disait basée à Atlanta, en Géorgie, en février 2020. Le site de la maison nomme sept associés — Darnell Streat, associé gérant, Maurice Holland, Darryl Redmon, Temi Bush, Robert Howard, Greg Hurt et Greg Willis — et la dit fondée par cinq entrepreneurs.

Natural Pleasure, première ligne, sort en 2018 ; elle est faite à Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos), avec Omar Ortez, dit Stogiepress. Cigar Coop dit Indulgence, troisième ligne annoncée le 30 novembre 2021, faite à la même fabrique, à Condega. La Jazz Series (octobre 2020), la Red Tail Series (annoncée le 7 novembre 2022) et Prophecy (annoncée le 20 juillet 2026, disponible dès le 1er août) viennent de La Aurora, à Santiago de los Caballeros, en République dominicaine, où le maître mélangeur Manuel Inoa les a mises au point avec la maison, dit Cigar Coop.

En octobre 2026, le site de la maison présente, entre autres collections, Jazz Series, Red Tail Series et Prophecy, et Century Premium Cigars tient à son catalogue Natural Pleasure, Jazz Series, Indulgence et Red Tail Series.',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro (Nicaragua)","vitolas":[],"story":"Première ligne, sortie en 2018 : liant équatorien, tripe d''Estelí ; en Toro (6½ x 52), Grand Robusto (5½ x 56), Robusto (5 x 50) et Shawty (4 x 56), dit Cigar Coop en 2020 ; force moyenne selon Stogiepress."},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown (Équateur)","vitolas":[],"story":"Deuxième ligne, lancée le 1er octobre 2020, de teinte colorado maduro, sur liant équatorien et tripe de tabacs du Nicaragua, du Pérou et de deux feuilles dominicaines du Cibao ; en Toro (6½ x 56), Gran Robusto (5½ x 52) et Gordito, dit Cigar Coop."},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Troisième ligne, annoncée le 30 novembre 2021 pour des fumeurs de force douce à moyenne : liant nicaraguayen, tripe nicaraguayenne et dominicaine ; en Belicoso (6½ x 54) et Lancero (7 x 38), en boîtes de dix, dit Cigar Coop."},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Quatrième ligne, en hommage aux Tuskegee Airmen, annoncée le 7 novembre 2022 : capes Natural et Maduro, en Toro et en Torpedo (6½ x 52), en boîtes de dix, dit Cigar Coop ; le site de la maison y range en octobre 2026 HellFighter, Warhawk Natural et 332nd Maduro."},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"Cameroun","vitolas":[],"story":"Production limitée annoncée le 20 juillet 2026, disponible dès le 1er août : liant nicaraguayen, tripe du Nicaragua, de Pennsylvanie et de République dominicaine, en 7 x 52, par paquets de cinq, mise au point avec Manuel Inoa à La Aurora, dit Cigar Coop."}]',
        'Emperors Group LLC is the parent company of Emperors Cut Cigars, says Cigar Coop. Stogiepress says the house was founded in 2017 in Houston, Texas; Cigar Coop said it was based in Atlanta, Georgia, in February 2020. The house''s website names seven partners — Darnell Streat, managing partner, Maurice Holland, Darryl Redmon, Temi Bush, Robert Howard, Greg Hurt and Greg Willis — and says it was founded by five entrepreneurs.

Natural Pleasure, the first line, came out in 2018; it is made at Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos), with Omar Ortez, says Stogiepress. Cigar Coop says Indulgence, the third line, announced on 30 November 2021, is made at the same factory, in Condega. The Jazz Series (October 2020), the Red Tail Series (announced on 7 November 2022) and Prophecy (announced on 20 July 2026, available from 1 August) come from La Aurora, in Santiago de los Caballeros, in the Dominican Republic, where master blender Manuel Inoa developed them with the house, says Cigar Coop.

In October 2026, the house''s website presents, among other collections, Jazz Series, Red Tail Series and Prophecy, and Century Premium Cigars carries Natural Pleasure, Jazz Series, Indulgence and Red Tail Series in its catalogue.',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro (Nicaragua)","vitolas":[],"story":"First line, released in 2018: Ecuadorian binder, filler from Estelí; in Toro (6½ x 52), Grand Robusto (5½ x 56), Robusto (5 x 50) and Shawty (4 x 56), says Cigar Coop in 2020; medium strength according to Stogiepress."},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown (Ecuador)","vitolas":[],"story":"Second line, launched on 1 October 2020, in a colorado maduro shade, on an Ecuadorian binder and a filler of tobaccos from Nicaragua and Peru and of two Dominican leaves from the Cibao; in Toro (6½ x 56), Gran Robusto (5½ x 52) and Gordito, says Cigar Coop."},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Third line, announced on 30 November 2021 for smokers of mild-to-medium strength: Nicaraguan binder, Nicaraguan and Dominican filler; in Belicoso (6½ x 54) and Lancero (7 x 38), in boxes of ten, says Cigar Coop."},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Fourth line, in tribute to the Tuskegee Airmen, announced on 7 November 2022: Natural and Maduro wrappers, in Toro and Torpedo (6½ x 52), in boxes of ten, says Cigar Coop; in October 2026 the house''s website lists HellFighter, Warhawk Natural and 332nd Maduro under it."},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"Cameroon","vitolas":[],"story":"Limited production announced on 20 July 2026, available from 1 August: Nicaraguan binder, filler from Nicaragua, Pennsylvania and the Dominican Republic, in 7 x 52, in packs of five, developed with Manuel Inoa at La Aurora, says Cigar Coop."}]',
        'Emperors Group LLC es la sociedad matriz de Emperors Cut Cigars, dice Cigar Coop. Stogiepress dice que la casa fue fundada en 2017 en Houston, Texas; Cigar Coop la decía con sede en Atlanta, Georgia, en febrero de 2020. El sitio web de la casa nombra a siete socios —Darnell Streat, socio gerente, Maurice Holland, Darryl Redmon, Temi Bush, Robert Howard, Greg Hurt y Greg Willis— y dice que fue fundada por cinco emprendedores.

Natural Pleasure, primera línea, sale en 2018; se elabora en Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos), con Omar Ortez, dice Stogiepress. Cigar Coop dice que Indulgence, tercera línea anunciada el 30 de noviembre de 2021, se elabora en la misma fábrica, en Condega. La Jazz Series (octubre de 2020), la Red Tail Series (anunciada el 7 de noviembre de 2022) y Prophecy (anunciada el 20 de julio de 2026, disponible desde el 1 de agosto) proceden de La Aurora, en Santiago de los Caballeros, en República Dominicana, donde el maestro mezclador Manuel Inoa las puso a punto con la casa, dice Cigar Coop.

En octubre de 2026, el sitio web de la casa presenta, entre otras colecciones, Jazz Series, Red Tail Series y Prophecy, y Century Premium Cigars tiene en su catálogo Natural Pleasure, Jazz Series, Indulgence y Red Tail Series.',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro (Nicaragua)","vitolas":[],"story":"Primera línea, aparecida en 2018: capote ecuatoriano, tripa de Estelí; en Toro (6½ x 52), Grand Robusto (5½ x 56), Robusto (5 x 50) y Shawty (4 x 56), dice Cigar Coop en 2020; fuerza media según Stogiepress."},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown (Ecuador)","vitolas":[],"story":"Segunda línea, lanzada el 1 de octubre de 2020, de tono colorado maduro, sobre capote ecuatoriano y tripa de tabacos de Nicaragua, de Perú y de dos hojas dominicanas del Cibao; en Toro (6½ x 56), Gran Robusto (5½ x 52) y Gordito, dice Cigar Coop."},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Tercera línea, anunciada el 30 de noviembre de 2021 para fumadores de fuerza suave a media: capote nicaragüense, tripa nicaragüense y dominicana; en Belicoso (6½ x 54) y Lancero (7 x 38), en cajas de diez, dice Cigar Coop."},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Cuarta línea, en homenaje a los Tuskegee Airmen, anunciada el 7 de noviembre de 2022: capas Natural y Maduro, en Toro y en Torpedo (6½ x 52), en cajas de diez, dice Cigar Coop; el sitio web de la casa incluye en ella, en octubre de 2026, HellFighter, Warhawk Natural y 332nd Maduro."},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"Camerún","vitolas":[],"story":"Producción limitada anunciada el 20 de julio de 2026, disponible desde el 1 de agosto: capote nicaragüense, tripa de Nicaragua, de Pensilvania y de República Dominicana, en 7 x 52, en paquetes de cinco, puesta a punto con Manuel Inoa en La Aurora, dice Cigar Coop."}]',
        'Emperors Group LLC ist die Muttergesellschaft von Emperors Cut Cigars, so Cigar Coop. Stogiepress zufolge wurde das Haus 2017 in Houston, Texas, gegründet; Cigar Coop verortete es im Februar 2020 in Atlanta, Georgia. Die Website des Hauses nennt sieben Gesellschafter — Darnell Streat, geschäftsführender Gesellschafter, Maurice Holland, Darryl Redmon, Temi Bush, Robert Howard, Greg Hurt und Greg Willis — und gibt an, es sei von fünf Unternehmern gegründet worden.

Natural Pleasure, die erste Linie, erscheint 2018; sie wird bei Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos) mit Omar Ortez hergestellt, so Stogiepress. Cigar Coop zufolge wird Indulgence, die am 30. November 2021 angekündigte dritte Linie, in derselben Fabrik in Condega hergestellt. Die Jazz Series (Oktober 2020), die Red Tail Series (am 7. November 2022 angekündigt) und Prophecy (am 20. Juli 2026 angekündigt, ab dem 1. August erhältlich) stammen von La Aurora in Santiago de los Caballeros, in der Dominikanischen Republik, wo Master Blender Manuel Inoa sie mit dem Haus entwickelt hat, so Cigar Coop.

Im Oktober 2026 zeigt die Website des Hauses unter anderem die Kollektionen Jazz Series, Red Tail Series und Prophecy, und Century Premium Cigars führt Natural Pleasure, Jazz Series, Indulgence und Red Tail Series im Katalog.',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro (Nicaragua)","vitolas":[],"story":"Erste Linie, 2018 erschienen: ecuadorianisches Umblatt, Einlage aus Estelí; als Toro (6½ x 52), Grand Robusto (5½ x 56), Robusto (5 x 50) und Shawty (4 x 56), so Cigar Coop im Jahr 2020; mittlere Stärke laut Stogiepress."},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown (Ecuador)","vitolas":[],"story":"Zweite Linie, am 1. Oktober 2020 eingeführt, im Farbton colorado maduro, auf ecuadorianischem Umblatt und einer Einlage aus Tabaken aus Nicaragua und Peru sowie aus zwei dominikanischen Blättern aus dem Cibao; als Toro (6½ x 56), Gran Robusto (5½ x 52) und Gordito, so Cigar Coop."},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Dritte Linie, am 30. November 2021 für Raucher milder bis mittlerer Stärke angekündigt: nicaraguanisches Umblatt, nicaraguanische und dominikanische Einlage; als Belicoso (6½ x 54) und Lancero (7 x 38), in Kisten zu zehn Stück, so Cigar Coop."},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Vierte Linie, zu Ehren der Tuskegee Airmen, am 7. November 2022 angekündigt: Deckblätter Natural und Maduro, als Toro und als Torpedo (6½ x 52), in Kisten zu zehn Stück, so Cigar Coop; die Website des Hauses ordnet ihr im Oktober 2026 HellFighter, Warhawk Natural und 332nd Maduro zu."},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"Kamerun","vitolas":[],"story":"Limitierte Produktion, am 20. Juli 2026 angekündigt, ab dem 1. August erhältlich: nicaraguanisches Umblatt, Einlage aus Nicaragua, Pennsylvania und der Dominikanischen Republik, als 7 x 52, in Packungen zu fünf Stück, zusammen mit Manuel Inoa bei La Aurora entwickelt, so Cigar Coop."}]',
        '据Cigar Coop称，Emperors Group LLC是Emperors Cut Cigars的母公司。据Stogiepress称，品牌方成立于2017年，位于得克萨斯州休斯敦；Cigar Coop在2020年2月则称其总部设在佐治亚州亚特兰大。品牌方的网站列出七名合伙人——Darnell Streat（执行合伙人）、Maurice Holland、Darryl Redmon、Temi Bush、Robert Howard、Greg Hurt与Greg Willis——并称其由五名企业家创立。

据Stogiepress称，首条产品线Natural Pleasure于2018年推出，它在Agroindustrial Nicaragüense de Tabacos S.A.（Agrotabacos）制作，与Omar Ortez合作。据Cigar Coop称，第三条产品线Indulgence于2021年11月30日宣布，在孔德加的同一家工厂制作。Jazz Series（2020年10月）、Red Tail Series（2022年11月7日宣布）与Prophecy（2026年7月20日宣布，自8月1日起供应）均来自多米尼加共和国圣地亚哥-德洛斯卡瓦列罗斯的La Aurora，据Cigar Coop称，首席调配师Manuel Inoa在那里与品牌方共同研制了它们。

2026年10月，品牌方的网站展示多个系列，其中包括Jazz Series、Red Tail Series与Prophecy，Century Premium Cigars则将Natural Pleasure、Jazz Series、Indulgence与Red Tail Series列入目录。',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro（尼加拉瓜）","vitolas":[],"story":"首条产品线，2018年推出：茄套为厄瓜多尔烟叶，茄芯来自埃斯特利；规格为Toro（6½ x 52）、Grand Robusto（5½ x 56）、Robusto（5 x 50）与Shawty（4 x 56），据Cigar Coop于2020年称；据Stogiepress称力度中等。"},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown（厄瓜多尔）","vitolas":[],"story":"第二条产品线，于2020年10月1日推出，色泽为colorado maduro，配厄瓜多尔茄套，茄芯取自尼加拉瓜与秘鲁的烟叶，以及两种来自锡巴奥（Cibao）的多米尼加烟叶；规格为Toro（6½ x 56）、Gran Robusto（5½ x 52）与Gordito，据Cigar Coop称。"},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"第三条产品线，于2021年11月30日宣布，面向喜好温和至中等力度的烟民：茄套为尼加拉瓜烟叶，茄芯为尼加拉瓜与多米尼加烟叶；规格为Belicoso（6½ x 54）与Lancero（7 x 38），每盒十支，据Cigar Coop称。"},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"第四条产品线，向Tuskegee Airmen致敬，于2022年11月7日宣布：茄衣为Natural与Maduro，规格为Toro与Torpedo（6½ x 52），每盒十支，据Cigar Coop称；品牌方的网站在2026年10月将HellFighter、Warhawk Natural与332nd Maduro归入该系列。"},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"喀麦隆","vitolas":[],"story":"限量生产，于2026年7月20日宣布，自8月1日起供应：茄套为尼加拉瓜烟叶，茄芯取自尼加拉瓜、宾夕法尼亚州与多米尼加共和国，规格为7 x 52，每包五支，与Manuel Inoa在La Aurora共同研制，据Cigar Coop称。"}]',
        'Emperors Group LLC هي الشركة الأم لـEmperors Cut Cigars، بحسب Cigar Coop. وتقول Stogiepress إن الدار تأسست عام 2017 في هيوستن بولاية تكساس؛ أما Cigar Coop فكانت تذكر أن مقرها في أتلانتا بولاية جورجيا في فبراير 2020. ويسمّي موقع الدار سبعة شركاء — Darnell Streat، الشريك المدير، وMaurice Holland وDarryl Redmon وTemi Bush وRobert Howard وGreg Hurt وGreg Willis — ويقول إنها تأسست على يد خمسة رواد أعمال.

Natural Pleasure، الخط الأول، صدر عام 2018؛ ويُصنع لدى Agroindustrial Nicaragüense de Tabacos S.A. (Agrotabacos)، مع Omar Ortez، بحسب Stogiepress. وتقول Cigar Coop إن Indulgence، الخط الثالث الذي أُعلن عنه في 30 نوفمبر 2021، يُصنع في المصنع نفسه، في كونديغا. أما Jazz Series (أكتوبر 2020) وRed Tail Series (أُعلن عنه في 7 نوفمبر 2022) وProphecy (أُعلن عنه في 20 يوليو 2026، ومتاح اعتبارًا من 1 أغسطس) فمصدرها La Aurora في سانتياغو دي لوس كاباييروس بجمهورية الدومينيكان، حيث طوّرها مع الدار كبير خبراء المزج Manuel Inoa، بحسب Cigar Coop.

وفي أكتوبر 2026، يعرض موقع الدار، من بين مجموعات أخرى، Jazz Series وRed Tail Series وProphecy، وتُدرج Century Premium Cigars في فهرسها Natural Pleasure وJazz Series وIndulgence وRed Tail Series.',
        '[{"name":"Natural Pleasure","color":"#6B4226","force":"Medium","wrapper":"Colorado maduro (نيكاراغوا)","vitolas":[],"story":"الخط الأول، صدر عام 2018: رباط إكوادوري وحشوة من إستيلي؛ بمقاسات Toro (6½ x 52) وGrand Robusto (5½ x 56) وRobusto (5 x 50) وShawty (4 x 56)، بحسب Cigar Coop في 2020؛ وقوة متوسطة بحسب Stogiepress."},{"name":"Jazz Series","color":"#6B4226","force":null,"wrapper":"Sumatra sun grown (الإكوادور)","vitolas":[],"story":"الخط الثاني، أُطلق في 1 أكتوبر 2020، بدرجة لون colorado maduro، على رباط إكوادوري وحشوة من تبغ نيكاراغوا وبيرو ومن ورقتين دومينيكيتين من سيباو؛ بمقاسات Toro (6½ x 56) وGran Robusto (5½ x 52) وGordito، بحسب Cigar Coop."},{"name":"Indulgence","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"الخط الثالث، أُعلن عنه في 30 نوفمبر 2021 للمدخنين الذين يميلون إلى قوة من خفيفة إلى متوسطة: رباط نيكاراغوي، وحشوة نيكاراغوية ودومينيكية؛ بمقاسَي Belicoso (6½ x 54) وLancero (7 x 38)، في علب من عشرة، بحسب Cigar Coop."},{"name":"Red Tail Series","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"الخط الرابع، تكريمًا لـTuskegee Airmen، أُعلن عنه في 7 نوفمبر 2022: غلافان Natural وMaduro، بمقاسَي Toro وTorpedo (6½ x 52)، في علب من عشرة، بحسب Cigar Coop؛ ويُدرج موقع الدار تحته في أكتوبر 2026 HellFighter وWarhawk Natural و332nd Maduro."},{"name":"Prophecy","color":"#8B5A2B","force":null,"wrapper":"الكاميرون","vitolas":[],"story":"إنتاج محدود أُعلن عنه في 20 يوليو 2026، ومتاح اعتبارًا من 1 أغسطس: رباط نيكاراغوي، وحشوة من نيكاراغوا وبنسلفانيا وجمهورية الدومينيكان، بمقاس 7 x 52، في عبوات من خمسة، طُوّر مع Manuel Inoa في La Aurora، بحسب Cigar Coop."}]')
