INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('La Unica',
        'dominican',
        '1986 — Stanford Newman et Carlos Fuente Sr.',
        'Tabacalera A. Fuente, Santiago de los Caballeros, République dominicaine',
        'jcnewman.com « La Unica | J.C. Newman Cigar Co. » (2026-10-01 : la maison dit La Unica née en 1986 d''une collaboration entre Stanford J. Newman et Carlos Fuente Sr. ; fabricant Tabacalera A. Fuente, République dominicaine ; cape Ecuadorian Shade en Natural ou Connecticut Broadleaf en Maduro, liant et tripe dominicains, force Mild, une seule description technique pour toute la marque ; recette d''origine à tripe dominicaine de graine cubaine vieillie ; six formats, No. 100 (8 1/2 x 52), No. 200 (7 x 49), No. 300 (6 7/10 x 44), No. 400 (4 1/2 x 50), No. 500 (5 1/2 x 42) et No. 600 (6 x 50) ; cigares premium en bundle de cellophane, quand les bundles étaient réservés aux seconds choix de fabrique) ; jcnewman.com « J.C. Newman and Arturo Fuente – The Beginning » (2026-10-01 : le partenariat commence en 1986 à Tampa ; en 1986, Tabacalera A. Fuente roule sa première marque pour J.C. Newman, La Unica ; Cuesta-Rey, Diamond Crown, Maximus, Julius Caeser et Black Diamond suivent ; Stanford Newman, Eric Newman et Bobby Newman d''un côté, Carlos Fuente Sr. et Carlos Fuente Jr. de l''autre) ; jcnewman.com « Drew Newman and Early Trips to the Dominican Republic | J.C. Newman Cigar Co. » (2026-10-01 : le partenariat commence en 1986 avec le lancement de La Unica, premier cigare roulé à la main à la Tabacalera A. Fuente ; trajet jusqu''à Santiago) ; cigarwars.net « Tabacalera A. Fuente y Cia. » (2026-10-01 : fabrique établie en 1980 à Santiago, République dominicaine ; propriétaire Carlos Fuente Jr. ; marques dont Arturo Fuente, Ashton et Diamond Crown) ; virtualglobetrotting.com « Tabacalera Arturo Fuente (cigars) in Santiago de los Caballeros, Dominican Republic » (2026-10-01 : fabrique située à Santiago de los Caballeros, ouverte en 1980) ; cigaraficionado.com « La Unica Cigar Tour Promotes New Size and New Image » (2007-06-25 : pour les vingt ans de la marque, le président Eric Newman la fait passer du bundle à la boîte en bois ; No. 600 (6 x 50), premier format nouveau depuis la création ; Cedar Cabinet Collection ; bundle depuis 1986 ; mélange inchangé ; Tabacalera A. Fuente y Cia., République dominicaine) ; lmcigars.com « La Unica Cigars » (2026-10-01 : formats No. 100 à No. 600 en Natural et en Maduro, en stock pour la plupart, en cabinets de cèdre de vingt ; roulée à la Tabacalera A. Fuente, en République dominicaine ; Stanford J. Newman, patriarche de J.C. Newman, et Carlos Fuente Sr. à l''origine du bundle de cellophane)',
        NULL,
        'La Unica est une marque de J.C. Newman, roulée par la famille Fuente depuis 1986. La maison dit qu''elle est née d''une collaboration entre Stanford J. Newman et Carlos Fuente Sr. : en 1986, La Unica est la première marque que la Tabacalera A. Fuente roule pour J.C. Newman, avant Cuesta-Rey et Diamond Crown. La fabrique, ouverte en 1980 à Santiago de los Caballeros, en République dominicaine, roule aussi les Arturo Fuente. La maison dit que La Unica a rompu avec l''usage en proposant des cigares premium en bundle de cellophane, quand les bundles étaient réservés aux seconds choix de fabrique.

En 2007, pour les vingt ans de la marque, Eric Newman, président de J.C. Newman, la fait passer du bundle à la boîte en bois et lui ajoute un format, le No. 600 (6 x 50), le premier depuis sa création ; le mélange reste le même. En octobre 2026, la maison présente La Unica en six formats, du No. 100 (8 1/2 x 52) au No. 600, sous cape Shade équatorienne en Natural ou Connecticut Broadleaf en Maduro, sur liant dominicain, et dit encore la tirer de sa recette d''origine, à tripe dominicaine de graine cubaine vieillie ; LM Cigars la tient alors en stock, en cabinets de vingt.',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade (Équateur) ou Broadleaf","vitolas":[],"story":"Six formats, du No. 100 (8 1/2 x 52) au No. 600 (6 x 50), en Natural sous cape Shade équatorienne et en Maduro sous cape Connecticut Broadleaf, sur liant et tripe dominicains ; force douce, dit la maison, pour l''ensemble de la marque."}]',
        'La Unica is a J.C. Newman brand, rolled by the Fuente family since 1986. The house says it was born of a collaboration between Stanford J. Newman and Carlos Fuente Sr.: in 1986, La Unica was the first brand that Tabacalera A. Fuente rolled for J.C. Newman, before Cuesta-Rey and Diamond Crown. The factory, opened in 1980 in Santiago de los Caballeros, in the Dominican Republic, also rolls Arturo Fuente. The house says that La Unica broke with convention by offering premium cigars in a cellophane bundle, when bundles were reserved for factory seconds.

In 2007, to mark the brand''s twenty years, Eric Newman, president of J.C. Newman, moved it from the bundle to the wooden box and added a size to it, the No. 600 (6 x 50), the first since its creation; the blend stays the same. In October 2026, the house presents La Unica in six sizes, from the No. 100 (8 1/2 x 52) to the No. 600, under an Ecuadorian Shade wrapper in Natural or Connecticut Broadleaf in Maduro, on a Dominican binder, and says it still draws it from its original recipe, with a Dominican filler of aged Cuban seed; LM Cigars then holds it in stock, in cabinets of twenty.',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade (Ecuador) or Broadleaf","vitolas":[],"story":"Six sizes, from the No. 100 (8 1/2 x 52) to the No. 600 (6 x 50), in Natural under an Ecuadorian Shade wrapper and in Maduro under a Connecticut Broadleaf wrapper, on a Dominican binder and filler; mild strength, says the house, for the whole brand."}]',
        'La Unica es una marca de J.C. Newman, liada por la familia Fuente desde 1986. La casa dice que nació de una colaboración entre Stanford J. Newman y Carlos Fuente Sr.: en 1986, La Unica es la primera marca que la Tabacalera A. Fuente lía para J.C. Newman, antes de Cuesta-Rey y Diamond Crown. La fábrica, abierta en 1980 en Santiago de los Caballeros, en República Dominicana, lía también los Arturo Fuente. La casa dice que La Unica rompió con la costumbre al ofrecer puros premium en bundle de celofán, cuando los bundles estaban reservados a los puros de segunda selección de fábrica.

En 2007, con motivo de los veinte años de la marca, Eric Newman, presidente de J.C. Newman, la hace pasar del bundle a la caja de madera y le añade un formato, el No. 600 (6 x 50), el primero desde su creación; la mezcla sigue siendo la misma. En octubre de 2026, la casa presenta La Unica en seis formatos, del No. 100 (8 1/2 x 52) al No. 600, con capa Shade ecuatoriana en Natural o Connecticut Broadleaf en Maduro, sobre capote dominicano, y dice seguir elaborándola según su receta original, con tripa dominicana de semilla cubana envejecida; LM Cigars la tiene entonces en existencias, en cabinets de veinte.',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade (Ecuador) o Broadleaf","vitolas":[],"story":"Seis formatos, del No. 100 (8 1/2 x 52) al No. 600 (6 x 50), en Natural con capa Shade ecuatoriana y en Maduro con capa Connecticut Broadleaf, sobre capote y tripa dominicanos; fuerza suave, dice la casa, para el conjunto de la marca."}]',
        'La Unica ist eine Marke von J.C. Newman, die seit 1986 von der Familie Fuente gerollt wird. Das Haus gibt an, sie sei aus einer Zusammenarbeit zwischen Stanford J. Newman und Carlos Fuente Sr. hervorgegangen: 1986 ist La Unica die erste Marke, die die Tabacalera A. Fuente für J.C. Newman rollt, noch vor Cuesta-Rey und Diamond Crown. Die Fabrik, 1980 in Santiago de los Caballeros in der Dominikanischen Republik eröffnet, rollt auch Arturo Fuente. Das Haus gibt an, La Unica habe mit dem Brauch gebrochen, indem sie Premium-Zigarren in einem bundle aus Cellophan angeboten habe, zu einer Zeit, als bundles der Zweitwahl der Fabrik vorbehalten waren.

2007, zum zwanzigjährigen Bestehen der Marke, überführt Eric Newman, Präsident von J.C. Newman, sie vom bundle in die Holzkiste und fügt ihr ein Format hinzu, die No. 600 (6 x 50), das erste seit ihrer Entstehung; die Mischung bleibt dieselbe. Im Oktober 2026 präsentiert das Haus La Unica in sechs Formaten, von der No. 100 (8 1/2 x 52) bis zur No. 600, unter einem ecuadorianischen Deckblatt Shade als Natural oder einem Connecticut Broadleaf als Maduro, auf dominikanischem Umblatt, und gibt an, sie weiterhin nach ihrem ursprünglichen Rezept herzustellen, mit einer dominikanischen Einlage aus gereiftem kubanischem Saatgut; LM Cigars hat sie dann auf Lager, in Cabinets zu zwanzig Stück.',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade (Ecuador) oder Broadleaf","vitolas":[],"story":"Sechs Formate, von der No. 100 (8 1/2 x 52) bis zur No. 600 (6 x 50), als Natural unter einem ecuadorianischen Deckblatt Shade und als Maduro unter einem Deckblatt Connecticut Broadleaf, auf dominikanischem Umblatt und dominikanischer Einlage; milde Stärke, so das Haus, für die gesamte Marke."}]',
        'La Unica是J.C. Newman的品牌，自1986年起由Fuente家族卷制。品牌方称，它诞生于Stanford J. Newman与Carlos Fuente Sr.的合作：1986年，La Unica是Tabacalera A. Fuente为J.C. Newman卷制的首个品牌，早于Cuesta-Rey与Diamond Crown。这家工厂于1980年在多米尼加共和国的圣地亚哥-德洛斯卡瓦列罗斯开业，同时也卷制Arturo Fuente。品牌方称，La Unica打破了惯例，推出以玻璃纸bundle包装的精品雪茄，而当时bundle专用于工厂的二等品。

2007年，值品牌二十周年之际，J.C. Newman的总裁Eric Newman将其从bundle改为木盒包装，并为其新增一个规格，即No. 600（6 x 50），这是自创立以来的首个新增规格；拼配保持不变。2026年10月，品牌方展示的La Unica共有六种规格，从No. 100（8 1/2 x 52）到No. 600；Natural采用厄瓜多尔Shade茄衣，Maduro采用Connecticut Broadleaf茄衣，均配多米尼加茄套；品牌方还称其仍源自原始配方，即采用多米尼加茄芯，源自经陈放的古巴种子；LM Cigars当时备有现货，为二十支装的cabinets。',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade（厄瓜多尔）或Broadleaf","vitolas":[],"story":"共六种规格，从No. 100（8 1/2 x 52）到No. 600（6 x 50）；Natural采用厄瓜多尔Shade茄衣，Maduro采用Connecticut Broadleaf茄衣，均配多米尼加茄套与茄芯；据品牌方称，整个品牌力度温和。"}]',
        'La Unica علامة لـJ.C. Newman، تلفّها عائلة Fuente منذ عام 1986. وتقول الدار إنها وُلدت من تعاون بين Stanford J. Newman وCarlos Fuente Sr.؛ ففي عام 1986 كانت La Unica أول علامة تلفّها Tabacalera A. Fuente لصالح J.C. Newman، قبل Cuesta-Rey وDiamond Crown. والمصنع، الذي افتُتح عام 1980 في سانتياغو دي لوس كاباييروس بجمهورية الدومينيكان، يلفّ أيضًا سيجار Arturo Fuente. وتقول الدار إن La Unica كسرت المألوف حين قدّمت سيجارًا فاخرًا في bundle من السيلوفان، في وقت كانت فيه bundles مخصصة لسيجار الدرجة الثانية من المصنع.

وفي عام 2007، بمناسبة مرور عشرين عامًا على العلامة، نقلها Eric Newman، رئيس J.C. Newman، من bundle إلى علبة خشبية وأضاف إليها مقاسًا، هو No. 600 (6 x 50)، وهو الأول منذ إنشائها؛ وتبقى الخلطة نفسها. وفي أكتوبر 2026، تعرض الدار La Unica بستة مقاسات، من No. 100 (8 1/2 x 52) إلى No. 600، بغلاف Shade إكوادوري في Natural أو Connecticut Broadleaf في Maduro، على رباط دومينيكي، وتقول إنها لا تزال تستمدها من وصفتها الأصلية، بحشوة دومينيكية من بذور كوبية معتّقة؛ وتحتفظ بها LM Cigars آنذاك في المخزون، في cabinets من عشرين.',
        '[{"name":"La Unica","color":"#C9A96E","force":"Mild","wrapper":"Shade (الإكوادور) أو Broadleaf","vitolas":[],"story":"ستة مقاسات، من No. 100 (8 1/2 x 52) إلى No. 600 (6 x 50)، في Natural بغلاف Shade إكوادوري وفي Maduro بغلاف Connecticut Broadleaf، على رباط وحشوة دومينيكيين؛ قوة خفيفة، بحسب الدار، للعلامة بأكملها."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Herr Lehmann ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Herr Lehmann',
        'germany',
        '1924 — Oskar Lehmann, Seelbach ; reprise 2014',
        'Usine propre — Cigarren-Manufaktur Herr Lehmann, Lotzbeckstraße 47, Lahr (Forêt-Noire)',
        'herr-lehmann.com « Herr Lehmann » (2026-10-01 : le site de la maison annonce une refonte en cours ; courriel de contact ; points de vente à Lahr (Bonacelli, Lotzbeckstr. 47 ; Schäfers Eck, Kirchstr. 1) et à Fribourg-en-Brisgau (Lust auf Gut, Gerberau 9A) ; en ligne Cigarworld et Dein Dorfladen ; aucun récit d''histoire sur la page) ; deindorfleben.de « Herr Lehmann » (page de présentation, 2026-10-01 : adresse Lotzbeckstr. 47, 1. OG, 77933 Lahr/Schwarzwald ; horaires du lundi au vendredi de 10 h à 18 h et le samedi de 10 h à 16 h ; atelier fondé en 1924 par Oskar Lehmann et son épouse, repris au milieu des années 1960 par leur fils Oskar et sa femme Maria, puis en 2014 par les propriétaires actuels, qui transportent le matériel de Seelbach à Lahr ; cigares et cigarillos roulés à la main, tabac Geudertheimer régional, cape de Sumatra ; ventes principales No. 3, No. 7 et No. 1 en édition limitée) ; deindorfleben.de « Herr Lehmann » (page partenaire, 2026-10-01 : Lotzbeckstr. 47 ; cigares No. 3, No. 5 et No. 7 en vente ; gin, liqueur d''herbes et eau-de-vie de pomme ; la Schwarzwald-Kollektion non disponible) ; deindorfleben.de « Zigarren drehen Archive » (2026-10-01 : No. 1 Schwarzwald-Rillo, No. 1 édition limitée en boîte décorée, No. 3 en boîte de douze, No. 5 et No. 7 en stock ; Schwarzwald-Kollektion non disponible) ; deindorfleben.de « Dorfladen Nr. 18: Zigarrenmanufaktur Herr Lehmann » (2021-08-13 : propriétaires Gregor Grüb et Klaus Harisch ; l''affaire née à Seelbach, où Oskar et Maria Lehmann roulaient des cigares ; tables et outils transmis aux nouveaux propriétaires à Lahr ; le nom Lehmann conservé en hommage à Oskar Lehmann ; tabac Geudertheimer de l''Ortenau, seule la cape importée de Sumatra ; cigares roulés à la main) ; netzwerk-suedbaden.de « Zigarrenwerkstatt: Frisch gewickelt bei Herr Lehmann » (2022-03-01, Susanne Maerz : atelier au centre de la vieille ville de Lahr, en face de l''ancien hôtel de ville ; exploité depuis mi-2014 par Gregor Grüb et Klaus Harisch, qui l''ont repris d''Oskar et Maria Lehmann, de Seelbach ; la poupée formée avec une bande de cuir actionnée au pied, pressée vingt-quatre heures dans des moules de bois, la cape posée à la main ; 95 % de Geudertheimer, cape de Sumatra achetée ; spiritueux et café ajoutés à partir de 2016, d''abord le Schwarzwald Whisky) ; waldrausch-magazin.de « Zeitloser Genuss » (2020-03-20, Mareike Kratt : maison fondée en 1924 par Oskar Lehmann et son épouse ; reprise dans les années 1960 par leur fils Oskar et Maria ; en 2014, nouveaux propriétaires, matériel transporté de Seelbach à Lahr ; tabac Geudertheimer cultivé exclusivement pour Herr Lehmann à partir de 2015) ; cigarworld.de « Buy Herr Lehmann Cigarren-Manufaktur cigars » (2026-10-01 : série au catalogue depuis le 29 septembre 2016 ; Oskar Lehmann Zigarren-Manufaktur de 1924, reprise en 2014 par Gregor Grüb et Klaus Harisch ; tripe et liant en Geudertheimer de l''Ortenau cultivé près de la manufacture ; No. 5 Schwarzwald, No. 7 Krönung et No. 8 Gipfel disponibles) ; cigarworld.de « Herr Lehmann | Cigarworld.de » (2026-10-01 : No. 3 Sumatra en cigarillos, 9,20 cm ; No. 5 Schwarzwald ; No. 7 Krönung ; No. 8 Gipfel) ; cigarworld.de « Herr Lehmann No. 5 Schwarzwald » (2026-10-01 : producteur HAGR Cigars GbR (Herr Lehmann), Lotzbeckstr. 47, 77933 Lahr ; cape Sumatra d''Indonésie, liant et tripe allemands ; torpedo 4,75 pouces x 50 ; totalmente a mano, longfiller ; force douce à moyenne ; disponible) ; cigarworld.de « Herr Lehmann No. 7 Krönung (Glastube) » (2026-10-01 : cape du Brésil, liant et tripe allemands ; 5,375 pouces x 42 ; totalmente a mano, longfiller ; disponible) ; cigarworld.de « Herr Lehmann Cigarren-Manufaktur No. 8 Der Schwarzwald Gipfel Glastube » (2026-10-01 : cape Sumatra, liant et tripe allemands ; 5,125 pouces x 50 ; totalmente a mano, longfiller ; au catalogue depuis le 7 avril 2022 ; disponible) ; bonacelli-webshop.de « Genuss pur in der Lahrer Kleiderfabrik » (2024-07-18, Dirk Frischauf : la manufacture de cigares Herr Lehmann de Lahr présentée avec des cigares faits main au tabac Geudertheimer régional et des distillats Herr Lehmann, whisky et gin) ; badische-zeitung.de « Die Lahrer Zigarrenmanufaktur “Herr Lehmann” zieht in neue Räume » (page fermée aux robots, lue par son titre : la manufacture déménage dans de nouveaux locaux) ; badische-zeitung.de « Zigarrenmanufaktur “Herr Lehmann” in Lahr muss unfreiwillig früher umziehen » (page fermée aux robots, lue par son titre : un déménagement plus tôt que prévu)',
        NULL,
        'Herr Lehmann est une manufacture de cigares de Lahr, dans la Forêt-Noire. Elle remonte à 1924 : Oskar Lehmann et son épouse la fondent à Seelbach, et leur fils Oskar, avec sa femme Maria, la reprend au milieu des années 1960, dit Dein Dorfladen. En 2014, Gregor Grüb et Klaus Harisch la reprennent et transportent le matériel de Seelbach à Lahr, en gardant le nom de Lehmann en hommage à Oskar Lehmann.

Cigarworld.de classe les cigares totalmente a mano, en longfiller, avec un liant et une tripe allemands de tabac Geudertheimer, cultivé dans l''Ortenau, sous une cape de Sumatra, sauf le No. 7, à cape brésilienne. En mars 2022, Netzwerk Südbaden décrit un atelier de la vieille ville de Lahr où l''on forme la poupée avec une bande de cuir actionnée au pied, avant de la presser vingt-quatre heures dans des moules de bois et d''y poser la cape à la main. En octobre 2026, la maison annonce sur son site une refonte en cours et y liste ses points de vente : deux à Lahr, un à Fribourg-en-Brisgau, et en ligne Cigarworld.de et Dein Dorfladen, qui donnent l''atelier à la Lotzbeckstraße 47, à Lahr, et tiennent ses cigares en stock.

La maison vend aussi un gin, une liqueur d''herbes et une eau-de-vie de pomme, dit Dein Dorfladen ; Netzwerk Südbaden date de 2016 son premier spiritueux, un whisky de la Forêt-Noire.',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra (Indonésie)","vitolas":[],"story":"Cigares numérotés : No. 1 Schwarzwald-Rillo et son édition limitée en boîte décorée, No. 3 en boîte de douze, classé en cigarillos par Cigarworld.de, No. 5 Schwarzwald (torpedo 4 3/4 x 50, aussi en tube de verre), No. 7 Krönung (5 3/8 x 42) et No. 8 Gipfel (5 1/8 x 50) ; force douce à moyenne, dit Cigarworld.de du No. 5."}]',
        'Herr Lehmann is a cigar factory in Lahr, in the Black Forest. It goes back to 1924: Oskar Lehmann and his wife founded it in Seelbach, and their son Oskar, with his wife Maria, took it over in the mid-1960s, says Dein Dorfladen. In 2014, Gregor Grüb and Klaus Harisch took it over and moved the equipment from Seelbach to Lahr, keeping the Lehmann name in tribute to Oskar Lehmann.

Cigarworld.de classifies the cigars as totalmente a mano, longfiller, with a German binder and filler of Geudertheimer tobacco, grown in the Ortenau, under a Sumatra wrapper, except the No. 7, which has a Brazilian wrapper. In March 2022, Netzwerk Südbaden describes a workshop in the old town of Lahr where the bunch is formed with a foot-operated leather band, before being pressed for twenty-four hours in wooden moulds and having the wrapper laid on by hand. In October 2026, the house announces on its website that an overhaul is under way and lists its points of sale there: two in Lahr, one in Freiburg im Breisgau, and online Cigarworld.de and Dein Dorfladen, which locate the workshop at Lotzbeckstraße 47, in Lahr, and hold its cigars in stock.

The house also sells a gin, a herbal liqueur and an apple brandy, says Dein Dorfladen; Netzwerk Südbaden dates its first spirit to 2016, a Black Forest whisky.',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra (Indonesia)","vitolas":[],"story":"Numbered cigars: No. 1 Schwarzwald-Rillo and its limited edition in a decorated box, No. 3 in a box of twelve, classed as cigarillos by Cigarworld.de, No. 5 Schwarzwald (torpedo 4 3/4 x 50, also in a glass tube), No. 7 Krönung (5 3/8 x 42) and No. 8 Gipfel (5 1/8 x 50); mild to medium strength, says Cigarworld.de of the No. 5."}]',
        'Herr Lehmann es una manufactura de puros de Lahr, en la Selva Negra. Se remonta a 1924: Oskar Lehmann y su esposa la fundan en Seelbach, y su hijo Oskar, con su esposa Maria, la releva a mediados de los años 1960, dice Dein Dorfladen. En 2014, Gregor Grüb y Klaus Harisch la retoman y trasladan el equipamiento de Seelbach a Lahr, conservando el nombre de Lehmann en homenaje a Oskar Lehmann.

Cigarworld.de clasifica los puros como totalmente a mano, longfiller, con capote y tripa alemanes de tabaco Geudertheimer, cultivado en la Ortenau, bajo capa de Sumatra, salvo el No. 7, de capa brasileña. En marzo de 2022, Netzwerk Südbaden describe un taller del casco antiguo de Lahr donde se forma el bonche con una banda de cuero accionada con el pie, antes de prensarlo veinticuatro horas en moldes de madera y colocarle la capa a mano. En octubre de 2026, la casa anuncia en su sitio web una renovación en curso y enumera en él sus puntos de venta: dos en Lahr, uno en Friburgo de Brisgovia, y en línea Cigarworld.de y Dein Dorfladen, que sitúan el taller en la Lotzbeckstraße 47, en Lahr, y tienen sus puros en existencias.

La casa vende también una ginebra, un licor de hierbas y un aguardiente de manzana, dice Dein Dorfladen; Netzwerk Südbaden data en 2016 su primer destilado, un whisky de la Selva Negra.',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra (Indonesia)","vitolas":[],"story":"Puros numerados: No. 1 Schwarzwald-Rillo y su edición limitada en caja decorada, No. 3 en caja de doce, clasificado como cigarritos por Cigarworld.de, No. 5 Schwarzwald (torpedo 4 3/4 x 50, también en tubo de vidrio), No. 7 Krönung (5 3/8 x 42) y No. 8 Gipfel (5 1/8 x 50); fuerza de suave a media, dice Cigarworld.de del No. 5."}]',
        'Herr Lehmann ist eine Zigarrenmanufaktur in Lahr im Schwarzwald. Sie geht auf das Jahr 1924 zurück: Oskar Lehmann und seine Frau gründen sie in Seelbach, und ihr Sohn Oskar übernimmt sie mit seiner Frau Maria Mitte der 1960er Jahre, so Dein Dorfladen. 2014 übernehmen Gregor Grüb und Klaus Harisch sie und transportieren die Ausrüstung von Seelbach nach Lahr, wobei sie den Namen Lehmann zu Ehren von Oskar Lehmann beibehalten.

Cigarworld.de stuft die Zigarren als totalmente a mano, longfiller ein, mit einem deutschen Umblatt und einer deutschen Einlage aus Geudertheimer-Tabak, angebaut in der Ortenau, unter einem Deckblatt aus Sumatra, außer der No. 7 mit brasilianischem Deckblatt. Im März 2022 beschreibt Netzwerk Südbaden eine Werkstatt in der Lahrer Altstadt, in der der Wickel mit einem fußbetätigten Lederband geformt wird, bevor er vierundzwanzig Stunden in Holzformen gepresst und das Deckblatt von Hand aufgelegt wird. Im Oktober 2026 kündigt das Haus auf seiner Website eine laufende Überarbeitung an und listet dort seine Verkaufsstellen auf: zwei in Lahr, eine in Freiburg im Breisgau, und online Cigarworld.de und Dein Dorfladen, die die Werkstatt in der Lotzbeckstraße 47 in Lahr verorten und seine Zigarren auf Lager haben.

Das Haus verkauft außerdem einen Gin, einen Kräuterlikör und einen Apfelbrand, so Dein Dorfladen; Netzwerk Südbaden datiert seine erste Spirituose, einen Schwarzwald-Whisky, auf 2016.',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra (Indonesien)","vitolas":[],"story":"Nummerierte Zigarren: No. 1 Schwarzwald-Rillo und ihre limitierte Edition in dekorierter Kiste, No. 3 in einer Kiste zu zwölf Stück, von Cigarworld.de als Zigarillos eingestuft, No. 5 Schwarzwald (torpedo 4 3/4 x 50, auch in einer Glastube), No. 7 Krönung (5 3/8 x 42) und No. 8 Gipfel (5 1/8 x 50); milde bis mittlere Stärke, so Cigarworld.de zur No. 5."}]',
        'Herr Lehmann是位于黑森林地区拉尔的一家雪茄工厂。它可追溯到1924年：Oskar Lehmann与其妻子在塞尔巴赫创办了它，其子Oskar与妻子Maria于1960年代中期接手，据Dein Dorfladen称。2014年，Gregor Grüb与Klaus Harisch接手，并将设备从塞尔巴赫运到拉尔，同时为向Oskar Lehmann致敬而保留了Lehmann这一名称。

Cigarworld.de将这些雪茄归类为totalmente a mano、longfiller，茄套与茄芯均为德国产，采用在奥尔特瑙种植的Geudertheimer烟叶，茄衣为Sumatra，唯独No. 7采用巴西茄衣。2022年3月，Netzwerk Südbaden描述了拉尔老城区的一间工坊：那里的茄束用一条以脚操作的皮革带成形，随后在木制模具中压制二十四小时，再以手覆上茄衣。2026年10月，品牌方在其网站上宣布正在进行改造，并列出其销售点：拉尔两处，弗赖堡一处，另有线上渠道Cigarworld.de与Dein Dorfladen，二者将工坊定位于拉尔的Lotzbeckstraße 47，并备有其雪茄现货。

品牌方还销售金酒、草本利口酒与苹果白兰地，据Dein Dorfladen称；Netzwerk Südbaden将其首款烈酒，即一款黑森林威士忌，定在2016年。',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra（印度尼西亚）","vitolas":[],"story":"编号雪茄：No. 1 Schwarzwald-Rillo及其装饰盒装的限量版，No. 3为十二支装盒装，被Cigarworld.de归为小雪茄，No. 5 Schwarzwald（torpedo 4 3/4 x 50，另有玻璃管装），No. 7 Krönung（5 3/8 x 42）与No. 8 Gipfel（5 1/8 x 50）；据Cigarworld.de称，No. 5力度温和至中等。"}]',
        'Herr Lehmann مصنع سيجار في لار، في الغابة السوداء. يعود تاريخه إلى عام 1924: أسّسه Oskar Lehmann وزوجته في زيلباخ، وتولّاه ابنهما Oskar مع زوجته Maria في منتصف عقد 1960، بحسب Dein Dorfladen. وفي عام 2014، تسلّمه Gregor Grüb وKlaus Harisch ونقلا المعدّات من زيلباخ إلى لار، مع الإبقاء على اسم Lehmann تكريمًا لـOskar Lehmann.

تصنّف Cigarworld.de السيجار ضمن totalmente a mano، longfiller، برباط وحشوة ألمانيين من تبغ Geudertheimer المزروع في أورتناو، تحت غلاف من Sumatra، باستثناء No. 7 ذي الغلاف البرازيلي. وفي مارس 2022، يصف Netzwerk Südbaden ورشة في المدينة القديمة في لار تُشكَّل فيها الحزمة بشريط جلدي يُشغَّل بالقدم، قبل أن تُضغط أربعًا وعشرين ساعة في قوالب خشبية ويوضع عليها الغلاف يدويًا. وفي أكتوبر 2026، تعلن الدار على موقعها تجديدًا جاريًا وتسرد فيه نقاط بيعها: نقطتان في لار، ونقطة واحدة في فرايبورغ إم برايسغاو، وعبر الإنترنت Cigarworld.de وDein Dorfladen، اللذان يحدّدان موقع الورشة في Lotzbeckstraße 47 في لار، ويحتفظان بسيجارها في المخزون.

وتبيع الدار أيضًا جينًا وليكور الأعشاب وبراندي التفاح، بحسب Dein Dorfladen؛ وتؤرّخ Netzwerk Südbaden أول مشروب روحي للدار، وهو ويسكي الغابة السوداء، بعام 2016.',
        '[{"name":"Herr Lehmann","color":"#A0522D","force":"Mild-Medium","wrapper":"Sumatra (إندونيسيا)","vitolas":[],"story":"سيجار مرقّم: No. 1 Schwarzwald-Rillo وإصداره المحدود في علبة مزخرفة، وNo. 3 في علبة من اثني عشر، وتصنّفه Cigarworld.de ضمن السيجاريلو، وNo. 5 Schwarzwald (torpedo 4 3/4 x 50، ويتوفر أيضًا في أنبوب زجاجي)، وNo. 7 Krönung (5 3/8 x 42)، وNo. 8 Gipfel (5 1/8 x 50)؛ قوة من خفيفة إلى متوسطة، بحسب Cigarworld.de بخصوص No. 5."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── La Fontana ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('La Fontana',
        'honduras',
        '1992 ou 1993 — Sal Fontana ou Tino Argudin',
        'Usine du groupe Davidoff — Agroindustrias Diadema Zona Franca Honduras SA (Diadema Cigars de Honduras), Danlí',
        'oettingerdavidoff.com « Group Companies | Oettinger Davidoff » (2026-10-01 : le groupe liste Agroindustrias Diadema Zona Franca Honduras SA, à Danlí, El Paraíso, Honduras ; Camacho, Zino Nicaragua, Baccarat et La Fontana y sont roulées à la main, puis exportées vers les États-Unis et l''Europe) ; cigaraficionado.com « Davidoff Opens New Camacho Factory » (2017-05-25 : la fabrique Diadema Cigars de Honduras, S.A. remplace AgroIndustrias Laepe S.A., de Davidoff ; elle fait la majorité du portefeuille Camacho et aussi Baccarat, La Fontana, National Brand, LegendArio et des marques sous contrat ; plus de 500 employés à Danlí) ; cigar-coop.com « Cigar News: Davidoff Announces Official Opening of New Honduran Factory » (2017-05-24 : la fabrique s''appelle Diadema Cigars de Honduras SA et remplace la fabrique Camacho Agroindustria Laepe SA ; la croissance de Camacho et d''autres marques dont La Fontana motive le déménagement ; production déjà commencée) ; trbusiness.com « Oettinger Davidoff buys Camacho » (2008-10-14 : Oettinger Davidoff Group rachète Camacho Cigars, de Danlí et de Miami, et dix marques, dont Camacho, Baccarat The Game, La Fontana, Legend-Ario et National Brand ; Julio Eiroa établit Caribe Imported Cigars en 1987 ; Christian Eiroa à la tête du portefeuille) ; cigaraficionado.com « An Interview with Christian Eiroa » (2005 : Christian Eiroa, héritier de la marque Camacho ; sa famille cultive du tabac de semence cubaine dans la vallée de Jamastran, au Honduras, et fabrique 14 millions de cigares Camacho, Baccarat et autres dans une usine de Danlí appelée Tabacos Rancho Jamastran ; il dit que Sal Fontana revient en 1992 et lance La Fontana ; la famille a Baccarat et La Fontana) ; cigarstorehouse.com « La Fontana Puccini Cigars » (2026-10-01 : en stock ; texte du détaillant : Tino Argudin quitte Cuba avec des graines de Pinar del Río et compose au Rancho Jamastran, au Honduras, un mélange digne du tabac de son île ; cape Jamastran Connecticut Gold, liant mexicain, tripe hondurienne ; Puccini 6 1/2 x 44 ; origine Honduras ; force douce à moyenne) ; cigarcentury.com « La Fontana Vintage - Century Premium Cigars » (2026-10-01 : cigares faits main, inaugurés en 1993 ; Honduras ; dix formats, Belicoso 6 x 54, Cristales 6 1/2 x 44, Da Vinci 6 7/8 x 48, Dante 6 1/8 x 38, Galileo 5 x 50, Michelangelo 7 1/2 x 52, Mona Lisa 4 3/4 x 46, Puccini 6 1/2 x 44, Rossini 5 1/2 x 33 et Verdi 5 1/2 x 44 ; force Mild to Medium) ; cigarcentury.com « La Fontana Vintage - Puccini with Reviews - Century Premium Cigars » (2026-10-01 : fabricant Davidoff Group ; liant mexicain ; force douce à moyenne) ; legendcigars.com « La Fontana Vintage – Legends Cigar » (2026-10-01 : faite depuis 1993, désormais au Davidoff Group ; cape Connecticut shade brun doré, liant mexicain, tripe hondurienne long-leaf ; force douce à moyenne ; cinq formats, Belicoso, Da Vinci, Galileo, Michelangelo et Puccini ; épuisée) ; egars.com « La Fontana » (2026-10-01 : lancée en 1993 ; cape Connecticut dorée ou Connecticut Maduro chocolat ; plus légère que les puros honduriens habituels ; Galileo 5 x 50 et Michelangelo 7 1/2 x 52 ; en rupture de stock) ; 70cigars.com « La Fontana Vintage – 70Cigars » (2026-10-01 : cinq formats en stock, Belicoso, Da Vinci, Michelangelo, Galileo et Puccini ; cape, liant et tripe honduriens ; force Mild ; origine du cigare donnée au Nicaragua) ; cigarworld.de « Buy La Fontana cigars | Cigarworld » (2026-10-01 : série au catalogue depuis le 4 juin 2002 ; dix variantes, toutes épuisées) ; cigarworld.de « La Fontana Dante » (2026-10-01 : faite à la main, longfiller ; cape de variété Connecticut du Honduras, liant et tripe du Honduras ; au catalogue depuis le 20 avril 2004 ; épuisée) ; neptunecigar.com « La Fontana Vintage Cigars - Neptune Cigar » (2026-10-01 : La Fontana Vintage au catalogue du détaillant)',
        NULL,
        'Les débuts de La Fontana se racontent de deux façons. Christian Eiroa, dont la famille cultive du tabac de semence cubaine dans la vallée de Jamastran, au Honduras, et fabrique ses cigares dans une usine de Danlí appelée Tabacos Rancho Jamastran, dit en 2005 que Sal Fontana revient en 1992 et lance La Fontana. Un texte de Cigar Storehouse la rattache à Tino Argudin, parti de Cuba avec des graines de Pinar del Río et qui compose au Rancho Jamastran un mélange digne du tabac de son île ; Century Premium Cigars, Legend Cigars et eGars la datent de 1993.

En 2008, Oettinger Davidoff rachète Camacho Cigars, de Danlí et de Miami, et avec elle dix marques, dont Baccarat et La Fontana. En mai 2017, la nouvelle fabrique de Camacho, Diadema Cigars de Honduras, ouvre à Danlí et remplace AgroIndustrias Laepe ; elle fait la majorité des Camacho, et aussi La Fontana. En octobre 2026, le groupe dit sur son site que La Fontana, avec Camacho et Baccarat, est roulée à la main chez Agroindustrias Diadema Zona Franca Honduras SA, à Danlí, puis exportée vers les États-Unis et l''Europe.

En octobre 2026, Legend Cigars et Cigar Storehouse décrivent La Fontana sous cape Connecticut, sur liant mexicain et tripe hondurienne, d''une force douce à moyenne ; 70Cigars donne un liant hondurien. Cigar Storehouse et 70Cigars la tiennent en stock, Legend Cigars et Cigarworld.de l''affichent épuisée.',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Cape Connecticut dorée, sur liant mexicain selon Legend Cigars et Cigar Storehouse, hondurien selon 70Cigars, et tripe hondurienne ; dix formats chez Century Premium Cigars, dont Rossini (5 1/2 x 33), Puccini (6 1/2 x 44) et Michelangelo (7 1/2 x 52) ; force douce à moyenne, dit Century Premium Cigars."}]',
        'The beginnings of La Fontana are told in two ways. Christian Eiroa, whose family grows Cuban-seed tobacco in the Jamastran Valley, in Honduras, and makes its cigars in a factory in Danlí called Tabacos Rancho Jamastran, says in 2005 that Sal Fontana came back in 1992 and launched La Fontana. A text from Cigar Storehouse ties it to Tino Argudin, who left Cuba with seeds from Pinar del Río and composed at Rancho Jamastran a blend worthy of the tobacco of his island; Century Premium Cigars, Legend Cigars and eGars date it to 1993.

In 2008, Oettinger Davidoff bought Camacho Cigars, of Danlí and Miami, and with it ten brands, including Baccarat and La Fontana. In May 2017, Camacho''s new factory, Diadema Cigars de Honduras, opened in Danlí and replaced AgroIndustrias Laepe; it makes the majority of Camacho cigars, and La Fontana as well. In October 2026, the group says on its website that La Fontana, with Camacho and Baccarat, is rolled by hand at Agroindustrias Diadema Zona Franca Honduras SA, in Danlí, then exported to the United States and Europe.

In October 2026, Legend Cigars and Cigar Storehouse describe La Fontana under a Connecticut wrapper, on a Mexican binder and Honduran filler, of mild to medium strength; 70Cigars gives a Honduran binder. Cigar Storehouse and 70Cigars hold it in stock; Legend Cigars and Cigarworld.de show it as sold out.',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Golden Connecticut wrapper, on a Mexican binder according to Legend Cigars and Cigar Storehouse, Honduran according to 70Cigars, and a Honduran filler; ten sizes at Century Premium Cigars, including Rossini (5 1/2 x 33), Puccini (6 1/2 x 44) and Michelangelo (7 1/2 x 52); mild to medium strength, says Century Premium Cigars."}]',
        'Los inicios de La Fontana se cuentan de dos maneras. Christian Eiroa, cuya familia cultiva tabaco de semilla cubana en el valle de Jamastrán, en Honduras, y elabora sus puros en una fábrica de Danlí llamada Tabacos Rancho Jamastran, dice en 2005 que Sal Fontana regresó en 1992 y lanzó La Fontana. Un texto de Cigar Storehouse la vincula con Tino Argudin, que salió de Cuba con semillas de Pinar del Río y compuso en el Rancho Jamastran una mezcla digna del tabaco de su isla; Century Premium Cigars, Legend Cigars y eGars la fechan en 1993.

En 2008, Oettinger Davidoff compra Camacho Cigars, de Danlí y de Miami, y con ella diez marcas, entre ellas Baccarat y La Fontana. En mayo de 2017, la nueva fábrica de Camacho, Diadema Cigars de Honduras, abre en Danlí y sustituye a AgroIndustrias Laepe; elabora la mayoría de los Camacho, y también La Fontana. En octubre de 2026, el grupo dice en su sitio web que La Fontana, con Camacho y Baccarat, se lía a mano en Agroindustrias Diadema Zona Franca Honduras SA, en Danlí, y luego se exporta a Estados Unidos y a Europa.

En octubre de 2026, Legend Cigars y Cigar Storehouse describen La Fontana con capa Connecticut, sobre capote mexicano y tripa hondureña, de fuerza suave a media; 70Cigars da un capote hondureño. Cigar Storehouse y 70Cigars la tienen en existencias; Legend Cigars y Cigarworld.de la muestran agotada.',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Capa Connecticut dorada, sobre capote mexicano según Legend Cigars y Cigar Storehouse, hondureño según 70Cigars, y tripa hondureña; diez formatos en Century Premium Cigars, entre ellos Rossini (5 1/2 x 33), Puccini (6 1/2 x 44) y Michelangelo (7 1/2 x 52); fuerza de suave a media, dice Century Premium Cigars."}]',
        'Die Anfänge von La Fontana werden auf zwei Arten erzählt. Christian Eiroa, dessen Familie Tabak aus kubanischem Saatgut im Jamastran-Tal in Honduras anbaut und ihre Zigarren in einer Fabrik in Danlí namens Tabacos Rancho Jamastran herstellt, sagt 2005, Sal Fontana sei 1992 zurückgekehrt und habe La Fontana auf den Markt gebracht. Ein Text von Cigar Storehouse bringt sie mit Tino Argudin in Verbindung, der Kuba mit Samen aus Pinar del Río verließ und auf dem Rancho Jamastran eine Mischung komponierte, die des Tabaks seiner Insel würdig war; Century Premium Cigars, Legend Cigars und eGars datieren sie auf 1993.

2008 kauft Oettinger Davidoff Camacho Cigars aus Danlí und Miami und mit ihr zehn Marken, darunter Baccarat und La Fontana. Im Mai 2017 eröffnet die neue Fabrik von Camacho, Diadema Cigars de Honduras, in Danlí und ersetzt AgroIndustrias Laepe; sie stellt die Mehrheit der Camacho her, und auch La Fontana. Im Oktober 2026 gibt die Gruppe auf ihrer Website an, La Fontana werde zusammen mit Camacho und Baccarat bei Agroindustrias Diadema Zona Franca Honduras SA in Danlí von Hand gerollt und anschließend in die Vereinigten Staaten und nach Europa exportiert.

Im Oktober 2026 beschreiben Legend Cigars und Cigar Storehouse La Fontana mit einem Deckblatt Connecticut, auf mexikanischem Umblatt und honduranischer Einlage, von milder bis mittlerer Stärke; 70Cigars gibt ein honduranisches Umblatt an. Cigar Storehouse und 70Cigars haben sie auf Lager, Legend Cigars und Cigarworld.de zeigen sie als ausverkauft an.',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"Goldenes Deckblatt Connecticut, auf mexikanischem Umblatt laut Legend Cigars und Cigar Storehouse, auf honduranischem laut 70Cigars, und honduranische Einlage; zehn Formate bei Century Premium Cigars, darunter Rossini (5 1/2 x 33), Puccini (6 1/2 x 44) und Michelangelo (7 1/2 x 52); milde bis mittlere Stärke, so Century Premium Cigars."}]',
        'La Fontana的起步有两种说法。Christian Eiroa的家族在洪都拉斯的贾马斯特兰山谷种植古巴种子烟草，并在丹利一家名为Tabacos Rancho Jamastran的工厂制造雪茄；他于2005年称，Sal Fontana于1992年回归并推出了La Fontana。Cigar Storehouse的一段文字则将其与Tino Argudin联系起来：他带着比那尔德里奥的种子离开古巴，在Rancho Jamastran调配出一款与家乡岛屿的烟草相称的拼配；Century Premium Cigars、Legend Cigars与eGars则将其定在1993年。

2008年，Oettinger Davidoff收购了丹利和迈阿密的Camacho Cigars，并随之获得十个品牌，其中包括Baccarat与La Fontana。2017年5月，Camacho的新工厂Diadema Cigars de Honduras在丹利开业，取代了AgroIndustrias Laepe；它生产大部分Camacho雪茄，也生产La Fontana。2026年10月，该集团在其网站上称，La Fontana与Camacho和Baccarat一样，在丹利的Agroindustrias Diadema Zona Franca Honduras SA手工卷制，随后出口至美国和欧洲。

2026年10月，Legend Cigars与Cigar Storehouse将La Fontana描述为Connecticut茄衣，配墨西哥茄套与洪都拉斯茄芯，力度温和至中等；70Cigars给出的则是洪都拉斯茄套。Cigar Storehouse与70Cigars备有现货，Legend Cigars与Cigarworld.de则显示已售罄。',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut（洪都拉斯）","vitolas":[],"story":"金色Connecticut茄衣，据Legend Cigars与Cigar Storehouse称配墨西哥茄套，据70Cigars称配洪都拉斯茄套，茄芯产自洪都拉斯；Century Premium Cigars列有十种规格，其中包括Rossini（5 1/2 x 33）、Puccini（6 1/2 x 44）与Michelangelo（7 1/2 x 52）；据Century Premium Cigars称力度温和至中等。"}]',
        'تُروى بدايات La Fontana بطريقتين. فيقول Christian Eiroa، الذي تزرع عائلته تبغًا من بذور كوبية في وادي جاماستران بهندوراس وتصنع سيجارها في مصنع في دانلي يُدعى Tabacos Rancho Jamastran، في عام 2005 إن Sal Fontana عاد في عام 1992 وأطلق La Fontana. وينسبها نص من Cigar Storehouse إلى Tino Argudin، الذي غادر كوبا ومعه بذور من بينار ديل ريو وأعدّ في Rancho Jamastran خلطة جديرة بتبغ جزيرته؛ وتؤرّخها Century Premium Cigars وLegend Cigars وeGars بعام 1993.

وفي عام 2008، تشتري Oettinger Davidoff شركة Camacho Cigars، من دانلي وميامي، ومعها عشر علامات، منها Baccarat وLa Fontana. وفي مايو 2017، يُفتتح مصنع Camacho الجديد، Diadema Cigars de Honduras، في دانلي ويحلّ محل AgroIndustrias Laepe؛ وهو يصنع معظم سيجار Camacho، ويصنع La Fontana أيضًا. وفي أكتوبر 2026، تقول المجموعة على موقعها إن La Fontana، مع Camacho وBaccarat، تُلفّ يدويًا لدى Agroindustrias Diadema Zona Franca Honduras SA في دانلي، ثم تُصدَّر إلى الولايات المتحدة وأوروبا.

وفي أكتوبر 2026، تصف Legend Cigars وCigar Storehouse La Fontana بغلاف Connecticut، على رباط مكسيكي وحشوة هندوراسية، بقوة من خفيفة إلى متوسطة؛ وتذكر 70Cigars رباطًا هندوراسيًا. وتحتفظ Cigar Storehouse و70Cigars بها في المخزون، بينما تعرضها Legend Cigars وCigarworld.de على أنها نافدة.',
        '[{"name":"Vintage","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (هندوراس)","vitolas":[],"story":"غلاف Connecticut ذهبي، على رباط مكسيكي بحسب Legend Cigars وCigar Storehouse، وهندوراسي بحسب 70Cigars، وحشوة هندوراسية؛ عشرة مقاسات لدى Century Premium Cigars، منها Rossini (5 1/2 x 33) وPuccini (6 1/2 x 44) وMichelangelo (7 1/2 x 52)؛ قوة من خفيفة إلى متوسطة، بحسب Century Premium Cigars."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

