INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Fortis Cigars',
        'nicaragua',
        '2023 — Fortis Cigar Company, Miami',
        'Estelí, Nicaragua — la maison ne nomme pas sa fabrique, seulement une collaboration avec A.J. Fernandez',
        'fortiscigars.com « Our Story » (1er octobre 2026 : la maison se dit fondée à Miami, en Floride, par des fondateurs qu''elle ne nomme pas ; pont entre la communauté du cigare de Floride du Sud et Estelí, Nicaragua ; Fortis, mot latin pour fort) ; fortiscigars.com « Gran Reserva » (1er octobre 2026 : depuis 2023, Fortis est passée d''un seul Maduro Toro à un portefeuille de plusieurs vitolas ; Gran Reserva façonnée à la main à Estelí, Nicaragua, en collaboration avec A.J. Fernandez ; quatre mélanges : Maduro Toro 6 x 56, force moyenne, et Maduro Robusto 5 x 56, force moyenne à pleine, cape San Andrés mexicaine maduro vieillie cinq ans, liant et tripe nicaraguayens ; Habano Toro 6 x 56, force moyenne, cape Habano équatorienne, liant et tripe nicaraguayens ; Connecticut Toro 6 x 56, force douce à moyenne, cape Connecticut shade équatorienne, liant de piloto dominicain et nicaraguayen, tripe dominicaine et nicaraguayenne ; copyright 2026 FORTIS Cigar Company LLC) ; neptunecigar.com « Fortis Cigars » (1er octobre 2026 : le détaillant tient à son catalogue Fortis Gran Reserva Connecticut, Fortis Gran Reserva Habano et Fortis Gran Reserva Maduro)',
        NULL,
        'Fortis Cigars est la marque de Fortis Cigar Company LLC. La maison dit avoir été fondée à Miami, en Floride, et ne nomme pas ses fondateurs ; son site écrit que, depuis 2023, Fortis est passée d''un seul Maduro Toro à un portefeuille de plusieurs vitolas. Elle donne son nom comme le mot latin pour fort.

Les cigares sont fabriqués à Estelí, au Nicaragua. La maison ne nomme pas la fabrique : elle dit les Gran Reserva façonnées à la main à Estelí, en collaboration avec A.J. Fernandez.

Le catalogue se réduit à la Gran Reserva, que la maison décline en octobre 2026 en trois mélanges : un Maduro en Toro et en Robusto, un Habano et un Connecticut en Toro, tous de calibre 56. Le Maduro porte une cape San Andrés mexicaine vieillie cinq ans, l''Habano une cape équatorienne et le Connecticut une cape Connecticut shade d''Équateur ; liants et tripes sont nicaraguayens, sauf au Connecticut, dont le liant est du piloto dominicain et nicaraguayen et la tripe dominicaine et nicaraguayenne. En octobre 2026, Neptune Cigars tient à son catalogue trois Gran Reserva, Connecticut, Habano et Maduro.',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro (Mexique)","vitolas":[],"story":"Cape San Andrés mexicaine maduro vieillie cinq ans, liant et tripe nicaraguayens, en Toro (6 x 56), de force moyenne, et en Robusto (5 x 56), de force moyenne à pleine, dit la maison."},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Équateur)","vitolas":[],"story":"Cape Habano équatorienne sur liant et tripe nicaraguayens, en Toro (6 x 56) de force moyenne, dit la maison."},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade (Équateur)","vitolas":[],"story":"Cape Connecticut shade équatorienne sur liant de piloto dominicain et nicaraguayen, tripe dominicaine et nicaraguayenne, en Toro (6 x 56) de force douce à moyenne, dit la maison."}]',
        'Fortis Cigars is the brand of Fortis Cigar Company LLC. The house says it was founded in Miami, Florida, and does not name its founders; its website writes that, since 2023, Fortis has gone from a single Maduro Toro to a portfolio of several vitolas. It gives its name as the Latin word for strong.

The cigars are made in Estelí, Nicaragua. The house does not name the factory: it says the Gran Reserva are made by hand in Estelí, in collaboration with A.J. Fernandez.

The catalogue is limited to the Gran Reserva, which the house offers in October 2026 in three blends: a Maduro in Toro and Robusto, a Habano and a Connecticut in Toro, all of ring gauge 56. The Maduro has a Mexican San Andrés wrapper aged five years, the Habano an Ecuadorian wrapper and the Connecticut a Connecticut shade wrapper from Ecuador; binders and fillers are Nicaraguan, except in the Connecticut, whose binder is Dominican and Nicaraguan piloto and whose filler is Dominican and Nicaraguan. In October 2026, Neptune Cigars carries three Gran Reserva in its catalogue, Connecticut, Habano and Maduro.',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro (Mexico)","vitolas":[],"story":"Mexican San Andrés maduro wrapper aged five years, Nicaraguan binder and filler, in Toro (6 x 56), of medium strength, and in Robusto (5 x 56), of medium to full strength, says the house."},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Ecuadorian Habano wrapper over a Nicaraguan binder and filler, in Toro (6 x 56) of medium strength, says the house."},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade (Ecuador)","vitolas":[],"story":"Ecuadorian Connecticut shade wrapper over a binder of Dominican and Nicaraguan piloto, Dominican and Nicaraguan filler, in Toro (6 x 56) of mild to medium strength, says the house."}]',
        'Fortis Cigars es la marca de Fortis Cigar Company LLC. La casa dice haber sido fundada en Miami, Florida, y no nombra a sus fundadores; su sitio web escribe que, desde 2023, Fortis ha pasado de un único Maduro Toro a una cartera de varias vitolas. La casa da su nombre como la palabra latina para fuerte.

Los puros se fabrican en Estelí, Nicaragua. La casa no nombra la fábrica: dice que las Gran Reserva están hechas a mano en Estelí, en colaboración con A.J. Fernandez.

El catálogo se limita a la Gran Reserva, que la casa presenta en octubre de 2026 en tres mezclas: un Maduro en Toro y en Robusto, un Habano y un Connecticut en Toro, todos de calibre 56. El Maduro lleva una capa San Andrés mexicana añejada cinco años, el Habano una capa ecuatoriana y el Connecticut una capa Connecticut shade de Ecuador; capotes y tripas son nicaragüenses, salvo en el Connecticut, cuyo capote es de piloto dominicano y nicaragüense y cuya tripa es dominicana y nicaragüense. En octubre de 2026, Neptune Cigars mantiene en su catálogo tres Gran Reserva, Connecticut, Habano y Maduro.',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro (México)","vitolas":[],"story":"Capa San Andrés maduro mexicana añejada cinco años, capote y tripa nicaragüenses, en Toro (6 x 56), de fuerza media, y en Robusto (5 x 56), de fuerza media a plena, dice la casa."},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Capa Habano ecuatoriana sobre capote y tripa nicaragüenses, en Toro (6 x 56) de fuerza media, dice la casa."},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade (Ecuador)","vitolas":[],"story":"Capa Connecticut shade ecuatoriana sobre capote de piloto dominicano y nicaragüense, tripa dominicana y nicaragüense, en Toro (6 x 56) de fuerza suave a media, dice la casa."}]',
        'Fortis Cigars ist die Marke der Fortis Cigar Company LLC. Das Haus gibt an, in Miami, Florida, gegründet worden zu sein, und nennt seine Gründer nicht; seine Website schreibt, Fortis sei seit 2023 von einem einzigen Maduro Toro zu einem Portfolio mehrerer Vitolas übergegangen. Es gibt seinen Namen als das lateinische Wort für stark an.

Die Zigarren werden in Estelí, Nicaragua, hergestellt. Das Haus nennt die Fabrik nicht: Es gibt an, die Gran Reserva würden in Estelí von Hand gefertigt, in Zusammenarbeit mit A.J. Fernandez.

Der Katalog beschränkt sich auf die Gran Reserva, die das Haus im Oktober 2026 in drei Mischungen anbietet: ein Maduro als Toro und als Robusto, ein Habano und ein Connecticut als Toro, alle im Ringmaß 56. Der Maduro trägt ein mexikanisches Deckblatt San Andrés, das fünf Jahre gereift ist, der Habano ein ecuadorianisches Deckblatt und der Connecticut ein Deckblatt Connecticut shade aus Ecuador; Umblätter und Einlagen sind nicaraguanisch, außer beim Connecticut, dessen Umblatt aus dominikanischem und nicaraguanischem piloto besteht und dessen Einlage dominikanisch und nicaraguanisch ist. Im Oktober 2026 führt Neptune Cigars drei Gran Reserva in seinem Katalog, Connecticut, Habano und Maduro.',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro (Mexiko)","vitolas":[],"story":"Mexikanisches Deckblatt San Andrés maduro, fünf Jahre gereift, nicaraguanisches Umblatt und nicaraguanische Einlage, als Toro (6 x 56) von mittlerer Stärke und als Robusto (5 x 56) von mittlerer bis voller Stärke, so das Haus."},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Ecuadorianisches Deckblatt Habano über nicaraguanischem Umblatt und nicaraguanischer Einlage, als Toro (6 x 56) von mittlerer Stärke, so das Haus."},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade (Ecuador)","vitolas":[],"story":"Ecuadorianisches Deckblatt Connecticut shade über einem Umblatt aus dominikanischem und nicaraguanischem piloto, dominikanische und nicaraguanische Einlage, als Toro (6 x 56) von milder bis mittlerer Stärke, so das Haus."}]',
        'Fortis Cigars是Fortis Cigar Company LLC的品牌。品牌方称其创立于佛罗里达州迈阿密，并未提供创始人的姓名；其网站写道，自2023年起，Fortis已从仅有一款Maduro Toro转为包含多种规格的产品组合。品牌方称其名称即拉丁语中表示强壮的词。

雪茄在尼加拉瓜的埃斯特利制造。品牌方未点明工厂名称：它称Gran Reserva在埃斯特利手工制作，并与A.J. Fernandez合作。

产品目录仅限于Gran Reserva，品牌方在2026年10月将其分为三种拼配：Maduro提供Toro与Robusto规格，Habano与Connecticut提供Toro规格，环径均为56。Maduro采用醇化五年的墨西哥San Andrés茄衣，Habano采用厄瓜多尔茄衣，Connecticut采用厄瓜多尔的Connecticut shade茄衣；茄套与茄芯均产自尼加拉瓜，Connecticut除外，其茄套为多米尼加与尼加拉瓜的piloto，茄芯产自多米尼加与尼加拉瓜。2026年10月，Neptune Cigars的目录中列有三款Gran Reserva，即Connecticut、Habano与Maduro。',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro（墨西哥）","vitolas":[],"story":"据品牌方称，茄衣为醇化五年的墨西哥San Andrés maduro，茄套与茄芯均产自尼加拉瓜，Toro（6 x 56）力度中等，Robusto（5 x 56）力度中等至浓郁。"},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"据品牌方称，茄衣为厄瓜多尔Habano，茄套与茄芯均产自尼加拉瓜，规格为Toro（6 x 56），力度中等。"},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade（厄瓜多尔）","vitolas":[],"story":"据品牌方称，茄衣为厄瓜多尔Connecticut shade，茄套为多米尼加与尼加拉瓜的piloto，茄芯产自多米尼加与尼加拉瓜，规格为Toro（6 x 56），力度温和至中等。"}]',
        'Fortis Cigars هي علامة Fortis Cigar Company LLC. وتقول الدار إنها تأسست في ميامي بولاية فلوريدا، ولا تسمّي مؤسسيها؛ ويكتب موقعها أن Fortis انتقلت منذ عام 2023 من Maduro Toro وحيد إلى محفظة من عدة مقاسات. وتقدّم الدار اسمها على أنه الكلمة اللاتينية التي تعني قويًّا.

يُصنع السيجار في إستيلي بنيكاراغوا. ولا تسمّي الدار المصنع: فهي تقول إن Gran Reserva مصنوعة يدويًا في إستيلي، بالتعاون مع A.J. Fernandez.

يقتصر الكتالوج على Gran Reserva، التي تقدّمها الدار في أكتوبر 2026 في ثلاث خلطات: Maduro بمقاسَي Toro وRobusto، وHabano وConnecticut بمقاس Toro، جميعها بعيار 56. ويحمل Maduro غلاف San Andrés مكسيكيًا معتّقًا خمس سنوات، ويحمل Habano غلافًا إكوادوريًا، ويحمل Connecticut غلاف Connecticut shade من الإكوادور؛ والروابط والحشوات نيكاراغوية، باستثناء Connecticut الذي رباطه من piloto دومينيكي ونيكاراغوي وحشوته دومينيكية ونيكاراغوية. وفي أكتوبر 2026، تحتفظ Neptune Cigars في كتالوجها بثلاثة من Gran Reserva، هي Connecticut وHabano وMaduro.',
        '[{"name":"Gran Reserva Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés maduro (المكسيك)","vitolas":[],"story":"غلاف San Andrés maduro مكسيكي معتّق خمس سنوات برباط وحشوة نيكاراغويين، بمقاس Toro (6 x 56) بقوة متوسطة، وبمقاس Robusto (5 x 56) بقوة من متوسطة إلى كاملة، بحسب الدار."},{"name":"Gran Reserva Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (الإكوادور)","vitolas":[],"story":"غلاف Habano إكوادوري فوق رباط وحشوة نيكاراغويين، بمقاس Toro (6 x 56) بقوة متوسطة، بحسب الدار."},{"name":"Gran Reserva Connecticut","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut shade (الإكوادور)","vitolas":[],"story":"غلاف Connecticut shade إكوادوري فوق رباط من piloto دومينيكي ونيكاراغوي، وحشوة دومينيكية ونيكاراغوية، بمقاس Toro (6 x 56) بقوة من خفيفة إلى متوسطة، بحسب الدار."}]')
