INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Onyx',
        'dominican',
        '2000 ou 1990 — Altadis U.S.A. (Onyx Reserve)',
        'Tabacalera de García, La Romana, Rép. dominicaine ; lignes Nicaragua chez A.J. Fernandez, Estelí',
        'altadisusa.com « Onyx » (2 octobre 2026, dit la maison : trois lignes, Onyx Reserve, Onyx Bold Nicaragua et Onyx Vintage Nicaragua ; Reserve de force moyenne à pleine ; Bold Nicaragua sous une cape San Andrés foncée sur des tabacs nicaraguayens vieillis plus de quatre ans) ; altadisusa.com « Onyx Reserve » (2 octobre 2026, dit la maison : origine République dominicaine ; cape Connecticut Broadleaf noircie, liant nicaraguayen, tripe dominicaine, nicaraguayenne et péruvienne ; cinq vitolas données en calibre puis longueur en pouces, Robusto 50 x 5, Toro 50 x 6, Churchill 50 x 7, No. 2 Belicoso 52 x 6 1/8, Torbusto 60 x 5 1/2, dont quatre pressées en carré ; fabrique non nommée) ; altadisusa.com « Onyx Bold Nicaragua » (2 octobre 2026, dit la maison : produite au Nicaragua ; cape San Andrés, liant nicaraguayen, tripe nicaraguayenne et dominicaine ; trois vitolas, Robusto 50 x 5, Toro 54 x 6, Magnum 60 x 6) ; altadisusa.com « Onyx Vintage Nicaragua » (2 octobre 2026, dit la maison : cape, liant et tripe du Nicaragua ; façonné chez AJ Fernandez, au Nicaragua ; Toro 54 x 6, Robusto 50 x 5, Magnum 60 x 6 ; boîtes de vingt) ; altadisusa.com « Cigar Brands » (2 octobre 2026 : le site d''Altadis U.S.A. présente seize marques, dont Casa de Garcia, Don Diego, Las Cabrillas et Onyx) ; cigaraficionado.com « Onyx Vintage Nicaragua Coming Next Month » (25 août 2023 : Onyx Reserve lancée en 2000, faite en République dominicaine à la Tabacalera de Garcia ; Vintage Nicaragua expédiée aux détaillants le 25 septembre, produite au Nicaragua par A.J. Fernandez sur des tabacs nicaraguayens, cape de la récolte 2019) ; cigaraficionado.com « Onyx Bold Nicaragua Coming Next Month » (7 juillet 2020 : un nouvel Onyx roulé par A.J. Fernandez au Nicaragua, en magasin en août ; cape San Andrés mexicaine ; liant et tripe du Nicaragua ; Robusto 5 x 50, Toro 6 x 54, Magnum 6 x 60) ; cigarjournal.com « Introducing extra-aged Tobacco Blend Onyx Vintage Nicaragua » (29 août 2023 : Vintage Nicaragua faite à Tabacalera AJ Fernandez, sortie le 25 septembre 2023, cape Habano du Nicaragua de la récolte 2019 ; Bold Nicaragua faite aussi à la fabrique AJ Fernandez ; Onyx Reserve faite à la Tabacalera de Garcia, en République dominicaine, lancée en 1990 selon l''article) ; cigar-coop.com « Onyx Vintage Nicaragua Toro by Altadis U.S.A. | Cigar Review » (28 mai 2024 : la marque remonte à 2000 avec Onyx Reserve ; Bold Nicaragua sortie en 2020, faite par AJ Fernandez, puis Vintage Nicaragua en 2023 ; fabrique Tabacalera AJ Fernandez Cigars de Nicaragua S.A. ; cape Habano du Nicaragua, millésime 2019) ; cigar-coop.com « A Visit to Tabacalera de Garcia | Feature Story » (10 septembre 2025 : la fabrique est à La Romana, en République dominicaine, près de Casa de Campo ; nouvelle usine ouverte en 2022) ; 70cigars.com « Onyx Vintage Nicaragua Toro » (2 octobre 2026, détaillant : façonné à Tabacalera AJ Fernandez, à Estelí, au Nicaragua, en collaboration entre Altadis U.S.A. et AJ Fernandez ; cape Habano de 2019) ; paylesscigarsandpipes.com « Onyx Bold Nicaragua » (2 octobre 2026, détaillant : fabrication confiée à A.J. Fernández dans sa fabrique au Nicaragua ; cape San Andrés mexicaine, liant nicaraguayen, tripe du Nicaragua et de République dominicaine ; force pleine ; trois vitolas) ; cigarsdirect.com « Buy Onyx Vintage Nicaragua Cigars Online & Save Big – Cigars Direct » (2 octobre 2026, détaillant : force moyenne à pleine ; cape Habano de la récolte 2019 ; mélange créé avec A.J. Fernandez)',
        NULL,
        'Onyx est une marque d''Altadis U.S.A., la maison de Don Diego et de Casa de Garcia, qui la présente sur son site en trois lignes : Onyx Reserve, Onyx Bold Nicaragua et Onyx Vintage Nicaragua. La marque se date du lancement d''Onyx Reserve : 2000 selon Cigar Coop et selon un article du 25 août 2023, 1990 selon un article du 29 août 2023.

Onyx Reserve, la ligne d''origine, est dominicaine, dit la maison ; deux articles d''août 2023 la disent roulée à la Tabacalera de García, que Cigar Coop situe à La Romana, près de Casa de Campo. La maison la dit de force moyenne à pleine, sous une cape Connecticut Broadleaf noircie, sur liant nicaraguayen et tripe dominicaine, nicaraguayenne et péruvienne, en cinq vitolas : Robusto, Toro, Churchill, No. 2 Belicoso et Torbusto.

Les deux lignes Nicaragua sont roulées chez A.J. Fernandez ; 70cigars.com situe à Estelí la fabrique de l''Onyx Vintage Nicaragua. Onyx Bold Nicaragua, annoncée en juillet 2020 pour une arrivée en magasin en août, porte une cape San Andrés foncée ; Cigar Coop la situe en 2020. Onyx Vintage Nicaragua, expédiée aux détaillants le 25 septembre 2023, est un puro nicaraguayen à cape de la récolte 2019. Chacune se décline en Robusto, Toro et Magnum. En octobre 2026, la maison tient les trois lignes à son catalogue.',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf noircie","vitolas":[],"story":"Cape Connecticut Broadleaf noircie sur liant nicaraguayen et tripe dominicaine, nicaraguayenne et péruvienne, de force moyenne à pleine, dit la maison, en cinq vitolas : Robusto (5 x 50), Toro (6 x 50), Churchill (7 x 50), No. 2 Belicoso (6 1/8 x 52) et Torbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape San Andrés foncée sur liant nicaraguayen, tripe nicaraguayenne et dominicaine, dit la maison, qui parle de tabacs nicaraguayens vieillis plus de quatre ans ; en trois vitolas, Robusto (5 x 50), Toro (6 x 54) et Magnum (6 x 60) ; force pleine, dit Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (Nicaragua, 2019)","vitolas":[],"story":"Cape, liant et tripe du Nicaragua, dit la maison, qui dit la ligne façonnée chez A.J. Fernandez ; cape Habano de la récolte 2019, dit Cigar Coop ; en trois vitolas, Robusto (5 x 50), Toro (6 x 54) et Magnum (6 x 60), en boîtes de vingt ; force moyenne à pleine, dit Cigars Direct."}]',
        'Onyx is a brand of Altadis U.S.A., the house of Don Diego and Casa de Garcia, which presents it on its website in three lines: Onyx Reserve, Onyx Bold Nicaragua and Onyx Vintage Nicaragua. The brand takes its date from the launch of Onyx Reserve: 2000 according to Cigar Coop and to an article of 25 August 2023, 1990 according to an article of 29 August 2023.

Onyx Reserve, the original line, is Dominican, says the house; two articles of August 2023 say it is rolled at the Tabacalera de García, which Cigar Coop places in La Romana, near Casa de Campo. The house says it is of medium-to-full strength, with a blackened Connecticut Broadleaf wrapper over a Nicaraguan binder and a Dominican, Nicaraguan and Peruvian filler, in five vitolas: Robusto, Toro, Churchill, No. 2 Belicoso and Torbusto.

The two Nicaragua lines are rolled at A.J. Fernandez; 70cigars.com places the factory of Onyx Vintage Nicaragua in Estelí. Onyx Bold Nicaragua, announced in July 2020 for arrival in shops in August, has a dark San Andrés wrapper; Cigar Coop places it in 2020. Onyx Vintage Nicaragua, shipped to retailers on 25 September 2023, is a Nicaraguan puro with a wrapper from the 2019 crop. Each comes in Robusto, Toro and Magnum. In October 2026, the house has the three lines in its catalogue.',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Black Connecticut Broadleaf","vitolas":[],"story":"Blackened Connecticut Broadleaf wrapper over a Nicaraguan binder and a Dominican, Nicaraguan and Peruvian filler, medium-to-full strength, says the house, in five vitolas: Robusto (5 x 50), Toro (6 x 50), Churchill (7 x 50), No. 2 Belicoso (6 1/8 x 52) and Torbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Dark San Andrés wrapper over a Nicaraguan binder, with a Nicaraguan and Dominican filler, says the house, which speaks of Nicaraguan tobaccos aged more than four years; in three vitolas, Robusto (5 x 50), Toro (6 x 54) and Magnum (6 x 60); full strength, says Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (Nicaragua, 2019)","vitolas":[],"story":"Wrapper, binder and filler from Nicaragua, says the house, which says the line is crafted at A.J. Fernandez; Habano wrapper from the 2019 crop, says Cigar Coop; in three vitolas, Robusto (5 x 50), Toro (6 x 54) and Magnum (6 x 60), in boxes of twenty; medium-to-full strength, says Cigars Direct."}]',
        'Onyx es una marca de Altadis U.S.A., la casa de Don Diego y de Casa de Garcia, que la presenta en su sitio web en tres líneas: Onyx Reserve, Onyx Bold Nicaragua y Onyx Vintage Nicaragua. La marca se fecha por el lanzamiento de Onyx Reserve: 2000 según Cigar Coop y según un artículo del 25 de agosto de 2023, 1990 según un artículo del 29 de agosto de 2023.

Onyx Reserve, la línea original, es dominicana, dice la casa; dos artículos de agosto de 2023 la dicen liada en la Tabacalera de García, que Cigar Coop sitúa en La Romana, cerca de Casa de Campo. La casa la dice de fuerza media a plena, con una capa Connecticut Broadleaf ennegrecida sobre capote nicaragüense y tripa dominicana, nicaragüense y peruana, en cinco vitolas: Robusto, Toro, Churchill, No. 2 Belicoso y Torbusto.

Las dos líneas Nicaragua se lían en A.J. Fernandez; 70cigars.com sitúa en Estelí la fábrica del Onyx Vintage Nicaragua. Onyx Bold Nicaragua, anunciada en julio de 2020 para su llegada a las tiendas en agosto, lleva una capa San Andrés oscura; Cigar Coop la sitúa en 2020. Onyx Vintage Nicaragua, enviada a los minoristas el 25 de septiembre de 2023, es un puro nicaragüense con capa de la cosecha de 2019. Cada una se ofrece en Robusto, Toro y Magnum. En octubre de 2026, la casa tiene las tres líneas en su catálogo.',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf negra","vitolas":[],"story":"Capa Connecticut Broadleaf ennegrecida sobre capote nicaragüense y tripa dominicana, nicaragüense y peruana, de fuerza media a plena, dice la casa, en cinco vitolas: Robusto (5 x 50), Toro (6 x 50), Churchill (7 x 50), No. 2 Belicoso (6 1/8 x 52) y Torbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (México)","vitolas":[],"story":"Capa San Andrés oscura sobre capote nicaragüense, con tripa nicaragüense y dominicana, dice la casa, que habla de tabacos nicaragüenses añejados más de cuatro años; en tres vitolas, Robusto (5 x 50), Toro (6 x 54) y Magnum (6 x 60); fuerza plena, dice Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (Nicaragua, 2019)","vitolas":[],"story":"Capa, capote y tripa de Nicaragua, dice la casa, que la dice elaborada en A.J. Fernandez; capa Habano de la cosecha de 2019, dice Cigar Coop; en tres vitolas, Robusto (5 x 50), Toro (6 x 54) y Magnum (6 x 60), en cajas de veinte; fuerza media a plena, dice Cigars Direct."}]',
        'Onyx ist eine Marke von Altadis U.S.A., dem Haus von Don Diego und Casa de Garcia, das sie auf seiner Website in drei Linien vorstellt: Onyx Reserve, Onyx Bold Nicaragua und Onyx Vintage Nicaragua. Die Marke wird nach dem Start von Onyx Reserve datiert: 2000 laut Cigar Coop und laut einem Artikel vom 25. August 2023, 1990 laut einem Artikel vom 29. August 2023.

Onyx Reserve, die ursprüngliche Linie, ist dominikanisch, so das Haus; zwei Artikel vom August 2023 geben an, sie werde in der Tabacalera de García gerollt, die Cigar Coop in La Romana, nahe Casa de Campo, verortet. Das Haus gibt sie mit mittlerer bis voller Stärke an, mit einem geschwärzten Deckblatt Connecticut Broadleaf über einem nicaraguanischen Umblatt und einer dominikanischen, nicaraguanischen und peruanischen Einlage, in fünf Vitolas: Robusto, Toro, Churchill, No. 2 Belicoso und Torbusto.

Die beiden Nicaragua-Linien werden bei A.J. Fernandez gerollt; 70cigars.com verortet die Fabrik der Onyx Vintage Nicaragua in Estelí. Onyx Bold Nicaragua, im Juli 2020 für die Ankunft in den Geschäften im August angekündigt, trägt ein dunkles Deckblatt San Andrés; Cigar Coop verortet sie im Jahr 2020. Onyx Vintage Nicaragua, am 25. September 2023 an die Einzelhändler versandt, ist ein nicaraguanischer puro mit einem Deckblatt aus der Ernte 2019. Jede gibt es in Robusto, Toro und Magnum. Im Oktober 2026 führt das Haus die drei Linien in seinem Katalog.',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf schwarz","vitolas":[],"story":"Geschwärztes Deckblatt Connecticut Broadleaf über einem nicaraguanischen Umblatt und einer dominikanischen, nicaraguanischen und peruanischen Einlage, mittlere bis volle Stärke, so das Haus, in fünf Vitolas: Robusto (5 x 50), Toro (6 x 50), Churchill (7 x 50), No. 2 Belicoso (6 1/8 x 52) und Torbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Dunkles Deckblatt San Andrés über einem nicaraguanischen Umblatt, mit nicaraguanischer und dominikanischer Einlage, so das Haus, das von nicaraguanischen Tabaken spricht, die mehr als vier Jahre gereift sind; in drei Vitolas, Robusto (5 x 50), Toro (6 x 54) und Magnum (6 x 60); volle Stärke, so Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (Nicaragua, 2019)","vitolas":[],"story":"Deckblatt, Umblatt und Einlage aus Nicaragua, so das Haus, das angibt, die Linie werde bei A.J. Fernandez gefertigt; Deckblatt Habano aus der Ernte 2019, so Cigar Coop; in drei Vitolas, Robusto (5 x 50), Toro (6 x 54) und Magnum (6 x 60), in Kisten zu zwanzig Stück; mittlere bis volle Stärke, so Cigars Direct."}]',
        'Onyx是Altadis U.S.A.的品牌，Altadis U.S.A.是Don Diego与Casa de Garcia的品牌方，在其网站上将Onyx呈现为三个系列：Onyx Reserve、Onyx Bold Nicaragua与Onyx Vintage Nicaragua。该品牌的日期取自Onyx Reserve的推出：据Cigar Coop和2023年8月25日的一篇文章，为2000年；据2023年8月29日的一篇文章，为1990年。

Onyx Reserve是原有的系列，据品牌方称，产自多米尼加；2023年8月的两篇文章称它在Tabacalera de García卷制，Cigar Coop称该厂位于拉罗马纳，靠近Casa de Campo。品牌方称其力度中等至饱满，茄衣为发黑的Connecticut Broadleaf，茄套产自尼加拉瓜，茄芯来自多米尼加、尼加拉瓜与秘鲁，共有五种规格：Robusto、Toro、Churchill、No. 2 Belicoso与Torbusto。

两个尼加拉瓜系列均在A.J. Fernandez卷制；70cigars.com称Onyx Vintage Nicaragua的工厂位于埃斯特利。Onyx Bold Nicaragua于2020年7月宣布，定于8月到店，使用深色San Andrés茄衣；Cigar Coop将其定在2020年。Onyx Vintage Nicaragua于2023年9月25日发运给零售商，是一款茄衣取自2019年收成的尼加拉瓜puro。它们各有Robusto、Toro与Magnum。2026年10月，品牌方的目录中列有这三个系列。',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"发黑的Connecticut Broadleaf","vitolas":[],"story":"发黑的Connecticut Broadleaf茄衣，配尼加拉瓜茄套，茄芯来自多米尼加、尼加拉瓜与秘鲁，力度中等至饱满，据品牌方称，共有五种规格：Robusto（5 x 50）、Toro（6 x 50）、Churchill（7 x 50）、No. 2 Belicoso（6 1/8 x 52）与Torbusto（5 1/2 x 60）。"},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"深色San Andrés茄衣，配尼加拉瓜茄套，茄芯来自尼加拉瓜与多米尼加，据品牌方称；品牌方还提到陈化超过四年的尼加拉瓜烟叶；有三种规格，即Robusto（5 x 50）、Toro（6 x 54）与Magnum（6 x 60）；据Payless Cigars and Pipes称，力度饱满。"},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano（尼加拉瓜，2019年）","vitolas":[],"story":"据品牌方称，茄衣、茄套与茄芯均产自尼加拉瓜，且该系列在A.J. Fernandez制作；据Cigar Coop称，茄衣为2019年收成的Habano；有三种规格，即Robusto（5 x 50）、Toro（6 x 54）与Magnum（6 x 60），每盒二十支；据Cigars Direct称，力度中等至饱满。"}]',
        'Onyx علامة لـAltadis U.S.A.، دار Don Diego وCasa de Garcia، التي تقدّمها على موقعها في ثلاثة خطوط هي Onyx Reserve وOnyx Bold Nicaragua وOnyx Vintage Nicaragua. وتُؤرَّخ العلامة بإطلاق Onyx Reserve: 2000 بحسب Cigar Coop وبحسب مقال بتاريخ 25 أغسطس 2023، و1990 بحسب مقال بتاريخ 29 أغسطس 2023.

Onyx Reserve، الخط الأصلي، دومينيكي، بحسب الدار؛ ويقول مقالان من أغسطس 2023 إنه يُلَفّ في Tabacalera de García، التي تضعها Cigar Coop في لا رومانا، قرب Casa de Campo. وتقول الدار إنه بقوة من متوسطة إلى كاملة، بغلاف Connecticut Broadleaf مُسوَّد فوق رباط نيكاراغوي وحشوة دومينيكية ونيكاراغوية وبيروية، في خمسة مقاسات: Robusto وToro وChurchill وNo. 2 Belicoso وTorbusto.

يُلَفّ الخطّان النيكاراغويان لدى A.J. Fernandez؛ ويضع 70cigars.com مصنع Onyx Vintage Nicaragua في إستيلي. أما Onyx Bold Nicaragua، التي أُعلن عنها في يوليو 2020 لوصولها إلى المتاجر في أغسطس، فتحمل غلافًا داكنًا من نوع San Andrés؛ وتضعها Cigar Coop في 2020. وأما Onyx Vintage Nicaragua، التي شُحنت إلى تجار التجزئة في 25 سبتمبر 2023، فهي puro نيكاراغوي بغلاف من محصول 2019. ويتوفر كل منهما في Robusto وToro وMagnum. وفي أكتوبر 2026، تُدرج الدار الخطوط الثلاثة في كتالوجها.',
        '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf مُسوَّد","vitolas":[],"story":"غلاف Connecticut Broadleaf مُسوَّد فوق رباط نيكاراغوي وحشوة دومينيكية ونيكاراغوية وبيروية، بقوة من متوسطة إلى كاملة، بحسب الدار، في خمسة مقاسات: Robusto (5 x 50) وToro (6 x 50) وChurchill (7 x 50) وNo. 2 Belicoso (6 1/8 x 52) وTorbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف San Andrés داكن فوق رباط نيكاراغوي وحشوة نيكاراغوية ودومينيكية، بحسب الدار التي تتحدث عن تبوغ نيكاراغوية معتّقة أكثر من أربع سنوات؛ في ثلاثة مقاسات هي Robusto (5 x 50) وToro (6 x 54) وMagnum (6 x 60)؛ وبقوة كاملة بحسب Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (نيكاراغوا، 2019)","vitolas":[],"story":"غلاف ورباط وحشوة من نيكاراغوا، بحسب الدار التي تقول إن الخط صُنع لدى A.J. Fernandez؛ وغلاف Habano من محصول 2019 بحسب Cigar Coop؛ في ثلاثة مقاسات هي Robusto (5 x 50) وToro (6 x 54) وMagnum (6 x 60)، في علب من عشرين سيجارة؛ وبقوة من متوسطة إلى كاملة بحسب Cigars Direct."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Red Anchor ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Red Anchor',
        'dominican',
        '1772, Delft — relancée en 2022 par United Cigars',
        'Chez Kelner Boutique Factory (KBF), Santiago, Rép. dominicaine',
        'unitedcigargroup.com « Red Anchor » (2 octobre 2026, dit la maison : marque établie en 1772 à Delft, aux Pays-Bas, restée en sommeil jusqu''à son acquisition par United Cigars, qui l''a relancée pour son 250e anniversaire ; partenariat avec la famille Kelner, aux racines néerlandaises et au savoir-faire dominicain ; cape Habano d''Équateur, liant de Monte Plata dominicain, tripe de Habano ''92 dominicain et des États-Unis ; force moyenne à pleine ; cinq vitolas en boîtes de vingt-cinq, Gunner 6 1/2 x 43, Captain 5 x 50, Admiral 6 x 52, Commodore 7 x 55 réservée aux événements, Cooper 4 1/2 x 43 ; fabrique non nommée) ; unitedcigargroup.com « About United Cigars | Trusted Since 1901, Built for Today''s Retailers » (2 octobre 2026, dit la maison : Red Anchor, Firecracker et La Gianna comptent parmi les marques mises en avant ; cigares faits avec des maîtres assembleurs du Honduras, de République dominicaine, du Nicaragua et du Costa Rica) ; cigar-coop.com « Cigar News: United Cigars to Relaunch Red Anchor at 2022 PCA Trade Show » (20 mai 2022 : Red Anchor, marque de Delft ; dépôt de marque en 1770 par une boutique de cigares ; autorisation donnée à Albertus Hillen le 22 février 1772 par les échevins de Delft de vendre ses cigares sous le nom de Red Anchor ; entreprise fermée en mars 1937 ; relance annoncée pour le salon PCA du 9 au 12 juillet 2022, à Las Vegas, pour le 250e anniversaire ; partenariat avec Hendrick Kelner et la Kelner Boutique Factory, en République dominicaine ; 250 boîtes de vingt-cinq ; une seule vitola, l''Admiral, annoncée en 6 x 54 ; autres vitolas prévues en 2023) ; cigardojo.com « Red Anchor Revived by United Cigars » (20 mai 2022 : marque née comme boutique de cigares en 1770 ; relance par United Cigars ; faite à la Kelner Boutique Factory, en République dominicaine ; une vitola en 2022, un 6 x 54, l''Admiral ; exposition prévue au salon PCA d''été, à Las Vegas) ; cigar-coop.com « Cigar Review: Red Anchor Admiral by United Cigars - Cigar Coop » (1er juin 2023 : David Garofalo a repris United Cigars et obtenu les droits de la marque ; relance en 2022 avec une vitola, quatre autres annoncées au PCA 2023, Gunner 6 1/2 x 43, Captain 5 x 50, Commodore 7 x 55 et Cooper 4 1/2 x 43 ; Admiral 6 x 52 ; fabrique KBF (Kelner Boutique Factory), en République dominicaine, dirigée par Hendrik Kelner Jr. ; cape Habano 2000 d''Équateur, liant de Monte Plata dominicain de la ferme Kelner, tripe de San Vicente et de Habano ''92 dominicains et de Pennsylvanie) ; cigaraficionado.com « Red Anchor Gets Two New Sizes » (8 août 2023 : United Cigars a acheté la marque en 2022 et l''a relancée avec l''Admiral ; Captain 5 x 50 et Gunner 6 1/2 x 43 ; partenariat avec la famille Kelner ; toutes les vitolas faites à la Kelner Boutique Factory, à Santiago ; cape Habano 2000 d''Équateur, liant et tripe dominicains et américains, en partie de fermes de la famille Kelner) ; premiumcigars.org « The Blend: United Cigars Red Anchor Captain » (3 janvier 2024 : Captain 5 x 50 ; cape Habano 2000 d''Équateur ; liant de Monte Plata dominicain de la ferme Kelner ; tripe de San Vicente et de Habano ''92 dominicains et de Pennsylvanie ; fait à la Kelner Boutique Factory, à Santiago, pour United Cigar Group)',
        NULL,
        'Red Anchor est une marque de Delft, aux Pays-Bas, que la maison, United Cigars, dit établie en 1772. Cigar Coop date de 1770 le dépôt de la marque par une boutique de cigares, du 22 février 1772 l''autorisation donnée par les échevins de Delft à Albertus Hillen de vendre ses cigares sous le nom de Red Anchor, et de mars 1937 la fermeture de l''entreprise.

United Cigars a acquis la marque restée en sommeil et l''a relancée pour son 250e anniversaire, dit la maison ; David Garofalo, qui a repris United Cigars, en a obtenu les droits, dit Cigar Coop. L''annonce date du 20 mai 2022, pour le salon PCA de Las Vegas, du 9 au 12 juillet 2022, avec une seule vitola, l''Admiral. La maison dit s''être associée à la famille Kelner, aux racines néerlandaises et au savoir-faire dominicain ; un article d''août 2023 dit toutes les vitolas roulées à la Kelner Boutique Factory, à Santiago, en République dominicaine.

En octobre 2026, la maison tient la marque à son catalogue, en boîtes de vingt-cinq, en cinq vitolas : Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, réservée aux événements) et Cooper (4 1/2 x 43). Elle donne une cape Habano d''Équateur, un liant de Monte Plata dominicain et une tripe de Habano ''92 dominicain et des États-Unis, de force moyenne à pleine. Red Anchor figure parmi les marques que la maison met en avant, avec Firecracker et La Gianna.',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Équateur)","vitolas":[],"story":"Cape Habano d''Équateur, liant de Monte Plata dominicain, tripe de Habano ''92 dominicain et des États-Unis, de force moyenne à pleine, dit la maison, en cinq vitolas : Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, réservée aux événements) et Cooper (4 1/2 x 43)."}]',
        'Red Anchor is a brand from Delft, in the Netherlands, which the house, United Cigars, says was established in 1772. Cigar Coop dates the registration of the brand by a cigar shop to 1770, the authorisation given by the aldermen of Delft to Albertus Hillen to sell his cigars under the name Red Anchor to 22 February 1772, and the closure of the business to March 1937.

United Cigars acquired the brand, which had lain dormant, and relaunched it for its 250th anniversary, says the house; David Garofalo, who took over United Cigars, obtained the rights to it, says Cigar Coop. The announcement dates from 20 May 2022, for the PCA show in Las Vegas, from 9 to 12 July 2022, with a single vitola, the Admiral. The house says it partnered with the Kelner family, of Dutch roots and Dominican know-how; an article of August 2023 says all the vitolas are rolled at the Kelner Boutique Factory, in Santiago, in the Dominican Republic.

In October 2026, the house has the brand in its catalogue, in boxes of twenty-five, in five vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, reserved for events) and Cooper (4 1/2 x 43). It gives an Ecuadorian Habano wrapper, a Dominican binder from Monte Plata and a filler of Dominican Habano ''92 and from the United States, of medium-to-full strength. Red Anchor is among the brands that the house highlights, with Firecracker and La Gianna.',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Ecuadorian Habano wrapper, Dominican binder from Monte Plata, filler of Dominican Habano ''92 and from the United States, medium-to-full strength, says the house, in five vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, reserved for events) and Cooper (4 1/2 x 43)."}]',
        'Red Anchor es una marca de Delft, en los Países Bajos, que la casa, United Cigars, dice establecida en 1772. Cigar Coop fecha en 1770 el registro de la marca por una tienda de puros, el 22 de febrero de 1772 la autorización dada por los regidores de Delft a Albertus Hillen para vender sus puros bajo el nombre de Red Anchor, y en marzo de 1937 el cierre de la empresa.

United Cigars adquirió la marca, que había permanecido inactiva, y la relanzó con motivo de su 250.º aniversario, dice la casa; David Garofalo, que se hizo cargo de United Cigars, obtuvo los derechos de la marca, dice Cigar Coop. El anuncio es del 20 de mayo de 2022, para la feria PCA de Las Vegas, del 9 al 12 de julio de 2022, con una sola vitola, el Admiral. La casa dice haberse asociado con la familia Kelner, de raíces neerlandesas y saber hacer dominicano; un artículo de agosto de 2023 dice que todas las vitolas se lían en la Kelner Boutique Factory, en Santiago, en República Dominicana.

En octubre de 2026, la casa tiene la marca en su catálogo, en cajas de veinticinco, en cinco vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, reservada a los eventos) y Cooper (4 1/2 x 43). Indica una capa Habano de Ecuador, un capote de Monte Plata dominicano y una tripa de Habano ''92 dominicano y de Estados Unidos, de fuerza media a plena. Red Anchor figura entre las marcas que la casa destaca, junto con Firecracker y La Gianna.',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Capa Habano de Ecuador, capote de Monte Plata dominicano, tripa de Habano ''92 dominicano y de Estados Unidos, de fuerza media a plena, dice la casa, en cinco vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, reservada a los eventos) y Cooper (4 1/2 x 43)."}]',
        'Red Anchor ist eine Marke aus Delft in den Niederlanden, die nach Angabe des Hauses, United Cigars, 1772 gegründet wurde. Cigar Coop datiert die Eintragung der Marke durch ein Zigarrengeschäft auf 1770, die Erlaubnis der Schöffen von Delft an Albertus Hillen, seine Zigarren unter dem Namen Red Anchor zu verkaufen, auf den 22. Februar 1772 und die Schließung des Unternehmens auf März 1937.

United Cigars hat die ruhende Marke erworben und zu ihrem 250-jährigen Jubiläum neu gestartet, so das Haus; David Garofalo, der United Cigars übernommen hat, hat die Rechte an der Marke erlangt, so Cigar Coop. Die Ankündigung stammt vom 20. Mai 2022, für die Messe PCA in Las Vegas vom 9. bis 12. Juli 2022, mit einer einzigen Vitola, der Admiral. Das Haus gibt an, sich mit der Familie Kelner zusammengetan zu haben, die niederländische Wurzeln und dominikanisches Know-how mitbringt; ein Artikel vom August 2023 gibt an, alle Vitolas würden in der Kelner Boutique Factory in Santiago in der Dominikanischen Republik gerollt.

Im Oktober 2026 führt das Haus die Marke in seinem Katalog, in Kisten zu fünfundzwanzig Stück, in fünf Vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, Veranstaltungen vorbehalten) und Cooper (4 1/2 x 43). Es nennt ein Deckblatt Habano aus Ecuador, ein dominikanisches Umblatt aus Monte Plata und eine Einlage aus dominikanischem Habano ''92 und aus den USA, von mittlerer bis voller Stärke. Red Anchor gehört zu den Marken, die das Haus hervorhebt, neben Firecracker und La Gianna.',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Deckblatt Habano aus Ecuador, dominikanisches Umblatt aus Monte Plata, Einlage aus dominikanischem Habano ''92 und aus den USA, mittlere bis volle Stärke, so das Haus, in fünf Vitolas: Gunner (6 1/2 x 43), Captain (5 x 50), Admiral (6 x 52), Commodore (7 x 55, Veranstaltungen vorbehalten) und Cooper (4 1/2 x 43)."}]',
        'Red Anchor是荷兰代尔夫特的品牌，品牌方United Cigars称其创立于1772年。Cigar Coop将一家雪茄店注册该品牌的时间定为1770年，将代尔夫特市政官员准许Albertus Hillen以Red Anchor之名销售其雪茄的时间定为1772年2月22日，将企业关闭的时间定为1937年3月。

United Cigars收购了处于休眠状态的该品牌，并为其250周年重新推出，据品牌方称；据Cigar Coop称，接手United Cigars的David Garofalo取得了该品牌的权利。公告发布于2022年5月20日，针对2022年7月9日至12日在拉斯维加斯举行的PCA展会，仅推出一种规格，即Admiral。品牌方称已与Kelner家族建立合作，该家族兼具荷兰的根源与多米尼加的技艺；2023年8月的一篇文章称所有规格都在多米尼加共和国圣地亚哥的Kelner Boutique Factory卷制。

2026年10月，品牌方的目录中列有该品牌，每盒二十五支，共有五种规格：Gunner（6 1/2 x 43）、Captain（5 x 50）、Admiral（6 x 52）、Commodore（7 x 55，专供活动）与Cooper（4 1/2 x 43）。品牌方给出的是厄瓜多尔Habano茄衣、多米尼加蒙特普拉塔的茄套，以及多米尼加Habano ''92与美国的茄芯，力度中等至饱满。Red Anchor位列品牌方重点推介的品牌之中，与Firecracker和La Gianna并列。',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Habano茄衣，多米尼加蒙特普拉塔的茄套，茄芯来自多米尼加Habano ''92与美国，力度中等至饱满，据品牌方称，共有五种规格：Gunner（6 1/2 x 43）、Captain（5 x 50）、Admiral（6 x 52）、Commodore（7 x 55，专供活动）与Cooper（4 1/2 x 43）。"}]',
        'Red Anchor علامة من دلفت في هولندا، تقول الدار، وهي United Cigars، إنها تأسست عام 1772. وتؤرّخ Cigar Coop بعام 1770 تسجيل العلامة من قبل متجر سيجار، وبتاريخ 22 فبراير 1772 الإذن الذي منحه أعضاء المجلس البلدي في دلفت لـAlbertus Hillen ببيع سيجاره تحت اسم Red Anchor، وبمارس 1937 إغلاق الشركة.

اشترت United Cigars العلامة التي ظلّت خاملة، وأعادت إطلاقها بمناسبة ذكراها الـ250، بحسب الدار؛ وحصل David Garofalo، الذي تولّى United Cigars، على حقوقها، بحسب Cigar Coop. ويعود الإعلان إلى 20 مايو 2022، لمعرض PCA في لاس فيغاس، من 9 إلى 12 يوليو 2022، مع مقاس واحد هو Admiral. وتقول الدار إنها أقامت شراكة مع عائلة Kelner، ذات الجذور الهولندية والدراية الدومينيكية؛ ويقول مقال من أغسطس 2023 إن جميع المقاسات تُلَفّ في Kelner Boutique Factory، في سانتياغو بجمهورية الدومينيكان.

وفي أكتوبر 2026، تُدرج الدار العلامة في كتالوجها، في علب من خمس وعشرين سيجارة، في خمسة مقاسات: Gunner (6 1/2 x 43) وCaptain (5 x 50) وAdmiral (6 x 52) وCommodore (7 x 55، مخصص للفعاليات) وCooper (4 1/2 x 43). وتذكر غلاف Habano من الإكوادور، ورباطًا دومينيكيًا من مونتي بلاتا، وحشوة من Habano ''92 دومينيكي ومن الولايات المتحدة، بقوة من متوسطة إلى كاملة. وتندرج Red Anchor ضمن العلامات التي تبرزها الدار، إلى جانب Firecracker وLa Gianna.',
        '[{"name":"Red Anchor","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (الإكوادور)","vitolas":[],"story":"غلاف Habano من الإكوادور، ورباط دومينيكي من مونتي بلاتا، وحشوة من Habano ''92 دومينيكي ومن الولايات المتحدة، بقوة من متوسطة إلى كاملة، بحسب الدار، في خمسة مقاسات: Gunner (6 1/2 x 43) وCaptain (5 x 50) وAdmiral (6 x 52) وCommodore (7 x 55، مخصص للفعاليات) وCooper (4 1/2 x 43)."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Secret Blend of Cuba ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Secret Blend of Cuba',
        'dominican',
        'Non précisée — Neptune Cigars',
        'Chez ABAM Cigars S.R.L. (Matías Maragoto), Villa Mella, Santo Domingo Norte (République dominicaine)',
        'neptunecigar.com « Secret Blend of Cuba Cigars - Neptune Cigar » (2 octobre 2026, détaillant : mixed filler de force douce à moyenne sous cape Connecticut Shade d''Équateur, origine République dominicaine, liant d''Indonésie, tripe dominicaine, roulée à la main ; fabricant Abam S.A., fabrique de Santo Domingo dirigée par José Matías Maragoto ; avis de clients de juin 2009 à mai 2025 ; le 21 octobre 2024, le détaillant répond qu''aucune date de retour n''est annoncée) ; neptunecigar.com « Secret Blend of Cuba Churchill 6″3/4 * 48 », « Secret Blend of Cuba Robusto 5″ * 48 », « Secret Blend of Cuba Mareva 5″ * 40 » et « Secret Blend of Cuba Corona 6″ * 46 » (2 octobre 2026, détaillant : quatre vitolas en paquets de vingt et à l''unité, toutes en rupture ; marque vendue en exclusivité chez Neptune ; roulage à la main, fabricant Abam S.A. ; force douce dans la fiche technique) ; neptunecigar.com « Abam, S.A. » (2 octobre 2026, détaillant : fabrique ABAM, à Santo Domingo, en République dominicaine, de José Matías Maragoto) ; cigaraficionado.com « ABAM, A Dominican Factory Off The Beaten Path » (22 février 2018 : ABAM à Santo Domingo, dans une zone franche du nord de la ville et non à Santiago, où se font la plupart des cigares dominicains ; fabrique ouverte en 1996 ; José Matías Maragoto en est propriétaire et l''exploite avec sa femme Aidee) ; cigarjournal.com « ABAM Cigars: Villiger''s Unknown Factory » (16 août 2018 : Matías Maragoto, Cubain en exil, dirige la fabrique avec sa femme Aidee et son frère José ; ouverte en 1996, déménagée en 1998 dans des locaux plus vastes ; 170 employés dont 80 torcedores) ; cigar-coop.com « Cigar News: Villiger Lounge Opens at ABAM Factory » (14 mars 2018 : adresse Zona Franca Industrial de Villa Mella, Nave 6, Buena Vista Primera, Villa Mella, Santo Domingo Norte, en République dominicaine ; fabrique de José Matías Maragoto) ; hemmys.de « Hemmy''s Zigarren - Berlin – Hemmy''s finest cigars & more » (page en allemand, 2 octobre 2026, dit la maison : les cigares Hemmy''s sont roulés entièrement à la main à la manufacture ABAM, à Santo Domingo, en République dominicaine)',
        NULL,
        'Secret Blend of Cuba est une marque que Neptune Cigars, détaillant, dit vendre en exclusivité ; sa page porte des avis de clients de juin 2009 à mai 2025. Il la dit roulée à la main en République dominicaine, chez ABAM, la fabrique de José Matías Maragoto : cape Connecticut Shade d''Équateur sur liant d''Indonésie et tripe dominicaine mêlée (mixed filler). En octobre 2026, il la tient à son catalogue en quatre vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) et Corona (6 x 46), toutes en rupture ; en octobre 2024, il répondait déjà à un client qu''aucune date de retour n''était annoncée.

ABAM a ouvert en 1996 à Santo Domingo, dans une zone franche du nord de la ville et non à Santiago, où se font la plupart des cigares dominicains, puis a déménagé en 1998 dans des locaux plus vastes, disent deux articles de 2018. Son adresse est la Zona Franca Industrial de Villa Mella, à Santo Domingo Norte. José Matías Maragoto, Cubain en exil, en est le propriétaire et la dirige avec sa femme Aidee ; en août 2018, elle employait 170 personnes, dont 80 torcedores.

ABAM roule aussi à la main les Hemmys, marque de Hemmy Garcia, à Santo Domingo, dit le site hemmys.de, en allemand.',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Cape Connecticut Shade d''Équateur sur liant d''Indonésie et tripe dominicaine mêlée, roulée à la main chez ABAM, dit Neptune Cigars, qui la dit douce dans sa fiche technique et douce à moyenne dans sa description ; en paquets de vingt ou à l''unité, en quatre vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) et Corona (6 x 46), toutes en rupture en octobre 2026."}]',
        'Secret Blend of Cuba is a brand that Neptune Cigars, a retailer, says it sells exclusively; its page carries customer reviews from June 2009 to May 2025. It says the brand is rolled by hand in the Dominican Republic, at ABAM, the factory of José Matías Maragoto: an Ecuadorian Connecticut Shade wrapper over an Indonesian binder and a Dominican mixed filler. In October 2026, it has the brand in its catalogue in four vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) and Corona (6 x 46), all out of stock; in October 2024, it was already replying to a customer that no return date was announced.

ABAM opened in 1996 in Santo Domingo, in a free zone in the north of the city and not in Santiago, where most Dominican cigars are made, then moved in 1998 to larger premises, say two articles of 2018. Its address is the Zona Franca Industrial de Villa Mella, in Santo Domingo Norte. José Matías Maragoto, a Cuban in exile, is its owner and runs it with his wife Aidee; in August 2018, it employed 170 people, including 80 torcedores.

ABAM also rolls the Hemmys by hand, a brand of Hemmy Garcia, in Santo Domingo, says the website hemmys.de, in German.',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Ecuadorian Connecticut Shade wrapper over an Indonesian binder and a Dominican mixed filler, rolled by hand at ABAM, says Neptune Cigars, which calls it mild in its technical sheet and mild to medium in its description; in packs of twenty or singly, in four vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) and Corona (6 x 46), all out of stock in October 2026."}]',
        'Secret Blend of Cuba es una marca que Neptune Cigars, minorista, dice vender en exclusiva; su página lleva opiniones de clientes de junio de 2009 a mayo de 2025. Dice que se lía a mano en República Dominicana, en ABAM, la fábrica de José Matías Maragoto: capa Connecticut Shade de Ecuador sobre capote de Indonesia y tripa dominicana mezclada (mixed filler). En octubre de 2026, la tiene en su catálogo en cuatro vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) y Corona (6 x 46), todas agotadas; en octubre de 2024, ya respondía a un cliente que no se anunciaba ninguna fecha de regreso.

ABAM abrió en 1996 en Santo Domingo, en una zona franca del norte de la ciudad y no en Santiago, donde se hace la mayor parte de los puros dominicanos, y se trasladó en 1998 a unas instalaciones más amplias, dicen dos artículos de 2018. Su dirección es la Zona Franca Industrial de Villa Mella, en Santo Domingo Norte. José Matías Maragoto, cubano en el exilio, es su propietario y la dirige con su esposa Aidee; en agosto de 2018, empleaba a 170 personas, entre ellas 80 torcedores.

ABAM también lía a mano los Hemmys, marca de Hemmy Garcia, en Santo Domingo, dice el sitio hemmys.de, en alemán.',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Capa Connecticut Shade de Ecuador sobre capote de Indonesia y tripa dominicana mezclada, liada a mano en ABAM, dice Neptune Cigars, que la dice suave en su ficha técnica y de suave a media en su descripción; en paquetes de veinte o por unidades, en cuatro vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) y Corona (6 x 46), todas agotadas en octubre de 2026."}]',
        'Secret Blend of Cuba ist eine Marke, die Neptune Cigars, ein Einzelhändler, nach eigenen Angaben exklusiv verkauft; auf seiner Seite finden sich Kundenmeinungen von Juni 2009 bis Mai 2025. Er gibt an, sie werde in der Dominikanischen Republik von Hand gerollt, bei ABAM, der Fabrik von José Matías Maragoto: Deckblatt Connecticut Shade aus Ecuador über einem Umblatt aus Indonesien und einer gemischten dominikanischen Einlage (mixed filler). Im Oktober 2026 führt er sie in seinem Katalog in vier Vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) und Corona (6 x 46), alle ausverkauft; im Oktober 2024 antwortete er bereits einem Kunden, es sei kein Datum für eine Rückkehr angekündigt.

ABAM hat 1996 in Santo Domingo eröffnet, in einer Freihandelszone im Norden der Stadt und nicht in Santiago, wo der Großteil der dominikanischen Zigarren hergestellt wird, und ist 1998 in größere Räumlichkeiten umgezogen, so zwei Artikel von 2018. Die Adresse lautet Zona Franca Industrial de Villa Mella in Santo Domingo Norte. José Matías Maragoto, ein Kubaner im Exil, ist ihr Eigentümer und leitet sie gemeinsam mit seiner Frau Aidee; im August 2018 beschäftigte sie 170 Personen, darunter 80 torcedores.

ABAM rollt außerdem in Santo Domingo von Hand die Hemmys, eine Marke von Hemmy Garcia, so die Website hemmys.de, auf Deutsch.',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Deckblatt Connecticut Shade aus Ecuador über einem Umblatt aus Indonesien und einer gemischten dominikanischen Einlage, bei ABAM von Hand gerollt, so Neptune Cigars, das sie in seinem Datenblatt als mild und in seiner Beschreibung als mild bis mittel angibt; in Paketen zu zwanzig oder einzeln, in vier Vitolas, Churchill (6 3/4 x 48), Robusto (5 x 48), Mareva (5 x 40) und Corona (6 x 46), alle im Oktober 2026 ausverkauft."}]',
        'Secret Blend of Cuba是一个品牌，零售商Neptune Cigars称其独家销售该品牌；该品牌的页面上有2009年6月至2025年5月的顾客评论。Neptune Cigars称该品牌在多米尼加共和国手工卷制，工厂为ABAM，即José Matías Maragoto的工厂：茄衣为厄瓜多尔Connecticut Shade，茄套来自印度尼西亚，茄芯为多米尼加混合茄芯（mixed filler）。2026年10月，其目录中列有该品牌的四种规格，即Churchill（6 3/4 x 48）、Robusto（5 x 48）、Mareva（5 x 40）与Corona（6 x 46），全部缺货；2024年10月，它已向一位顾客答复，称尚未宣布任何回归日期。

ABAM于1996年在圣多明各开业，位于该市北部的一处自由贸易区，而不是大多数多米尼加雪茄的制造地圣地亚哥，随后于1998年迁入更宽敞的场所，2018年的两篇文章如此称。其地址为Zona Franca Industrial de Villa Mella，位于Santo Domingo Norte。流亡的古巴人José Matías Maragoto是该厂的所有者，与妻子Aidee共同管理；2018年8月，该厂雇有170人，其中80人为torcedores。

ABAM还在圣多明各手工卷制Hemmys，这是Hemmy Garcia的品牌，据德语网站hemmys.de称。',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Connecticut Shade茄衣，配印度尼西亚茄套与多米尼加混合茄芯，在ABAM手工卷制，据Neptune Cigars称；该零售商在技术说明中称其力度温和，在描述中称其力度温和至中等；每包二十支或单支销售，有四种规格，即Churchill（6 3/4 x 48）、Robusto（5 x 48）、Mareva（5 x 40）与Corona（6 x 46），2026年10月全部缺货。"}]',
        'Secret Blend of Cuba علامة يقول تاجر التجزئة Neptune Cigars إنه يبيعها حصريًا؛ وتحمل صفحتها آراء عملاء من يونيو 2009 إلى مايو 2025. ويقول إنها تُلَفّ يدويًا في جمهورية الدومينيكان، لدى ABAM، مصنع José Matías Maragoto: غلاف Connecticut Shade من الإكوادور فوق رباط من إندونيسيا وحشوة دومينيكية مختلطة (mixed filler). وفي أكتوبر 2026، يُدرجها في كتالوجه في أربعة مقاسات هي Churchill (6 3/4 x 48) وRobusto (5 x 48) وMareva (5 x 40) وCorona (6 x 46)، وكلها نافدة؛ وفي أكتوبر 2024، كان يرد بالفعل على عميل بأنه لم يُعلَن عن أي موعد للعودة.

افتُتحت ABAM عام 1996 في سانتو دومينغو، في منطقة حرة شمال المدينة وليس في سانتياغو، حيث يُصنع معظم السيجار الدومينيكي، ثم انتقلت عام 1998 إلى مقر أوسع من مقرّها السابق، بحسب مقالين من 2018. وعنوانها هو Zona Franca Industrial de Villa Mella في Santo Domingo Norte. ويملكها José Matías Maragoto، وهو كوبي في المنفى، ويديرها مع زوجته Aidee؛ وفي أغسطس 2018، كانت توظّف 170 شخصًا، منهم 80 torcedores.

وتلفّ ABAM يدويًا أيضًا Hemmys، علامة Hemmy Garcia، في سانتو دومينغو، بحسب موقع hemmys.de باللغة الألمانية.',
        '[{"name":"Secret Blend of Cuba","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"غلاف Connecticut Shade من الإكوادور فوق رباط من إندونيسيا وحشوة دومينيكية مختلطة، تُلَفّ يدويًا لدى ABAM، بحسب Neptune Cigars، الذي يصفها بقوة خفيفة في بطاقته التقنية وبقوة من خفيفة إلى متوسطة في وصفه؛ في عبوات من عشرين سيجارة أو بالوحدة، في أربعة مقاسات هي Churchill (6 3/4 x 48) وRobusto (5 x 48) وMareva (5 x 40) وCorona (6 x 46)، وكلها نافدة في أكتوبر 2026."}]')
