-- ── Las Cabrillas ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Las Cabrillas',
        'honduras',
        'Non précisée — Altadis U.S.A.',
        'Honduras — la maison ne nomme pas sa fabrique',
        'altadisusa.com « Las Cabrillas » (2 octobre 2026, dit la maison : cigares disponibles en cape Natural et Maduro ; le Natural façonné à la main au Honduras sous une cape Connecticut shade rustique ; le Maduro sous une cape San Andrés Marrón) ; altadisusa.com « Las Cabrillas Natural » (2 octobre 2026, dit la maison : origine Honduras ; cape Connecticut Shade, liant et tripe de San Andrés ; saveurs épicées typiques des feuilles de la vallée de San Andrés Tuxtla ; quatre vitolas données en calibre puis longueur en pouces, Ponce de Leon 44 x 6 5/8, Cortez 50 x 4 3/4, De Soto 50 x 6 7/8, Balboa 54 x 7 1/2) ; altadisusa.com « Las Cabrillas Maduro » (2 octobre 2026, dit la maison : fait au Honduras ; cape San Andrés Marrón, liant de San Andrés, tripe mexicaine ; une seule vitola listée, Balboa Maduro 54 x 7 1/2) ; cigarworld.de « Buy Las Cabrillas cigars » (page en anglais, 2 octobre 2026, détaillant : série introduite le 15.06.2001 au catalogue ; onze vitolas, toutes épuisées ; fabrication totalmente a mano) ; cigarworld.de « Las Cabrillas Magellans » (page en anglais, 2 octobre 2026, détaillant : au catalogue depuis le 15.06.2001 ; origine Honduras ; totalmente a mano, longfiller ; épuisé) ; paylesscigarsandpipes.com « Las Cabrillas » (2 octobre 2026, détaillant : Natural façonné à la main au Honduras sous une cape Connecticut shade rustique, Maduro sous une cape San Andrés Marrón ; force moyenne ; Balboa, Cortez et Desoto en boîtes de quinze) ; cigarcentury.com « Las Cabrillas - Maduro - Balboa with Reviews - Century Premium Cigars » (2 octobre 2026, détaillant : Balboa Maduro 7 1/2 x 54, origine Honduras, force moyenne) ; cigarworld.com « Las Cabrillas Cigars | Cigar World » (2 octobre 2026, détaillant : Natural dit mellow-medium)',
        NULL,
        'Las Cabrillas est une marque qu''Altadis U.S.A. présente sur son site, en deux lignes, Natural et Maduro. La maison ne date pas sa création et ne nomme pas sa fabrique : elle dit le Natural façonné à la main au Honduras et le Maduro fait au Honduras. Cigarworld.de tient la série au catalogue depuis le 15 juin 2001 et la dit totalmente a mano, en longfiller.

Le Natural porte une cape Connecticut shade rustique sur liant et tripe de San Andrés ; la maison dit ses saveurs épicées typiques des feuilles de la vallée de San Andrés Tuxtla. Elle le propose en quatre vitolas : Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) et Balboa (7 1/2 x 54). Le Maduro, qu''elle dit habillé d''une cape San Andrés Marrón, a un liant de San Andrés et une tripe mexicaine ; elle n''en liste qu''une vitola, le Balboa (7 1/2 x 54). Payless Cigars and Pipes donne la série de force moyenne, CigarCentury le Balboa Maduro.

En octobre 2026, la maison tient Natural et Maduro à son catalogue ; Cigarworld.de, lui, donne épuisées les onze vitolas de la série qu''il liste.',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"Connecticut shade rustique","vitolas":[],"story":"Cape Connecticut shade rustique sur liant et tripe de San Andrés, façonné à la main au Honduras, en quatre vitolas, Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) et Balboa (7 1/2 x 54), dit la maison ; force moyenne, dit Payless Cigars and Pipes."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"Cape San Andrés Marrón sur liant de San Andrés et tripe mexicaine, fait au Honduras, dit la maison, qui ne liste que le Balboa Maduro (7 1/2 x 54) ; force moyenne, dit CigarCentury."}]',
        'Las Cabrillas is a brand that Altadis U.S.A. presents on its website, in two lines, Natural and Maduro. The house does not date its creation or name its factory: it says the Natural is crafted by hand in Honduras and the Maduro is made in Honduras. Cigarworld.de has had the series in its catalogue since 15 June 2001 and says it is totalmente a mano, in longfiller.

The Natural has a rustic Connecticut shade wrapper over a San Andrés binder and filler; the house says its spicy flavours are typical of the leaves of the San Andrés Tuxtla valley. It offers it in four vitolas: Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) and Balboa (7 1/2 x 54). The Maduro, which it says is dressed in a San Andrés Marrón wrapper, has a San Andrés binder and a Mexican filler; it lists only one vitola, the Balboa (7 1/2 x 54). Payless Cigars and Pipes gives the series as medium strength, CigarCentury the Balboa Maduro.

In October 2026, the house has Natural and Maduro in its catalogue; Cigarworld.de, for its part, gives the eleven vitolas of the series that it lists as sold out.',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"Rustic Connecticut shade","vitolas":[],"story":"Rustic Connecticut shade wrapper over a San Andrés binder and filler, crafted by hand in Honduras, in four vitolas, Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) and Balboa (7 1/2 x 54), says the house; medium strength, says Payless Cigars and Pipes."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"San Andrés Marrón wrapper over a San Andrés binder and a Mexican filler, made in Honduras, says the house, which lists only the Balboa Maduro (7 1/2 x 54); medium strength, says CigarCentury."}]',
        'Las Cabrillas es una marca que Altadis U.S.A. presenta en su sitio web, en dos líneas, Natural y Maduro. La casa no fecha su creación ni nombra su fábrica: dice el Natural elaborado a mano en Honduras y el Maduro hecho en Honduras. Cigarworld.de tiene la serie en su catálogo desde el 15 de junio de 2001 y la dice totalmente a mano, en longfiller.

El Natural lleva una capa Connecticut shade rústica sobre capote y tripa de San Andrés; la casa dice que sus sabores especiados son típicos de las hojas del valle de San Andrés Tuxtla. Lo ofrece en cuatro vitolas: Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) y Balboa (7 1/2 x 54). El Maduro, que la casa dice vestido con una capa San Andrés Marrón, tiene un capote de San Andrés y una tripa mexicana; de él solo enumera una vitola, el Balboa (7 1/2 x 54). Payless Cigars and Pipes da la serie como de fuerza media, CigarCentury el Balboa Maduro.

En octubre de 2026, la casa tiene Natural y Maduro en su catálogo; Cigarworld.de, por su parte, da por agotadas las once vitolas de la serie que enumera.',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"Connecticut shade rústica","vitolas":[],"story":"Capa Connecticut shade rústica sobre capote y tripa de San Andrés, elaborado a mano en Honduras, en cuatro vitolas, Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) y Balboa (7 1/2 x 54), dice la casa; fuerza media, dice Payless Cigars and Pipes."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"Capa San Andrés Marrón sobre capote de San Andrés y tripa mexicana, hecho en Honduras, dice la casa, que solo enumera el Balboa Maduro (7 1/2 x 54); fuerza media, dice CigarCentury."}]',
        'Las Cabrillas ist eine Marke, die Altadis U.S.A. auf seiner Website in zwei Linien vorstellt, Natural und Maduro. Das Haus datiert ihre Entstehung nicht und nennt ihre Fabrik nicht: Es gibt an, der Natural werde in Honduras von Hand gefertigt und der Maduro in Honduras hergestellt. Cigarworld.de führt die Serie seit dem 15. Juni 2001 im Katalog und gibt sie als totalmente a mano und als longfiller an.

Der Natural trägt ein rustikales Deckblatt Connecticut shade über Umblatt und Einlage von San Andrés; das Haus sagt, seine würzigen Aromen seien typisch für die Blätter des Tals von San Andrés Tuxtla. Es bietet ihn in vier Vitolas an: Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) und Balboa (7 1/2 x 54). Der Maduro, bei dem das Haus ein Deckblatt San Andrés Marrón angibt, hat ein Umblatt von San Andrés und eine mexikanische Einlage; davon listet es nur eine Vitola, den Balboa (7 1/2 x 54). Payless Cigars and Pipes gibt die Serie mit mittlerer Stärke an, CigarCentury den Balboa Maduro.

Im Oktober 2026 führt das Haus Natural und Maduro in seinem Katalog; Cigarworld.de dagegen gibt die elf Vitolas der Serie, die es listet, als ausverkauft an.',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"Connecticut shade, rustikal","vitolas":[],"story":"Rustikales Deckblatt Connecticut shade über Umblatt und Einlage von San Andrés, von Hand in Honduras gefertigt, in vier Vitolas, Ponce de Leon (6 5/8 x 44), Cortez (4 3/4 x 50), De Soto (6 7/8 x 50) und Balboa (7 1/2 x 54), so das Haus; mittlere Stärke, so Payless Cigars and Pipes."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"Deckblatt San Andrés Marrón über einem Umblatt von San Andrés und einer mexikanischen Einlage, in Honduras hergestellt, so das Haus, das nur den Balboa Maduro (7 1/2 x 54) listet; mittlere Stärke, so CigarCentury."}]',
        'Las Cabrillas是一个品牌，Altadis U.S.A.在其网站上将其呈现为两个系列，即Natural与Maduro。品牌方没有给出该品牌的创立日期，也没有点出工厂名称：品牌方称Natural在洪都拉斯手工制作，Maduro在洪都拉斯制作。Cigarworld.de的目录中自2001年6月15日起列有该系列，并称其为totalmente a mano，且采用longfiller。

Natural使用质朴的Connecticut shade茄衣，茄套与茄芯均为San Andrés；品牌方称其辛香风味是San Andrés Tuxtla山谷烟叶的典型特征。品牌方提供四种规格：Ponce de Leon（6 5/8 x 44）、Cortez（4 3/4 x 50）、De Soto（6 7/8 x 50）与Balboa（7 1/2 x 54）。Maduro据品牌方称披有San Andrés Marrón茄衣，茄套为San Andrés，茄芯产自墨西哥；品牌方仅列出一种规格，即Balboa（7 1/2 x 54）。Payless Cigars and Pipes称该系列力度中等，CigarCentury则称Balboa Maduro力度中等。

2026年10月，品牌方的目录中列有Natural与Maduro；Cigarworld.de则称其所列该系列的十一种规格全部售罄。',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"质朴的Connecticut shade","vitolas":[],"story":"质朴的Connecticut shade茄衣，茄套与茄芯均为San Andrés，在洪都拉斯手工制作，有四种规格，即Ponce de Leon（6 5/8 x 44）、Cortez（4 3/4 x 50）、De Soto（6 7/8 x 50）与Balboa（7 1/2 x 54），据品牌方称；据Payless Cigars and Pipes称，力度中等。"},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"San Andrés Marrón茄衣，配San Andrés茄套与墨西哥茄芯，在洪都拉斯制作，据品牌方称；品牌方仅列出Balboa Maduro（7 1/2 x 54）；据CigarCentury称，力度中等。"}]',
        'Las Cabrillas علامة تقدّمها Altadis U.S.A. على موقعها في خطّين هما Natural وMaduro. ولا تذكر الدار تاريخ إنشائها ولا تسمّي مصنعها: فهي تقول إن Natural مصنوع يدويًا في هندوراس، وإن Maduro مصنوع في هندوراس. ويُدرج Cigarworld.de السلسلة في كتالوجه منذ 15 يونيو 2001، ويقول إنها totalmente a mano، من نوع longfiller.

يحمل Natural غلافًا ريفيًا من Connecticut shade فوق رباط وحشوة من San Andrés؛ وتقول الدار إن نكهاته المتبّلة مميّزة لأوراق وادي San Andrés Tuxtla. وتقدّمه في أربعة مقاسات: Ponce de Leon (6 5/8 x 44) وCortez (4 3/4 x 50) وDe Soto (6 7/8 x 50) وBalboa (7 1/2 x 54). أما Maduro، الذي تقول الدار إنه مكسوّ بغلاف San Andrés Marrón، فله رباط من San Andrés وحشوة مكسيكية؛ ولا تُدرج منه سوى مقاس واحد هو Balboa (7 1/2 x 54). ويذكر Payless Cigars and Pipes أن السلسلة بقوة متوسطة، ويذكر CigarCentury ذلك عن Balboa Maduro.

وفي أكتوبر 2026، تُدرج الدار Natural وMaduro في كتالوجها؛ أما Cigarworld.de فيذكر أن المقاسات الأحد عشر للسلسلة التي يُدرجها نافدة.',
        '[{"name":"Natural","color":"#C9A96E","force":"Medium","wrapper":"Connecticut shade ريفي","vitolas":[],"story":"غلاف Connecticut shade ريفي فوق رباط وحشوة من San Andrés، صُنع يدويًا في هندوراس، في أربعة مقاسات هي Ponce de Leon (6 5/8 x 44) وCortez (4 3/4 x 50) وDe Soto (6 7/8 x 50) وBalboa (7 1/2 x 54)، بحسب الدار؛ وبقوة متوسطة بحسب Payless Cigars and Pipes."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés Marrón","vitolas":[],"story":"غلاف San Andrés Marrón فوق رباط من San Andrés وحشوة مكسيكية، صُنع في هندوراس، بحسب الدار التي لا تُدرج سوى Balboa Maduro (7 1/2 x 54)؛ وبقوة متوسطة بحسب CigarCentury."}]')
