SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Artista Cigars','Domaine de Lavalette','Domenico','Eladio Diaz','Flavoroute','God of Fire','Laura Chavin','Mustique','Don Emmanuel','Christo','El Mago','Emperors Cut','Firecracker','Gellis Family Cigars','La Unica','Herr Lehmann','La Fontana','La Gianna','Fortis Cigars','Drunk Chicken','Licenciados','Onyx','Red Anchor','Secret Blend of Cuba','Las Cabrillas')) = 25 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Artista Cigars"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Domaine de Lavalette"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Domenico"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Eladio Diaz"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"God of Fire"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Laura Chavin"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Mustique"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Don Emmanuel"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Emperors Cut"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Firecracker"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Gellis Family Cigars"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"La Unica"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Licenciados"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Onyx"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Red Anchor"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Secret Blend of Cuba"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Flavoroute"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Christo"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Herr Lehmann"') FROM `producer_countries` WHERE `id` = 'germany') AS germany_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"El Mago"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Fortis Cigars"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"La Fontana"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"La Gianna"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Las Cabrillas"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Drunk Chicken"') FROM `producer_countries` WHERE `id` = 'usa') AS usa_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Artista Cigars','Domaine de Lavalette','Domenico','Eladio Diaz','Flavoroute','God of Fire','Laura Chavin','Mustique','Don Emmanuel','Christo','El Mago','Emperors Cut','Firecracker','Gellis Family Cigars','La Unica','Herr Lehmann','La Fontana','La Gianna','Fortis Cigars','Drunk Chicken','Licenciados','Onyx','Red Anchor','Secret Blend of Cuba','Las Cabrillas')) = 250 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 245') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
